"use strict";
(function () {
  if (window.__MAGNOLIE_PLATFORM__ !== "windows") return;
  const variants = {
  "what-your-computer-needs": {
    "en": "<p><b>Magnolie Organizer</b> is available as a complete desktop application for Linux and Windows. This edition of the handbook describes the Windows version. <b>Magnolie Notes</b> adds mobile notes, tasks, and secure exchange through the Magnolienbaum on Android phones and tablets.</p><p>Magnolie Organizer for Windows runs on <b>64-bit Windows 10 or Windows 11</b>.</p><h3>Requirements</h3><ul><li><b>Operating system:</b> Windows 10 version 2004 or later, or Windows 11, in each case 64 bit</li><li><b>Memory:</b> 2 gigabytes is enough; 4 gigabytes provides plenty of room</li><li><b>Disk space:</b> about 230 megabytes for the self-contained application, plus space for your data</li><li><b>Display:</b> at least 1024 x 768 pixels</li><li><b>WebView2:</b> Microsoft Edge WebView2 Runtime, present on current Windows installations</li><li><b>Internet:</b> not required for day-to-day use; only online functions such as holidays, weather, maps, and update checks need a connection</li></ul><h3>Included components</h3><p>The application includes the required .NET runtime. Python and additional interface libraries do not need to be installed.</p><div class='merke'><b>Good to know</b>The Organizer works on your computer. Your entries leave it only when you explicitly use an online or sharing function.</div>",
    "de": "<p><b>Magnolie Organizer</b> ist als vollständige Desktop-Anwendung für Linux und Windows erhältlich. Diese Handbuchfassung beschreibt die Windows-Ausgabe. <b>Magnolie Notes</b> ergänzt sie auf Android-Smartphones und -Tablets um mobile Notizen, Aufgaben und den sicheren Austausch über den Magnolienbaum.</p><p>Magnolie Organizer für Windows läuft unter <b>Windows 10 oder Windows 11 (64 Bit)</b>.</p><h3>Voraussetzungen</h3><ul><li><b>Betriebssystem:</b> Windows 10 Version 2004 oder neuer beziehungsweise Windows 11, jeweils 64 Bit</li><li><b>Arbeitsspeicher:</b> 2 Gigabyte genügen; 4 Gigabyte bieten reichlich Spielraum</li><li><b>Speicherplatz:</b> etwa 230 Megabyte für die selbstenthaltende Anwendung, zusätzlich Platz für Ihre Daten</li><li><b>Bildschirm:</b> mindestens 1024 x 768 Bildpunkte</li><li><b>WebView2:</b> die Microsoft Edge WebView2 Runtime, die bei aktuellen Windows-Installationen vorhanden ist</li><li><b>Internet:</b> für die tägliche Arbeit nicht erforderlich; nur Online-Funktionen wie Feiertage, Wetter, Karten und Aktualisierungsprüfungen benötigen eine Verbindung</li></ul><h3>Mitgelieferte Komponenten</h3><p>Die Anwendung bringt die benötigte .NET-Laufzeit selbst mit. Python oder zusätzliche Oberflächenbibliotheken müssen nicht installiert werden.</p><div class='merke'><b>Gut zu wissen</b>Der Organizer arbeitet auf Ihrem Computer. Ihre Einträge verlassen ihn nur, wenn Sie ausdrücklich eine Online- oder Weitergabefunktion verwenden.</div>",
    "ar": "<p>يتوفر <b>Magnolie Organizer</b> كتطبيق سطح مكتب متكامل لنظامي Linux وWindows. تصف هذه الطبعة من الدليل إصدار Windows. يضيف <b>Magnolie Notes</b> الملاحظات والمهام المحمولة والتبادل الآمن عبر Magnolienbaum على هواتف Android وأجهزته اللوحية.</p><p>يعمل Magnolie Organizer لنظام Windows على <b>Windows 10 أو Windows 11 بإصدار 64 بت</b>.</p><h3>المتطلبات</h3><ul><li><b>نظام التشغيل:</b> Windows 10 الإصدار 2004 أو أحدث، أو Windows 11، وفي الحالتين 64 بت</li><li><b>الذاكرة:</b> تكفي سعة 2 غيغابايت؛ وتوفر 4 غيغابايت مساحة مريحة</li><li><b>مساحة القرص:</b> نحو 230 ميغابايت للتطبيق المستقل، بالإضافة إلى مساحة لبياناتك</li><li><b>الشاشة:</b> 1024 x 768 بكسل على الأقل</li><li><b>WebView2:</b> Microsoft Edge WebView2 Runtime، وهو موجود في عمليات تثبيت Windows الحالية</li><li><b>الإنترنت:</b> غير مطلوب للاستخدام اليومي؛ ولا تحتاج إلى اتصال سوى الوظائف المتصلة بالإنترنت، مثل العطلات والطقس والخرائط والتحقق من التحديثات</li></ul><h3>المكونات المضمنة</h3><p>يتضمن التطبيق بيئة تشغيل .NET المطلوبة. ولا يلزم تثبيت Python أو مكتبات واجهة إضافية.</p><div class='merke'><b>من المفيد أن تعرف</b>يعمل Organizer على حاسوبك. ولا تغادر إدخالاتك الحاسوب إلا عندما تستخدم صراحة وظيفة متصلة بالإنترنت أو وظيفة مشاركة.</div>",
    "be": "<p><b>Magnolie Organizer</b> даступны як паўнавартасная настольная праграма для Linux і Windows. Гэтае выданне даведніка апісвае версію для Windows. <b>Magnolie Notes</b> дадае мабільныя нататкі, заданні і бяспечны абмен праз Magnolienbaum на тэлефонах і планшэтах Android.</p><p>Magnolie Organizer для Windows працуе ў <b>64-разраднай Windows 10 або Windows 11</b>.</p><h3>Патрабаванні</h3><ul><li><b>Аперацыйная сістэма:</b> Windows 10 версіі 2004 або навейшай ці Windows 11, у абодвух выпадках 64-разрадная</li><li><b>Памяць:</b> дастаткова 2 гігабайтаў; 4 гігабайты даюць вялікі запас</li><li><b>Месца на дыску:</b> каля 230 мегабайтаў для аўтаномнай праграмы і дадатковае месца для вашых даных</li><li><b>Дысплей:</b> не менш за 1024 x 768 пікселяў</li><li><b>WebView2:</b> Microsoft Edge WebView2 Runtime, наяўны ў сучасных усталяваннях Windows</li><li><b>Інтэрнэт:</b> для штодзённай працы не патрэбны; злучэнне патрабуюць толькі анлайн-функцыі, напрыклад святы, надвор’е, карты і праверка абнаўленняў</li></ul><h3>Уключаныя кампаненты</h3><p>Праграма змяшчае патрэбнае асяроддзе выканання .NET. Python і дадатковыя бібліятэкі інтэрфейсу ўсталёўваць не трэба.</p><div class='merke'><b>Карысна ведаць</b>Organizer працуе на вашым камп’ютары. Вашы запісы пакідаюць яго толькі тады, калі вы яўна карыстаецеся анлайн-функцыяй або функцыяй абмену.</div>",
    "cs": "<p><b>Magnolie Organizer</b> je k dispozici jako úplná desktopová aplikace pro Linux a Windows. Toto vydání příručky popisuje verzi pro Windows. <b>Magnolie Notes</b> přidává mobilní poznámky, úkoly a bezpečnou výměnu prostřednictvím Magnolienbaum na telefonech a tabletech s Androidem.</p><p>Magnolie Organizer pro Windows běží v <b>64bitových Windows 10 nebo Windows 11</b>.</p><h3>Požadavky</h3><ul><li><b>Operační systém:</b> Windows 10 verze 2004 nebo novější či Windows 11, vždy 64bitový</li><li><b>Paměť:</b> stačí 2 gigabajty; 4 gigabajty poskytují dostatek prostoru</li><li><b>Místo na disku:</b> přibližně 230 megabajtů pro samostatnou aplikaci a další místo pro vaše data</li><li><b>Displej:</b> nejméně 1024 x 768 pixelů</li><li><b>WebView2:</b> Microsoft Edge WebView2 Runtime, který je součástí aktuálních instalací Windows</li><li><b>Internet:</b> pro každodenní používání není nutný; připojení vyžadují jen online funkce jako svátky, počasí, mapy a kontroly aktualizací</li></ul><h3>Obsažené součásti</h3><p>Aplikace obsahuje potřebné běhové prostředí .NET. Python ani další knihovny rozhraní není třeba instalovat.</p><div class='merke'><b>Je dobré vědět</b>Organizer pracuje ve vašem počítači. Vaše záznamy jej opustí pouze tehdy, když výslovně použijete online funkci nebo funkci sdílení.</div>",
    "da": "<p><b>Magnolie Organizer</b> findes som et komplet skrivebordsprogram til Linux og Windows. Denne udgave af håndbogen beskriver Windows-versionen. <b>Magnolie Notes</b> tilføjer mobile noter, opgaver og sikker udveksling via Magnolienbaum på Android-telefoner og -tablets.</p><p>Magnolie Organizer til Windows kører på <b>64-bit Windows 10 eller Windows 11</b>.</p><h3>Krav</h3><ul><li><b>Styresystem:</b> Windows 10 version 2004 eller nyere, eller Windows 11, i begge tilfælde 64-bit</li><li><b>Hukommelse:</b> 2 gigabyte er nok; 4 gigabyte giver rigelig plads</li><li><b>Diskplads:</b> omkring 230 megabyte til det selvstændige program plus plads til dine data</li><li><b>Skærm:</b> mindst 1024 × 768 billedpunkter</li><li><b>WebView2:</b> Microsoft Edge WebView2 Runtime, som findes på nuværende Windows-installationer</li><li><b>Internet:</b> ikke nødvendigt til daglig brug; kun onlinefunktioner som helligdage, vejr, kort og opdateringskontrol kræver en forbindelse</li></ul><h3>Medfølgende komponenter</h3><p>Programmet indeholder den nødvendige .NET-runtime. Python og yderligere grænsefladebiblioteker skal ikke installeres.</p><div class='merke'><b>Godt at vide</b>Organizeren arbejder på din computer. Dine indtastninger forlader den kun, hvis du udtrykkeligt bruger en online- eller delefunktion.</div>",
    "es": "<p><b>Magnolie Organizer</b> está disponible como aplicación de escritorio completa para Linux y Windows. Esta edición del manual describe la versión de Windows. <b>Magnolie Notes</b> añade notas móviles, tareas e intercambio seguro a través del Magnolienbaum en teléfonos y tabletas Android.</p><p>Magnolie Organizer para Windows funciona en <b>Windows 10 o Windows 11 de 64 bits</b>.</p><h3>Requisitos</h3><ul><li><b>Sistema operativo:</b> Windows 10 versión 2004 o posterior, o Windows 11, en ambos casos de 64 bits</li><li><b>Memoria:</b> 2 gigabytes bastan; 4 gigabytes ofrecen un margen holgado</li><li><b>Espacio en disco:</b> unos 230 megabytes para la aplicación autónoma, más el espacio necesario para sus datos</li><li><b>Pantalla:</b> al menos 1024 × 768 píxeles</li><li><b>WebView2:</b> Microsoft Edge WebView2 Runtime, presente en las instalaciones actuales de Windows</li><li><b>Internet:</b> no es necesario para el uso diario; solo las funciones en línea, como festivos, tiempo meteorológico, mapas y comprobación de actualizaciones, necesitan conexión</li></ul><h3>Componentes incluidos</h3><p>La aplicación incluye el entorno de ejecución .NET necesario. No hace falta instalar Python ni bibliotecas de interfaz adicionales.</p><div class='merke'><b>Conviene saberlo</b>El Organizador trabaja en su ordenador. Sus entradas solo salen de él si utiliza expresamente una función en línea o de compartición.</div>",
    "fr": "<p><b>Magnolie Organizer</b> est disponible comme application de bureau complète pour Linux et Windows. Cette édition du manuel décrit la version Windows. <b>Magnolie Notes</b> y ajoute des notes mobiles, des tâches et l’échange sécurisé via le Magnolienbaum sur les téléphones et tablettes Android.</p><p>Magnolie Organizer pour Windows fonctionne sous <b>Windows 10 ou Windows 11 en 64 bits</b>.</p><h3>Configuration requise</h3><ul><li><b>Système d’exploitation :</b> Windows 10 version 2004 ou version ultérieure, ou Windows 11, dans les deux cas en 64 bits</li><li><b>Mémoire :</b> 2 gigaoctets suffisent ; 4 gigaoctets offrent une marge confortable</li><li><b>Espace disque :</b> environ 230 mégaoctets pour l’application autonome, auxquels s’ajoute l’espace nécessaire à vos données</li><li><b>Affichage :</b> au moins 1024 × 768 pixels</li><li><b>WebView2 :</b> Microsoft Edge WebView2 Runtime, présent sur les installations Windows actuelles</li><li><b>Internet :</b> non requis pour l’utilisation quotidienne ; seules les fonctions en ligne telles que les jours fériés, la météo, les cartes et la recherche de mises à jour nécessitent une connexion</li></ul><h3>Composants inclus</h3><p>L’application intègre le runtime .NET nécessaire. Python et les bibliothèques d’interface supplémentaires n’ont pas besoin d’être installés.</p><div class='merke'><b>Bon à savoir</b>L’Organizer fonctionne sur votre ordinateur. Vos saisies ne le quittent que si vous utilisez explicitement une fonction en ligne ou de partage.</div>",
    "hi": "<p><b>Magnolie Organizer</b> Linux और Windows के लिए एक संपूर्ण डेस्कटॉप एप्लिकेशन के रूप में उपलब्ध है। पुस्तिका का यह संस्करण Windows संस्करण का वर्णन करता है। <b>Magnolie Notes</b> Android फ़ोन और टैबलेट पर मोबाइल नोट्स, कार्य और Magnolienbaum के माध्यम से सुरक्षित आदान-प्रदान की सुविधा जोड़ता है।</p><p>Windows के लिए Magnolie Organizer <b>64-बिट Windows 10 या Windows 11</b> पर चलता है।</p><h3>आवश्यकताएँ</h3><ul><li><b>ऑपरेटिंग सिस्टम:</b> Windows 10 संस्करण 2004 या बाद का, अथवा Windows 11, दोनों में 64 बिट</li><li><b>मेमोरी:</b> 2 गीगाबाइट पर्याप्त है; 4 गीगाबाइट भरपूर जगह देता है</li><li><b>डिस्क स्थान:</b> स्व-निहित एप्लिकेशन के लिए लगभग 230 मेगाबाइट, साथ ही आपके डेटा के लिए स्थान</li><li><b>डिस्प्ले:</b> कम से कम 1024 x 768 पिक्सेल</li><li><b>WebView2:</b> Microsoft Edge WebView2 Runtime, जो वर्तमान Windows इंस्टॉलेशन में मौजूद होता है</li><li><b>इंटरनेट:</b> रोजमर्रा के उपयोग के लिए आवश्यक नहीं; केवल छुट्टियाँ, मौसम, नक्शे और अपडेट जाँच जैसे ऑनलाइन कार्यों को कनेक्शन चाहिए</li></ul><h3>शामिल घटक</h3><p>एप्लिकेशन में आवश्यक .NET रनटाइम शामिल है। Python और अतिरिक्त इंटरफ़ेस लाइब्रेरी इंस्टॉल करने की आवश्यकता नहीं है।</p><div class='merke'><b>जानने योग्य बात</b>Organizer आपके कंप्यूटर पर काम करता है। आपकी प्रविष्टियाँ केवल तभी इससे बाहर जाती हैं जब आप स्पष्ट रूप से किसी ऑनलाइन या साझा करने वाले कार्य का उपयोग करते हैं।</div>",
    "hsb": "<p><b>Magnolie Organizer</b> steji jako dospołne desktopowe nałoženje za Linux a Windows k dispoziciji. Tute wudaće přiručki wopisuje wersiju za Windows. <b>Magnolie Notes</b> přidawa mobilne noticy, nadawki a wěstu wuměnu přez Magnolienbaum na telefonach a tabletach z Androidom.</p><p>Magnolie Organizer za Windows běži pod <b>64-bitowym Windows 10 abo Windows 11</b>.</p><h3>Žadanja</h3><ul><li><b>Dźěłowy system:</b> Windows 10, wersija 2004 abo nowša, abo Windows 11, kóždy raz 64-bitowy</li><li><b>Skład:</b> 2 gigabajty dosahaja; 4 gigabajty skićeja wjele rezerwy</li><li><b>Tačelowy rum:</b> něhdźe 230 megabajtow za samostatne nałoženje a přidatny rum za waše daty</li><li><b>Wobrazowka:</b> znajmjeńša 1024 x 768 pikselow</li><li><b>WebView2:</b> Microsoft Edge WebView2 Runtime, kotryž je w aktualnych instalacijach Windows</li><li><b>Internet:</b> za wšědne dźěło njetrjebny; jenož online-funkcije kaž swjate dny, wjedro, karty a kontrola aktualizacijow trjebaja zwisk</li></ul><h3>Sobudodate komponenty</h3><p>Nałoženje wobsahuje trěbne běžne wokoliny .NET. Python a přidatne biblioteki powjercha njetrjebaće instalować.</p><div class='merke'><b>Derje wědźeć</b>Organizer dźěła na wašim ličaku. Waše zapiski jón jenož wopušća, hdyž wuraznje online-funkciju abo funkciju dźělenja wužiwaće.</div>",
    "it": "<p><b>Magnolie Organizer</b> è disponibile come applicazione desktop completa per Linux e Windows. Questa edizione del manuale descrive la versione per Windows. <b>Magnolie Notes</b> vi aggiunge note, attività e scambio sicuro tramite il Magnolienbaum su telefoni e tablet Android.</p><p>Magnolie Organizer per Windows funziona su <b>Windows 10 o Windows 11 a 64 bit</b>.</p><h3>Requisiti</h3><ul><li><b>Sistema operativo:</b> Windows 10 versione 2004 o successiva, oppure Windows 11, in entrambi i casi a 64 bit</li><li><b>Memoria:</b> 2 gigabyte bastano; 4 gigabyte offrono ampio margine</li><li><b>Spazio su disco:</b> circa 230 megabyte per l'applicazione autonoma, più lo spazio per i vostri dati</li><li><b>Schermo:</b> almeno 1024 × 768 pixel</li><li><b>WebView2:</b> Microsoft Edge WebView2 Runtime, presente nelle installazioni Windows attuali</li><li><b>Internet:</b> non necessario per l'uso quotidiano; solo le funzioni online come festività, meteo, mappe e controllo degli aggiornamenti richiedono una connessione</li></ul><h3>Componenti inclusi</h3><p>L'applicazione include il runtime .NET necessario. Non occorre installare Python né altre librerie di interfaccia.</p><div class='merke'><b>Buono a sapersi</b>L'Organizer lavora sul vostro computer. Le vostre voci lo lasciano solo se utilizzate espressamente una funzione online o di condivisione.</div>",
    "ja": "<p><b>Magnolie Organizer</b> は、Linux および Windows 向けの完全なデスクトップアプリケーションとして提供されています。この版のハンドブックでは Windows 版について説明します。<b>Magnolie Notes</b> を使うと、Android スマートフォンやタブレットでモバイル用のメモやタスクを利用し、Magnolienbaum を介して安全に交換できます。</p><p>Windows 版 Magnolie Organizer は <b>64 ビット版 Windows 10 または Windows 11</b> で動作します。</p><h3>要件</h3><ul><li><b>オペレーティングシステム：</b>64 ビット版 Windows 10 バージョン 2004 以降、または 64 ビット版 Windows 11</li><li><b>メモリ：</b>2 ギガバイトで十分です。4 ギガバイトあれば余裕があります</li><li><b>ディスク領域：</b>自己完結型アプリケーションに約 230 メガバイト、およびデータ用の領域</li><li><b>ディスプレイ：</b>1024 x 768 ピクセル以上</li><li><b>WebView2：</b>現行の Windows 環境に備わっている Microsoft Edge WebView2 Runtime</li><li><b>インターネット：</b>日常的な使用には不要です。祝日、天気、地図、更新の確認などのオンライン機能だけが接続を必要とします</li></ul><h3>同梱コンポーネント</h3><p>必要な .NET ランタイムはアプリケーションに含まれています。Python や追加のインターフェースライブラリをインストールする必要はありません。</p><div class='merke'><b>知っておくと便利なこと</b>Organizer はお使いのコンピューター上で動作します。明示的にオンライン機能または共有機能を使用した場合に限り、入力内容がコンピューター外に送られます。</div>",
    "nb": "<p><b>Magnolie Organizer</b> er tilgjengelig som et komplett skrivebordsprogram for Linux og Windows. Denne utgaven av håndboken beskriver Windows-versjonen. <b>Magnolie Notes</b> legger til mobile notater, oppgaver og sikker utveksling via Magnolienbaum på Android-telefoner og -nettbrett.</p><p>Magnolie Organizer for Windows kjører på <b>64-biters Windows 10 eller Windows 11</b>.</p><h3>Krav</h3><ul><li><b>Operativsystem:</b> Windows 10 versjon 2004 eller nyere, eller Windows 11, alltid 64-biters</li><li><b>Minne:</b> 2 gigabyte er nok; 4 gigabyte gir rikelig plass</li><li><b>Diskplass:</b> omtrent 230 megabyte for det selvstendige programmet, pluss plass til dataene dine</li><li><b>Skjerm:</b> minst 1024 x 768 piksler</li><li><b>WebView2:</b> Microsoft Edge WebView2 Runtime, som finnes på gjeldende Windows-installasjoner</li><li><b>Internett:</b> ikke nødvendig for daglig bruk; bare nettfunksjoner som helligdager, vær, kart og oppdateringskontroll trenger forbindelse</li></ul><h3>Inkluderte komponenter</h3><p>Programmet inkluderer nødvendig .NET-runtime. Python og ekstra grensesnittbiblioteker trenger ikke installeres.</p><div class='merke'><b>Greit å vite</b>Organizeren arbeider på datamaskinen din. Oppføringene forlater den bare når du uttrykkelig bruker en nett- eller delingsfunksjon.</div>",
    "nl": "<p><b>Magnolie Organizer</b> is beschikbaar als volledige bureaubladtoepassing voor Linux en Windows. Deze uitgave van het handboek beschrijft de Windows-versie. <b>Magnolie Notes</b> voegt daar mobiele notities, taken en veilige uitwisseling via de Magnolienbaum op Android-telefoons en -tablets aan toe.</p><p>Magnolie Organizer voor Windows draait op <b>64-bits Windows 10 of Windows 11</b>.</p><h3>Vereisten</h3><ul><li><b>Besturingssysteem:</b> Windows 10 versie 2004 of nieuwer, of Windows 11, in beide gevallen 64-bits</li><li><b>Geheugen:</b> 2 gigabyte is genoeg; 4 gigabyte geeft ruim speling</li><li><b>Schijfruimte:</b> ongeveer 230 megabyte voor de zelfstandige toepassing, plus ruimte voor uw gegevens</li><li><b>Beeldscherm:</b> minstens 1024 × 768 beeldpunten</li><li><b>WebView2:</b> Microsoft Edge WebView2 Runtime, aanwezig op huidige Windows-installaties</li><li><b>Internet:</b> niet nodig voor dagelijks gebruik; alleen onlinefuncties zoals feestdagen, weer, kaarten en updatecontroles hebben een verbinding nodig</li></ul><h3>Meegeleverde onderdelen</h3><p>De toepassing bevat de benodigde .NET-runtime. Python en extra interfacebibliotheken hoeven niet te worden geïnstalleerd.</p><div class='merke'><b>Goed om te weten</b>De Organizer werkt op uw computer. Uw invoer verlaat hem alleen als u uitdrukkelijk een online- of deelfunctie gebruikt.</div>",
    "pl": "<p><b>Magnolie Organizer</b> jest dostępny jako kompletna aplikacja komputerowa dla systemów Linux i Windows. To wydanie podręcznika opisuje wersję dla Windows. <b>Magnolie Notes</b> dodaje mobilne notatki, zadania i bezpieczną wymianę przez Magnolienbaum na telefonach i tabletach z Androidem.</p><p>Magnolie Organizer dla Windows działa w <b>64-bitowym Windows 10 lub Windows 11</b>.</p><h3>Wymagania</h3><ul><li><b>System operacyjny:</b> Windows 10 w wersji 2004 lub nowszej albo Windows 11, zawsze 64-bitowy</li><li><b>Pamięć:</b> wystarczą 2 gigabajty; 4 gigabajty zapewniają dużo zapasu</li><li><b>Miejsce na dysku:</b> około 230 megabajtów na samodzielną aplikację oraz miejsce na dane użytkownika</li><li><b>Ekran:</b> co najmniej 1024 x 768 pikseli</li><li><b>WebView2:</b> Microsoft Edge WebView2 Runtime, obecny w aktualnych instalacjach Windows</li><li><b>Internet:</b> niewymagany w codziennej pracy; tylko funkcje internetowe, takie jak święta, pogoda, mapy i sprawdzanie aktualizacji, wymagają połączenia</li></ul><h3>Dołączone składniki</h3><p>Aplikacja zawiera wymagane środowisko uruchomieniowe .NET. Nie trzeba instalować Pythona ani dodatkowych bibliotek interfejsu.</p><div class='merke'><b>Warto wiedzieć</b>Organizer działa na komputerze użytkownika. Wpisy opuszczają go tylko po jawnym użyciu funkcji internetowej lub udostępniania.</div>",
    "pt": "<p><b>Magnolie Organizer</b> está disponível como aplicação de ambiente de trabalho completa para Linux e Windows. Esta edição do manual descreve a versão para Windows. <b>Magnolie Notes</b> acrescenta notas móveis, tarefas e troca segura através do Magnolienbaum em telemóveis e tablets Android.</p><p>O Magnolie Organizer para Windows funciona em <b>Windows 10 ou Windows 11 de 64 bits</b>.</p><h3>Requisitos</h3><ul><li><b>Sistema operativo:</b> Windows 10 versão 2004 ou posterior, ou Windows 11, em ambos os casos de 64 bits</li><li><b>Memória:</b> 2 gigabytes chegam; 4 gigabytes dão bastante folga</li><li><b>Espaço em disco:</b> cerca de 230 megabytes para a aplicação autónoma, mais o espaço necessário para os seus dados</li><li><b>Ecrã:</b> pelo menos 1024 × 768 pixels</li><li><b>WebView2:</b> Microsoft Edge WebView2 Runtime, presente nas instalações atuais do Windows</li><li><b>Internet:</b> não é necessária para o uso diário; só as funções em linha, como feriados, meteorologia, mapas e verificação de atualizações, precisam de ligação</li></ul><h3>Componentes incluídos</h3><p>A aplicação inclui o runtime .NET necessário. Não é preciso instalar o Python nem outras bibliotecas de interface.</p><div class='merke'><b>É bom saber</b>O Organizador trabalha no seu computador. As suas entradas só saem dele se utilizar expressamente uma função em linha ou de partilha.</div>",
    "ru": "<p><b>Magnolie Organizer</b> доступен как полноценное настольное приложение для Linux и Windows. Это издание руководства описывает версию для Windows. <b>Magnolie Notes</b> добавляет мобильные заметки, задачи и безопасный обмен через Magnolienbaum на телефонах и планшетах Android.</p><p>Magnolie Organizer для Windows работает в <b>64-разрядной Windows 10 или Windows 11</b>.</p><h3>Требования</h3><ul><li><b>Операционная система:</b> Windows 10 версии 2004 или новее либо Windows 11, в каждом случае 64-разрядная</li><li><b>Память:</b> достаточно 2 гигабайт; 4 гигабайта обеспечивают хороший запас</li><li><b>Место на диске:</b> около 230 мегабайт для автономного приложения плюс место для ваших данных</li><li><b>Экран:</b> не менее 1024 x 768 пикселей</li><li><b>WebView2:</b> Microsoft Edge WebView2 Runtime, присутствующий в актуальных установках Windows</li><li><b>Интернет:</b> не требуется для повседневной работы; подключение нужно только сетевым функциям, таким как праздники, погода, карты и проверка обновлений</li></ul><h3>Включённые компоненты</h3><p>Приложение содержит требуемую среду выполнения .NET. Устанавливать Python и дополнительные библиотеки интерфейса не нужно.</p><div class='merke'><b>Полезно знать</b>Organizer работает на вашем компьютере. Ваши записи покидают его, только когда вы явно используете сетевую функцию или функцию общего доступа.</div>",
    "tr": "<p><b>Magnolie Organizer</b>, Linux ve Windows için eksiksiz bir masaüstü uygulaması olarak sunulur. El kitabının bu sürümü Windows sürümünü açıklar. <b>Magnolie Notes</b>, Android telefonlarda ve tabletlerde mobil notlar, görevler ve Magnolienbaum üzerinden güvenli veri alışverişi olanağı ekler.</p><p>Windows için Magnolie Organizer, <b>64 bit Windows 10 veya Windows 11</b> üzerinde çalışır.</p><h3>Gereksinimler</h3><ul><li><b>İşletim sistemi:</b> Her biri 64 bit olmak üzere Windows 10 sürüm 2004 veya üzeri ya da Windows 11</li><li><b>Bellek:</b> 2 gigabayt yeterlidir; 4 gigabayt geniş çalışma alanı sağlar</li><li><b>Disk alanı:</b> Bağımsız uygulama için yaklaşık 230 megabayt ve verileriniz için ek alan</li><li><b>Ekran:</b> En az 1024 x 768 piksel</li><li><b>WebView2:</b> Güncel Windows kurulumlarında bulunan Microsoft Edge WebView2 Runtime</li><li><b>İnternet:</b> Günlük kullanım için gerekmez; yalnızca tatiller, hava durumu, haritalar ve güncelleme denetimleri gibi çevrimiçi işlevler bağlantı gerektirir</li></ul><h3>Birlikte gelen bileşenler</h3><p>Uygulama gerekli .NET çalışma zamanını içerir. Python ve ek arayüz kitaplıklarının kurulması gerekmez.</p><div class='merke'><b>Bilmenizde yarar var</b>Organizer bilgisayarınızda çalışır. Kayıtlarınız yalnızca açıkça çevrimiçi veya paylaşım işlevi kullandığınızda bilgisayarınızdan çıkar.</div>",
    "uk": "<p><b>Magnolie Organizer</b> доступний як повноцінна настільна програма для Linux і Windows. Це видання посібника описує версію для Windows. <b>Magnolie Notes</b> додає мобільні нотатки, завдання та безпечний обмін через Magnolienbaum на телефонах і планшетах Android.</p><p>Magnolie Organizer для Windows працює в <b>64-розрядній Windows 10 або Windows 11</b>.</p><h3>Вимоги</h3><ul><li><b>Операційна система:</b> Windows 10 версії 2004 або новішої чи Windows 11, у кожному разі 64-розрядна</li><li><b>Пам’ять:</b> достатньо 2 гігабайтів; 4 гігабайти забезпечують чималий запас</li><li><b>Місце на диску:</b> близько 230 мегабайтів для автономної програми та додаткове місце для ваших даних</li><li><b>Екран:</b> щонайменше 1024 x 768 пікселів</li><li><b>WebView2:</b> Microsoft Edge WebView2 Runtime, наявний у сучасних інсталяціях Windows</li><li><b>Інтернет:</b> не потрібен для щоденної роботи; з’єднання потребують лише мережеві функції, як-от свята, погода, карти та перевірка оновлень</li></ul><h3>Включені компоненти</h3><p>Програма містить потрібне середовище виконання .NET. Python і додаткові бібліотеки інтерфейсу встановлювати не потрібно.</p><div class='merke'><b>Корисно знати</b>Organizer працює на вашому комп’ютері. Ваші записи залишають його лише тоді, коли ви явно використовуєте мережеву функцію або функцію поширення.</div>",
    "zh-cn": "<p><b>Magnolie Organizer</b> 提供适用于 Linux 和 Windows 的完整桌面应用程序。本版手册介绍 Windows 版本。<b>Magnolie Notes</b> 可在 Android 手机和平板电脑上添加移动笔记、任务，并通过 Magnolienbaum 进行安全交换。</p><p>Windows 版 Magnolie Organizer 可在 <b>64 位 Windows 10 或 Windows 11</b> 上运行。</p><h3>要求</h3><ul><li><b>操作系统：</b>64 位 Windows 10 版本 2004 或更高版本，或者 64 位 Windows 11</li><li><b>内存：</b>2 GB 已足够；4 GB 可提供充足余量</li><li><b>磁盘空间：</b>自包含应用程序约需 230 MB，另需存放数据的空间</li><li><b>显示器：</b>至少 1024 x 768 像素</li><li><b>WebView2：</b>Microsoft Edge WebView2 Runtime，当前的 Windows 安装中已包含</li><li><b>互联网：</b>日常使用不需要；只有假日、天气、地图和更新检查等在线功能需要连接</li></ul><h3>随附组件</h3><p>应用程序已包含所需的 .NET 运行时。无需安装 Python 或其他界面库。</p><div class='merke'><b>须知</b>Organizer 在您的电脑上运行。只有在您明确使用在线或共享功能时，您的条目才会离开电脑。</div>"
  },
  "installing-the-organizer": {
    "en": "<p>Download <i>Magnolie-Organizer-Windows-2.0.0-Setup-x64.exe</i> and double-click the file.</p><ol class='schritte'><li>Confirm the welcome page with <span class='knopfwort'>Next</span>.</li><li>Accept the proposed program folder under your local application-data folder, or select another program folder.</li><li>Leave <b>User handbook</b> selected if this book should be installed as well.</li><li>Select the desktop shortcut if required.</li><li>Click <span class='knopfwort'>Install</span>.</li></ol><p>Installation applies only to your Windows account and does not require administrator rights. A <b>Magnolie Organizer</b> folder is created in the Start menu.</p><div class='achtung'><b>Keep program and data folders separate</b>Do not install the program directly in <i>%LOCALAPPDATA%\\Magnolie Organizer</i>. That folder is reserved for your personal data and settings.</div>",
    "de": "<p>Laden Sie <i>Magnolie-Organizer-Windows-2.0.0-Setup-x64.exe</i> herunter und starten Sie die Datei per Doppelklick.</p><ol class='schritte'><li>Bestätigen Sie die Willkommensseite mit <span class='knopfwort'>Weiter</span>.</li><li>Übernehmen Sie den vorgeschlagenen Programmordner unter Ihrem lokalen Anwendungsdatenordner oder wählen Sie einen anderen Programmordner.</li><li>Lassen Sie die Komponente <b>Benutzerhandbuch</b> markiert, wenn dieses Buch mitinstalliert werden soll.</li><li>Wählen Sie bei Bedarf zusätzlich die Desktop-Verknüpfung.</li><li>Klicken Sie auf <span class='knopfwort'>Installieren</span>.</li></ol><p>Die Installation gilt nur für Ihr Windows-Benutzerkonto und benötigt keine Administratorrechte. Im Startmenü entsteht der Ordner <b>Magnolie Organizer</b>.</p><div class='achtung'><b>Programm- und Datenordner trennen</b>Installieren Sie das Programm nicht unmittelbar nach <i>%LOCALAPPDATA%\\Magnolie Organizer</i>. Dieser Ordner ist für Ihre persönlichen Daten und Einstellungen reserviert.</div>",
    "ar": "<p>نزّل <i dir='ltr'>Magnolie-Organizer-Windows-2.0.0-Setup-x64.exe</i> وانقر نقرًا مزدوجًا على الملف.</p><ol class='schritte'><li>أكد صفحة الترحيب باستخدام <span class='knopfwort'>التالي</span>.</li><li>اقبل مجلد البرنامج المقترح ضمن مجلد بيانات التطبيقات المحلية، أو اختر مجلد برنامج آخر.</li><li>اترك <b>دليل المستخدم</b> محددا إذا أردت تثبيت هذا الدليل أيضا.</li><li>حدد اختصار سطح المكتب عند الحاجة.</li><li>انقر على <span class='knopfwort'>تثبيت</span>.</li></ol><p>ينطبق التثبيت على حساب Windows الخاص بك فقط ولا يتطلب صلاحيات المسؤول. ويُنشأ مجلد <b>Magnolie Organizer</b> في قائمة ابدأ.</p><div class='achtung'><b>افصل مجلد البرنامج عن مجلد البيانات</b>لا تثبت البرنامج مباشرة في <i dir='ltr'>%LOCALAPPDATA%\\Magnolie Organizer</i>. فهذا المجلد محجوز لبياناتك وإعداداتك الشخصية.</div>",
    "be": "<p>Спампуйце <i>Magnolie-Organizer-Windows-2.0.0-Setup-x64.exe</i> і двойчы пстрыкніце файл.</p><ol class='schritte'><li>Пацвердзіце старонку прывітання кнопкай <span class='knopfwort'>Далей</span>.</li><li>Прыміце прапанаваную папку праграмы ў лакальнай папцы даных праграм або выберыце іншую папку праграмы.</li><li>Пакіньце выбраным <b>Даведнік карыстальніка</b>, калі трэба ўсталяваць і гэтую кнігу.</li><li>Пры патрэбе выберыце ярлык на працоўным стале.</li><li>Націсніце <span class='knopfwort'>Усталяваць</span>.</li></ol><p>Усталяванне дзейнічае толькі для вашага ўліковага запісу Windows і не патрабуе правоў адміністратара. У меню «Пуск» ствараецца папка <b>Magnolie Organizer</b>.</p><div class='achtung'><b>Трымайце папкі праграмы і даных асобна</b>Не ўсталёўвайце праграму непасрэдна ў <i>%LOCALAPPDATA%\\Magnolie Organizer</i>. Гэтая папка прызначана для вашых асабістых даных і налад.</div>",
    "cs": "<p>Stáhněte <i>Magnolie-Organizer-Windows-2.0.0-Setup-x64.exe</i> a poklepejte na soubor.</p><ol class='schritte'><li>Potvrďte uvítací stránku tlačítkem <span class='knopfwort'>Další</span>.</li><li>Přijměte navrženou programovou složku ve své místní složce dat aplikací nebo vyberte jinou programovou složku.</li><li>Ponechte vybranou položku <b>Uživatelská příručka</b>, má-li se nainstalovat také tato kniha.</li><li>V případě potřeby vyberte zástupce na ploše.</li><li>Klepněte na <span class='knopfwort'>Instalovat</span>.</li></ol><p>Instalace platí jen pro váš účet Windows a nevyžaduje oprávnění správce. V nabídce Start se vytvoří složka <b>Magnolie Organizer</b>.</p><div class='achtung'><b>Oddělte programovou a datovou složku</b>Neinstalujte program přímo do <i>%LOCALAPPDATA%\\Magnolie Organizer</i>. Tato složka je vyhrazena pro vaše osobní údaje a nastavení.</div>",
    "da": "<p>Hent <i>Magnolie-Organizer-Windows-2.0.0-Setup-x64.exe</i>, og dobbeltklik på filen.</p><ol class='schritte'><li>Bekræft velkomstsiden med <span class='knopfwort'>Næste</span>.</li><li>Accepter den foreslåede programmappe under din lokale mappe med programdata, eller vælg en anden programmappe.</li><li>Lad <b>Brugerhåndbog</b> være markeret, hvis denne bog også skal installeres.</li><li>Vælg om nødvendigt genvejen på skrivebordet.</li><li>Klik på <span class='knopfwort'>Installer</span>.</li></ol><p>Installationen gælder kun din Windows-konto og kræver ikke administratorrettigheder. I menuen Start oprettes mappen <b>Magnolie Organizer</b>.</p><div class='achtung'><b>Hold programmappe og datamappe adskilt</b>Installer ikke programmet direkte i <i>%LOCALAPPDATA%\\Magnolie Organizer</i>. Den mappe er reserveret til dine personlige data og indstillinger.</div>",
    "es": "<p>Descargue <i>Magnolie-Organizer-Windows-2.0.0-Setup-x64.exe</i> y haga doble clic en el archivo.</p><ol class='schritte'><li>Confirme la página de bienvenida con <span class='knopfwort'>Siguiente</span>.</li><li>Acepte la carpeta de programa propuesta dentro de su carpeta local de datos de aplicación, o elija otra carpeta de programa.</li><li>Deje marcado <b>Manual de usuario</b> si desea instalar también este libro.</li><li>Seleccione el acceso directo del escritorio si lo necesita.</li><li>Haga clic en <span class='knopfwort'>Instalar</span>.</li></ol><p>La instalación afecta únicamente a su cuenta de Windows y no requiere derechos de administrador. En el menú Inicio se crea la carpeta <b>Magnolie Organizer</b>.</p><div class='achtung'><b>Separe la carpeta del programa de la de los datos</b>No instale el programa directamente en <i>%LOCALAPPDATA%\\Magnolie Organizer</i>. Esa carpeta está reservada para sus datos personales y sus ajustes.</div>",
    "fr": "<p>Téléchargez <i>Magnolie-Organizer-Windows-2.0.0-Setup-x64.exe</i> et double-cliquez sur le fichier.</p><ol class='schritte'><li>Validez la page de bienvenue avec <span class='knopfwort'>Suivant</span>.</li><li>Acceptez le dossier de programme proposé dans votre dossier local de données d’application, ou choisissez un autre dossier de programme.</li><li>Laissez <b>Manuel d’utilisation</b> sélectionné si ce livre doit être installé également.</li><li>Sélectionnez au besoin le raccourci sur le bureau.</li><li>Cliquez sur <span class='knopfwort'>Installer</span>.</li></ol><p>L’installation ne concerne que votre compte Windows et ne nécessite aucun droit d’administrateur. Un dossier <b>Magnolie Organizer</b> est créé dans le menu Démarrer.</p><div class='achtung'><b>Séparez le dossier du programme de celui des données</b>N’installez pas le programme directement dans <i>%LOCALAPPDATA%\\Magnolie Organizer</i>. Ce dossier est réservé à vos données personnelles et à vos réglages.</div>",
    "hi": "<p><i>Magnolie-Organizer-Windows-2.0.0-Setup-x64.exe</i> डाउनलोड करें और फ़ाइल पर डबल-क्लिक करें।</p><ol class='schritte'><li>स्वागत पृष्ठ पर <span class='knopfwort'>अगला</span> दबाएँ।</li><li>अपने स्थानीय एप्लिकेशन-डेटा फ़ोल्डर के अंतर्गत सुझाया गया प्रोग्राम फ़ोल्डर स्वीकार करें, या कोई दूसरा प्रोग्राम फ़ोल्डर चुनें।</li><li>यदि यह पुस्तिका भी इंस्टॉल करनी है, तो <b>उपयोगकर्ता पुस्तिका</b> को चयनित रहने दें।</li><li>आवश्यकता होने पर डेस्कटॉप शॉर्टकट चुनें।</li><li><span class='knopfwort'>इंस्टॉल करें</span> पर क्लिक करें।</li></ol><p>इंस्टॉलेशन केवल आपके Windows खाते पर लागू होता है और इसके लिए प्रशासक अधिकारों की आवश्यकता नहीं है। प्रारंभ मेनू में <b>Magnolie Organizer</b> फ़ोल्डर बनाया जाता है।</p><div class='achtung'><b>प्रोग्राम और डेटा फ़ोल्डर अलग रखें</b>प्रोग्राम को सीधे <i>%LOCALAPPDATA%\\Magnolie Organizer</i> में इंस्टॉल न करें। वह फ़ोल्डर आपके निजी डेटा और सेटिंग के लिए आरक्षित है।</div>",
    "hsb": "<p>Sćehńće <i>Magnolie-Organizer-Windows-2.0.0-Setup-x64.exe</i> a klikńće dwójce na dataju.</p><ol class='schritte'><li>Witajnu stronu z <span class='knopfwort'>Dale</span> wobkrućće.</li><li>Přewozmće namjetowany programowy zapis pod lokalnym zapisom nałoženskich datow abo wubjerće druhi programowy zapis.</li><li>Wostajće <b>Wužiwarsku přiručku</b> wubranu, jeli ma so tuta kniha sobu instalować.</li><li>Wubjerće po potrjebje zwjazanje na desktopje.</li><li>Klikńće na <span class='knopfwort'>Instalować</span>.</li></ol><p>Instalacija płaći jenož za waše konto Windows a njetrjeba prawa administratora. W startowym meniju so zapis <b>Magnolie Organizer</b> załoži.</p><div class='achtung'><b>Programowy a datowy zapis dźělće</b>Njeinstalujće program direktnje do <i>%LOCALAPPDATA%\\Magnolie Organizer</i>. Tutón zapis je za waše wosobinske daty a nastajenja rezerwowany.</div>",
    "it": "<p>Scaricate <i>Magnolie-Organizer-Windows-2.0.0-Setup-x64.exe</i> e fate doppio clic sul file.</p><ol class='schritte'><li>Confermate la pagina di benvenuto con <span class='knopfwort'>Avanti</span>.</li><li>Accettate la cartella di programma proposta nella vostra cartella locale dei dati applicazione, oppure sceglietene un'altra.</li><li>Lasciate selezionato <b>Manuale utente</b> se volete installare anche questo libro.</li><li>Selezionate all'occorrenza il collegamento sul desktop.</li><li>Fate clic su <span class='knopfwort'>Installa</span>.</li></ol><p>L'installazione riguarda solo il vostro account Windows e non richiede diritti di amministratore. Nel menu Start viene creata la cartella <b>Magnolie Organizer</b>.</p><div class='achtung'><b>Tenete separate la cartella del programma e quella dei dati</b>Non installate il programma direttamente in <i>%LOCALAPPDATA%\\Magnolie Organizer</i>. Quella cartella è riservata ai vostri dati personali e alle impostazioni.</div>",
    "ja": "<p><i>Magnolie-Organizer-Windows-2.0.0-Setup-x64.exe</i> をダウンロードし、ファイルをダブルクリックします。</p><ol class='schritte'><li>ようこそ画面で <span class='knopfwort'>次へ</span> を押します。</li><li>ローカルアプリケーションデータフォルダー内に提案されたプログラムフォルダーをそのまま使うか、別のプログラムフォルダーを選びます。</li><li>このハンドブックもインストールする場合は、<b>ユーザーハンドブック</b>を選択したままにします。</li><li>必要に応じてデスクトップショートカットを選びます。</li><li><span class='knopfwort'>インストール</span> をクリックします。</li></ol><p>インストールは現在の Windows アカウントだけに適用され、管理者権限は必要ありません。スタートメニューに <b>Magnolie Organizer</b> フォルダーが作成されます。</p><div class='achtung'><b>プログラムとデータのフォルダーを分ける</b>プログラムを <i>%LOCALAPPDATA%\\Magnolie Organizer</i> に直接インストールしないでください。このフォルダーは個人データと設定用に予約されています。</div>",
    "nb": "<p>Last ned <i>Magnolie-Organizer-Windows-2.0.0-Setup-x64.exe</i>, og dobbeltklikk på filen.</p><ol class='schritte'><li>Bekreft velkomstsiden med <span class='knopfwort'>Neste</span>.</li><li>Godta den foreslåtte programmappen under den lokale programdatamappen, eller velg en annen programmappe.</li><li>La <b>Brukerhåndbok</b> være valgt hvis denne boken også skal installeres.</li><li>Velg om nødvendig snarveien på skrivebordet.</li><li>Klikk på <span class='knopfwort'>Installer</span>.</li></ol><p>Installasjonen gjelder bare Windows-kontoen din og krever ikke administratorrettigheter. Det opprettes en <b>Magnolie Organizer</b>-mappe på Start-menyen.</p><div class='achtung'><b>Hold program- og datamapper atskilt</b>Ikke installer programmet direkte i <i>%LOCALAPPDATA%\\Magnolie Organizer</i>. Denne mappen er reservert for personlige data og innstillinger.</div>",
    "nl": "<p>Haal <i>Magnolie-Organizer-Windows-2.0.0-Setup-x64.exe</i> op en dubbelklik op het bestand.</p><ol class='schritte'><li>Bevestig de welkomstpagina met <span class='knopfwort'>Volgende</span>.</li><li>Neem de voorgestelde programmamap in uw lokale map met toepassingsgegevens over, of kies een andere programmamap.</li><li>Laat <b>Gebruikershandboek</b> geselecteerd als dit boek moet worden meegeïnstalleerd.</li><li>Kies zo nodig ook de snelkoppeling op het bureaublad.</li><li>Klik op <span class='knopfwort'>Installeren</span>.</li></ol><p>De installatie geldt alleen voor uw Windows-account en vereist geen beheerdersrechten. In het startmenu ontstaat de map <b>Magnolie Organizer</b>.</p><div class='achtung'><b>Houd programmamap en gegevensmap gescheiden</b>Installeer het programma niet rechtstreeks in <i>%LOCALAPPDATA%\\Magnolie Organizer</i>. Die map is gereserveerd voor uw persoonlijke gegevens en instellingen.</div>",
    "pl": "<p>Pobierz <i>Magnolie-Organizer-Windows-2.0.0-Setup-x64.exe</i> i kliknij plik dwukrotnie.</p><ol class='schritte'><li>Potwierdź stronę powitalną przyciskiem <span class='knopfwort'>Dalej</span>.</li><li>Zaakceptuj proponowany folder programu w lokalnym folderze danych aplikacji albo wybierz inny folder programu.</li><li>Pozostaw zaznaczony <b>Podręcznik użytkownika</b>, jeśli ta książka również ma zostać zainstalowana.</li><li>W razie potrzeby wybierz skrót na pulpicie.</li><li>Kliknij <span class='knopfwort'>Zainstaluj</span>.</li></ol><p>Instalacja dotyczy wyłącznie konta Windows użytkownika i nie wymaga uprawnień administratora. W menu Start powstaje folder <b>Magnolie Organizer</b>.</p><div class='achtung'><b>Oddziel folder programu od folderu danych</b>Nie instaluj programu bezpośrednio w <i>%LOCALAPPDATA%\\Magnolie Organizer</i>. Ten folder jest przeznaczony na dane osobiste i ustawienia.</div>",
    "pt": "<p>Transfira <i>Magnolie-Organizer-Windows-2.0.0-Setup-x64.exe</i> e faça duplo clique no ficheiro.</p><ol class='schritte'><li>Confirme a página de boas-vindas com <span class='knopfwort'>Seguinte</span>.</li><li>Aceite a pasta de programa proposta na sua pasta local de dados de aplicação, ou escolha outra pasta de programa.</li><li>Deixe <b>Manual do utilizador</b> selecionado se quiser instalar também este livro.</li><li>Selecione o atalho no ambiente de trabalho, se precisar.</li><li>Clique em <span class='knopfwort'>Instalar</span>.</li></ol><p>A instalação abrange apenas a sua conta do Windows e não exige direitos de administrador. No menu Iniciar é criada a pasta <b>Magnolie Organizer</b>.</p><div class='achtung'><b>Separe a pasta do programa da pasta dos dados</b>Não instale o programa diretamente em <i>%LOCALAPPDATA%\\Magnolie Organizer</i>. Essa pasta está reservada aos seus dados pessoais e definições.</div>",
    "ru": "<p>Загрузите <i>Magnolie-Organizer-Windows-2.0.0-Setup-x64.exe</i> и дважды щёлкните файл.</p><ol class='schritte'><li>Подтвердите страницу приветствия кнопкой <span class='knopfwort'>Далее</span>.</li><li>Примите предложенную папку программы в локальной папке данных приложений или выберите другую папку программы.</li><li>Оставьте выбранным <b>Руководство пользователя</b>, если эту книгу также нужно установить.</li><li>При необходимости выберите ярлык на рабочем столе.</li><li>Нажмите <span class='knopfwort'>Установить</span>.</li></ol><p>Установка применяется только к вашей учётной записи Windows и не требует прав администратора. В меню «Пуск» создаётся папка <b>Magnolie Organizer</b>.</p><div class='achtung'><b>Разделяйте папки программы и данных</b>Не устанавливайте программу непосредственно в <i>%LOCALAPPDATA%\\Magnolie Organizer</i>. Эта папка предназначена для ваших личных данных и настроек.</div>",
    "tr": "<p><i>Magnolie-Organizer-Windows-2.0.0-Setup-x64.exe</i> dosyasını indirin ve çift tıklayın.</p><ol class='schritte'><li>Karşılama sayfasını <span class='knopfwort'>İleri</span> ile onaylayın.</li><li>Yerel uygulama verileri klasörünüz altında önerilen program klasörünü kabul edin veya başka bir program klasörü seçin.</li><li>Bu kitabın da kurulmasını istiyorsanız <b>Kullanıcı el kitabı</b> seçeneğini işaretli bırakın.</li><li>Gerekiyorsa masaüstü kısayolunu seçin.</li><li><span class='knopfwort'>Kur</span> düğmesine tıklayın.</li></ol><p>Kurulum yalnızca Windows hesabınız için geçerlidir ve yönetici hakları gerektirmez. Başlat menüsünde bir <b>Magnolie Organizer</b> klasörü oluşturulur.</p><div class='achtung'><b>Program ve veri klasörlerini ayrı tutun</b>Programı doğrudan <i>%LOCALAPPDATA%\\Magnolie Organizer</i> konumuna kurmayın. Bu klasör kişisel verileriniz ve ayarlarınız için ayrılmıştır.</div>",
    "uk": "<p>Завантажте <i>Magnolie-Organizer-Windows-2.0.0-Setup-x64.exe</i> і двічі клацніть файл.</p><ol class='schritte'><li>Підтвердьте сторінку привітання кнопкою <span class='knopfwort'>Далі</span>.</li><li>Прийміть запропоновану папку програми в локальній папці даних програм або виберіть іншу папку програми.</li><li>Залиште вибраним <b>Посібник користувача</b>, якщо цю книгу також слід установити.</li><li>За потреби виберіть ярлик на робочому столі.</li><li>Натисніть <span class='knopfwort'>Установити</span>.</li></ol><p>Інсталяція стосується лише вашого облікового запису Windows і не потребує прав адміністратора. У меню «Пуск» створюється папка <b>Magnolie Organizer</b>.</p><div class='achtung'><b>Тримайте папки програми й даних окремо</b>Не встановлюйте програму безпосередньо в <i>%LOCALAPPDATA%\\Magnolie Organizer</i>. Цю папку зарезервовано для ваших особистих даних і налаштувань.</div>",
    "zh-cn": "<p>下载 <i>Magnolie-Organizer-Windows-2.0.0-Setup-x64.exe</i>，然后双击该文件。</p><ol class='schritte'><li>在欢迎页面上点击 <span class='knopfwort'>下一步</span>。</li><li>接受本地应用程序数据文件夹下建议的程序文件夹，或选择其他程序文件夹。</li><li>如果还要安装本手册，请保持选中<b>用户手册</b>。</li><li>需要时选择桌面快捷方式。</li><li>点击 <span class='knopfwort'>安装</span>。</li></ol><p>安装仅适用于您的 Windows 账户，不需要管理员权限。开始菜单中会创建 <b>Magnolie Organizer</b> 文件夹。</p><div class='achtung'><b>将程序文件夹与数据文件夹分开</b>请勿将程序直接安装到 <i>%LOCALAPPDATA%\\Magnolie Organizer</i>。该文件夹专用于您的个人数据和设置。</div>"
  },
  "starting-for-the-first-time": {
    "en": "<p>After installation, open <b>Magnolie Organizer</b> from its folder in the Windows Start menu.</p><p>A closed book with a brown leather cover and a golden magnolia blossom appears. <b>Click the cover once</b> to open the book.</p><p>The notepad initially contains a welcome note with the most important points. You can read and later delete it, or simply leave it there.</p><p>If you installed the handbook, you can reopen it at any time under <i>Settings ▸ About</i> or from the same Start-menu folder.</p><div class='merke'><b>No password required</b>No setup is required on first launch. You can enable password protection later under <i>Settings ▸ Security</i>.</div>",
    "de": "<p>Nach der Installation öffnen Sie <b>Magnolie Organizer</b> aus seinem Ordner im Windows-Startmenü.</p><p>Ein geschlossenes Buch mit braunem Ledereinband und goldener Magnolienblüte erscheint. <b>Klicken Sie einmal auf den Einband</b>, um das Buch zu öffnen.</p><p>Beim ersten Start enthält der Notizblock einen Willkommenshinweis mit den wichtigsten Punkten. Sie können ihn lesen und später löschen oder einfach stehen lassen.</p><p>Wenn Sie das Handbuch mitinstalliert haben, öffnen Sie es jederzeit unter <i>Einstellungen ▸ Über</i> oder aus demselben Startmenüordner.</p><div class='merke'><b>Kein Kennwort nötig</b>Beim ersten Start ist keine Einrichtung erforderlich. Einen Kennwortschutz können Sie später unter <i>Einstellungen ▸ Sicherheit</i> einschalten.</div>",
    "ar": "<p>بعد التثبيت، افتح <b>Magnolie Organizer</b> من مجلده في قائمة ابدأ في Windows.</p><p>يظهر كتاب مغلق بغلاف جلدي بني وزهرة ماغنوليا ذهبية. <b>انقر على الغلاف مرة واحدة</b> لفتح الكتاب.</p><p>تحتوي المفكرة في البداية على ملاحظة ترحيب تتضمن أهم النقاط. يمكنك قراءتها وحذفها لاحقا، أو تركها كما هي.</p><p>إذا ثبت الدليل، يمكنك فتحه مجددا في أي وقت من <i>الإعدادات ▸ حول</i> أو من مجلد قائمة ابدأ نفسه.</p><div class='merke'><b>لا حاجة إلى كلمة مرور</b>لا يلزم أي إعداد عند التشغيل الأول. ويمكنك تفعيل الحماية بكلمة مرور لاحقا من <i>الإعدادات ▸ الأمان</i>.</div>",
    "be": "<p>Пасля ўсталявання адкрыйце <b>Magnolie Organizer</b> з яго папкі ў меню «Пуск» Windows.</p><p>З’явіцца закрытая кніга ў карычневай скураной вокладцы з залатой кветкай магноліі. <b>Адзін раз пстрыкніце вокладку</b>, каб адкрыць кнігу.</p><p>Спачатку нататнік змяшчае прывітальную нататку з найважнейшымі звесткамі. Яе можна прачытаць і пазней выдаліць або проста пакінуць.</p><p>Калі вы ўсталявалі даведнік, яго можна ў любы час зноў адкрыць праз <i>Налады ▸ Аб праграме</i> або з той самай папкі меню «Пуск».</p><div class='merke'><b>Пароль не патрабуецца</b>Пры першым запуску нічога наладжваць не трэба. Абарону паролем можна пазней уключыць праз <i>Налады ▸ Бяспека</i>.</div>",
    "cs": "<p>Po instalaci otevřete <b>Magnolie Organizer</b> z jeho složky v nabídce Start systému Windows.</p><p>Objeví se zavřená kniha s hnědou koženou vazbou a zlatým květem magnolie. Knihu otevřete <b>jedním klepnutím na obálku</b>.</p><p>Poznámkový blok zpočátku obsahuje uvítací poznámku s nejdůležitějšími body. Můžete si ji přečíst a později smazat nebo ji ponechat.</p><p>Pokud jste nainstalovali příručku, můžete ji kdykoli znovu otevřít v části <i>Nastavení ▸ O aplikaci</i> nebo ze stejné složky nabídky Start.</p><div class='merke'><b>Heslo není vyžadováno</b>Při prvním spuštění není nutné nic nastavovat. Ochranu heslem můžete později zapnout v části <i>Nastavení ▸ Zabezpečení</i>.</div>",
    "da": "<p>Åbn <b>Magnolie Organizer</b> efter installationen fra programmets mappe i Windows-menuen Start.</p><p>Der vises en lukket bog med brunt læderbind og en gylden magnoliablomst. <b>Klik én gang på bindet</b> for at åbne bogen.</p><p>Notesblokken indeholder til at begynde med en velkomstnote med de vigtigste punkter. Du kan læse den og slette den senere, eller blot lade den stå.</p><p>Har du installeret håndbogen, kan du altid åbne den igen under <i>Indstillinger ▸ Om</i> eller fra samme mappe i menuen Start.</p><div class='merke'><b>Ingen adgangskode nødvendig</b>Første start kræver ingen opsætning. Du kan slå adgangskodebeskyttelse til senere under <i>Indstillinger ▸ Sikkerhed</i>.</div>",
    "es": "<p>Tras la instalación, abra <b>Magnolie Organizer</b> desde su carpeta en el menú Inicio de Windows.</p><p>Aparece un libro cerrado con cubierta de cuero marrón y una flor de magnolia dorada. <b>Haga clic una vez en la cubierta</b> para abrir el libro.</p><p>Al principio, el bloc de notas contiene una nota de bienvenida con los puntos más importantes. Puede leerla y borrarla más adelante, o simplemente dejarla donde está.</p><p>Si ha instalado el manual, puede volver a abrirlo en cualquier momento en <i>Ajustes ▸ Acerca de</i> o desde la misma carpeta del menú Inicio.</p><div class='merke'><b>No hace falta contraseña</b>El primer inicio no requiere ninguna configuración. Más adelante puede activar la protección por contraseña en <i>Ajustes ▸ Seguridad</i>.</div>",
    "fr": "<p>Après l’installation, ouvrez <b>Magnolie Organizer</b> depuis son dossier dans le menu Démarrer de Windows.</p><p>Un livre fermé apparaît, avec une couverture en cuir brun et une fleur de magnolia dorée. <b>Cliquez une fois sur la couverture</b> pour ouvrir le livre.</p><p>Le bloc-notes contient au départ une note de bienvenue qui résume les points les plus importants. Vous pouvez la lire puis la supprimer plus tard, ou simplement la laisser en place.</p><p>Si vous avez installé le manuel, vous pouvez le rouvrir à tout moment sous <i>Paramètres ▸ À propos</i> ou depuis le même dossier du menu Démarrer.</p><div class='merke'><b>Aucun mot de passe requis</b>Aucune configuration n’est nécessaire au premier démarrage. Vous pourrez activer plus tard la protection par mot de passe sous <i>Paramètres ▸ Sécurité</i>.</div>",
    "hi": "<p>इंस्टॉलेशन के बाद Windows प्रारंभ मेनू में उसके फ़ोल्डर से <b>Magnolie Organizer</b> खोलें।</p><p>भूरे चमड़े के आवरण और सुनहरे मैग्नोलिया फूल वाली एक बंद पुस्तक दिखाई देती है। पुस्तक खोलने के लिए <b>आवरण पर एक बार क्लिक करें</b>।</p><p>नोटपैड में आरंभ में सबसे महत्वपूर्ण बातों वाला स्वागत नोट होता है। आप उसे पढ़कर बाद में हटा सकते हैं या वहीं रहने दे सकते हैं।</p><p>यदि आपने पुस्तिका इंस्टॉल की है, तो उसे कभी भी <i>सेटिंग्स ▸ परिचय</i> या उसी प्रारंभ-मेनू फ़ोल्डर से दोबारा खोल सकते हैं।</p><div class='merke'><b>पासवर्ड आवश्यक नहीं</b>पहली बार शुरू करते समय कोई सेटअप आवश्यक नहीं है। आप बाद में <i>सेटिंग्स ▸ सुरक्षा</i> में पासवर्ड सुरक्षा चालू कर सकते हैं।</div>",
    "hsb": "<p>Po instalaciji wočińće <b>Magnolie Organizer</b> z jeho zapisa w startowym meniju Windows.</p><p>Začinjená kniha z brunej kožanej wjazbu a złotej magnolijowej kwětku so zjewi. <b>Klikńće jónkróć na wobalku</b>, zo byšće knihu wočinili.</p><p>Noticnik spočatnje witansku noticu z najwažnišimi dypkami wobsahuje. Móžeće ju čitać a pozdźišo zhašeć abo prosće wostajić.</p><p>Jeli sće přiručku instalowali, móžeće ju kóždy čas pod <i>Nastajenja ▸ Wo programje</i> abo ze samsneho zapisa startoweho menija zaso wočinić.</p><div class='merke'><b>Žane hesło trěbne</b>Při prěnim startowanju njetrjebaće ničo zarjadować. Hesłowy škit móžeće pozdźišo pod <i>Nastajenja ▸ Wěstota</i> zmóžnić.</div>",
    "it": "<p>Dopo l'installazione aprite <b>Magnolie Organizer</b> dalla sua cartella nel menu Start di Windows.</p><p>Compare un libro chiuso con copertina in pelle marrone e un fiore di magnolia dorato. <b>Fate clic una volta sulla copertina</b> per aprire il libro.</p><p>All'inizio il blocco note contiene una nota di benvenuto con i punti più importanti. Potete leggerla ed eliminarla in seguito, oppure semplicemente lasciarla dov'è.</p><p>Se avete installato il manuale, potete riaprirlo in qualsiasi momento in <i>Impostazioni ▸ Informazioni</i> o dalla stessa cartella del menu Start.</p><div class='merke'><b>Nessuna password necessaria</b>Il primo avvio non richiede alcuna configurazione. Potete attivare la protezione con password più tardi in <i>Impostazioni ▸ Sicurezza</i>.</div>",
    "ja": "<p>インストール後、Windows のスタートメニューにあるフォルダーから <b>Magnolie Organizer</b> を開きます。</p><p>茶色の革表紙と金色のマグノリアの花が付いた閉じた本が表示されます。本を開くには、<b>表紙を 1 回クリック</b>します。</p><p>最初は、重要なポイントをまとめた歓迎メモがメモ帳に入っています。読んだ後で削除しても、そのまま残してもかまいません。</p><p>ハンドブックをインストールした場合は、<i>設定 ▸ このアプリについて</i>、または同じスタートメニューフォルダーからいつでも開き直せます。</p><div class='merke'><b>パスワードは不要</b>初回起動時の設定は必要ありません。後から <i>設定 ▸ セキュリティ</i> でパスワード保護を有効にできます。</div>",
    "nb": "<p>Etter installasjonen åpner du <b>Magnolie Organizer</b> fra programmets mappe på Start-menyen i Windows.</p><p>Det vises en lukket bok med brunt læromslag og en gyllen magnoliablomst. <b>Klikk én gang på omslaget</b> for å åpne boken.</p><p>Notatblokken inneholder først et velkomstnotat med de viktigste punktene. Du kan lese og senere slette det, eller bare la det stå.</p><p>Hvis du installerte håndboken, kan du åpne den igjen når som helst under <i>Innstillinger ▸ Om</i> eller fra samme Start-mappe.</p><div class='merke'><b>Passord er ikke nødvendig</b>Første oppstart krever ingen konfigurering. Du kan senere slå på passordbeskyttelse under <i>Innstillinger ▸ Sikkerhet</i>.</div>",
    "nl": "<p>Open na de installatie <b>Magnolie Organizer</b> vanuit de map in het Windows-startmenu.</p><p>Er verschijnt een gesloten boek met een bruine leren kaft en een gouden magnoliabloem. <b>Klik één keer op de kaft</b> om het boek te openen.</p><p>Het kladblok bevat aanvankelijk een welkomstnotitie met de belangrijkste punten. U kunt die lezen en later verwijderen, of gewoon laten staan.</p><p>Hebt u het handboek meegeïnstalleerd, dan opent u het altijd opnieuw via <i>Instellingen ▸ Info</i> of vanuit dezelfde map in het startmenu.</p><div class='merke'><b>Geen wachtwoord nodig</b>Bij de eerste start is geen instelling nodig. Wachtwoordbeveiliging kunt u later inschakelen via <i>Instellingen ▸ Beveiliging</i>.</div>",
    "pl": "<p>Po instalacji otwórz <b>Magnolie Organizer</b> z jego folderu w menu Start systemu Windows.</p><p>Pojawi się zamknięta książka w brązowej skórzanej oprawie ze złotym kwiatem magnolii. <b>Kliknij okładkę jeden raz</b>, aby otworzyć książkę.</p><p>Notatnik początkowo zawiera notatkę powitalną z najważniejszymi informacjami. Można ją przeczytać i później usunąć albo pozostawić.</p><p>Jeśli zainstalowano podręcznik, można go ponownie otworzyć w dowolnej chwili w <i>Ustawienia ▸ O programie</i> albo z tego samego folderu menu Start.</p><div class='merke'><b>Hasło nie jest wymagane</b>Przy pierwszym uruchomieniu nie trzeba niczego konfigurować. Ochronę hasłem można później włączyć w <i>Ustawienia ▸ Bezpieczeństwo</i>.</div>",
    "pt": "<p>Depois da instalação, abra o <b>Magnolie Organizer</b> a partir da sua pasta no menu Iniciar do Windows.</p><p>Aparece um livro fechado com capa de couro castanho e uma flor de magnólia dourada. <b>Clique uma vez na capa</b> para abrir o livro.</p><p>De início, o bloco de notas contém uma nota de boas-vindas com os pontos mais importantes. Pode lê-la e apagá-la mais tarde, ou simplesmente deixá-la ficar.</p><p>Se instalou o manual, pode reabri-lo a qualquer momento em <i>Definições ▸ Acerca de</i> ou a partir da mesma pasta do menu Iniciar.</p><div class='merke'><b>Não é preciso palavra-passe</b>O primeiro arranque não exige qualquer configuração. Pode ativar a proteção por palavra-passe mais tarde em <i>Definições ▸ Segurança</i>.</div>",
    "ru": "<p>После установки откройте <b>Magnolie Organizer</b> из его папки в меню «Пуск» Windows.</p><p>Появится закрытая книга в коричневом кожаном переплёте с золотым цветком магнолии. <b>Один раз щёлкните обложку</b>, чтобы открыть книгу.</p><p>Изначально блокнот содержит приветственную заметку с самыми важными сведениями. Её можно прочитать и позже удалить или просто оставить.</p><p>Если вы установили руководство, его можно в любое время снова открыть через <i>Настройки ▸ О программе</i> или из той же папки меню «Пуск».</p><div class='merke'><b>Пароль не требуется</b>При первом запуске ничего настраивать не нужно. Защиту паролем можно позже включить в <i>Настройки ▸ Безопасность</i>.</div>",
    "tr": "<p>Kurulumdan sonra Windows Başlat menüsündeki klasöründen <b>Magnolie Organizer</b> uygulamasını açın.</p><p>Kahverengi deri kapaklı ve altın renkli manolya çiçekli kapalı bir kitap görünür. Kitabı açmak için <b>kapağa bir kez tıklayın</b>.</p><p>Not defterinde başlangıçta en önemli noktaları içeren bir karşılama notu bulunur. Bu notu okuyup daha sonra silebilir veya olduğu gibi bırakabilirsiniz.</p><p>El kitabını kurduysanız istediğiniz zaman <i>Ayarlar ▸ Hakkında</i> bölümünden veya aynı Başlat menüsü klasöründen yeniden açabilirsiniz.</p><div class='merke'><b>Parola gerekmez</b>İlk çalıştırmada kurulum işlemi gerekmez. Parola korumasını daha sonra <i>Ayarlar ▸ Güvenlik</i> bölümünden etkinleştirebilirsiniz.</div>",
    "uk": "<p>Після інсталяції відкрийте <b>Magnolie Organizer</b> з його папки в меню «Пуск» Windows.</p><p>З’явиться закрита книга в коричневій шкіряній палітурці із золотою квіткою магнолії. <b>Один раз клацніть обкладинку</b>, щоб відкрити книгу.</p><p>Спочатку нотатник містить вітальну нотатку з найважливішими відомостями. Її можна прочитати й пізніше видалити або просто залишити.</p><p>Якщо ви встановили посібник, його можна будь-коли знову відкрити через <i>Налаштування ▸ Про програму</i> або з тієї самої папки меню «Пуск».</p><div class='merke'><b>Пароль не потрібен</b>Під час першого запуску нічого налаштовувати не потрібно. Захист паролем можна пізніше ввімкнути в <i>Налаштування ▸ Безпека</i>.</div>",
    "zh-cn": "<p>安装后，从 Windows 开始菜单的文件夹中打开 <b>Magnolie Organizer</b>。</p><p>屏幕上会出现一本带棕色皮革封面和金色玉兰花的合起的书。<b>单击一次封面</b>即可打开书本。</p><p>记事本最初包含一条列出要点的欢迎笔记。您可以阅读后再删除，也可以将其保留。</p><p>如果安装了手册，您随时可以从<i>设置 ▸ 关于</i>或同一个开始菜单文件夹重新打开它。</p><div class='merke'><b>无需密码</b>首次启动时无需设置。稍后可在<i>设置 ▸ 安全</i>中启用密码保护。</div>"
  },
  "all-day-appointments": {
    "en": "<p>Not every appointment has a specific time. For a day of leave, a company holiday, or a day when a tradesperson will arrive \"at some point,\" select <span class='knopfwort'>All day</span> beside the two time fields.</p><ol class='schritte'><li>Create the appointment as usual and enter its title.</li><li>Select <b>All day</b>.</li><li>If the appointment spans several days, enter the final date under <b>Through</b>.</li><li>The two time fields become pale and hatched because they are no longer needed.</li><li>Click <span class='knopfwort'>Add appointment</span>.</li></ol><p>In the appointment overview, <i>All day</i> appears in italics instead of a time and is listed before timed appointments.</p><h3>When exporting</h3><p>Other calendar programs, including Thunderbird and Outlook, recognize exported all-day appointments as bars spanning the entire day.</p><div class='merke'><b>Changing this later</b>Clear the selected option to restore suggested times.</div>",
    "de": "<p>Nicht jeder Termin hat eine bestimmte Uhrzeit. Für einen Urlaubstag, Betriebsfeiertag oder einen Tag, an dem ein Handwerker irgendwann kommt, wählen Sie neben den Zeitfeldern <span class='knopfwort'>Ganztags</span>.</p><ol class='schritte'><li>Legen Sie den Termin wie gewohnt an und tragen Sie den Titel ein.</li><li>Wählen Sie <b>Ganztags</b>.</li><li>Bei mehreren Tagen tragen Sie unter <b>Bis</b> den letzten Tag ein.</li><li>Die beiden nicht mehr benötigten Zeitfelder werden blass und schraffiert.</li><li>Klicken Sie auf <span class='knopfwort'>Termin aufnehmen</span>.</li></ol><p>In der Terminliste steht <i>Ganztags</i> kursiv anstelle einer Uhrzeit und vor Terminen mit Uhrzeit.</p><h3>Beim Export</h3><p>Andere Kalenderprogramme, darunter Thunderbird und Outlook, erkennen exportierte Ganztagstermine als Balken über den ganzen Tag.</p><div class='merke'><b>Später ändern</b>Entfernen Sie die Auswahl, um wieder vorgeschlagene Uhrzeiten zu erhalten.</div>",
    "ar": "<p>ليس لكل موعد وقت محدد. ليوم إجازة أو عطلة شركة أو يوم سيأتي فيه عامل صيانة «في وقت ما»، حدد <span class='knopfwort'>طوال اليوم</span> بجوار حقلي الوقت.</p><ol class='schritte'><li>أنشئ الموعد كالمعتاد وأدخل عنوانه.</li><li>حدد <b>طوال اليوم</b>.</li><li>إذا امتد الموعد عدة أيام، فأدخل التاريخ الأخير تحت <b>حتى</b>.</li><li>يصبح حقلا الوقت باهتين ومخططين لعدم الحاجة إليهما.</li><li>انقر على <span class='knopfwort'>إضافة موعد</span>.</li></ol><p>في نظرة عامة على المواعيد، تظهر عبارة <i>طوال اليوم</i> بخط مائل بدلا من الوقت، وتُدرج قبل المواعيد ذات الوقت المحدد.</p><h3>عند التصدير</h3><p>تتعرف برامج التقويم الأخرى، بما فيها Thunderbird وOutlook، على المواعيد المصدرة التي تستغرق يوما كاملا كأشرطة تمتد طوال اليوم.</p><div class='merke'><b>تغيير ذلك لاحقا</b>ألغ تحديد الخيار لاستعادة الأوقات المقترحة.</div>",
    "be": "<p>Не кожная сустрэча мае пэўны час. Для дня адпачынку, карпаратыўнага свята або дня, калі майстар прыйдзе «калі-небудзь», выберыце <span class='knopfwort'>Увесь дзень</span> побач з двума палямі часу.</p><ol class='schritte'><li>Стварыце сустрэчу як звычайна і ўвядзіце яе назву.</li><li>Выберыце <b>Увесь дзень</b>.</li><li>Калі сустрэча доўжыцца некалькі дзён, увядзіце апошнюю дату ў полі <b>Да</b>.</li><li>Абодва непатрэбныя палі часу стануць бледнымі і заштрыхаванымі.</li><li>Націсніце <span class='knopfwort'>Дадаць сустрэчу</span>.</li></ol><p>У аглядзе сустрэч замест часу курсівам паказваецца <i>Увесь дзень</i>, перад сустрэчамі з вызначаным часам.</p><h3>Пры экспарце</h3><p>Іншыя каляндарныя праграмы, у тым ліку Thunderbird і Outlook, распазнаюць экспартаваныя сустрэчы на ўвесь дзень як палосы на цэлы дзень.</p><div class='merke'><b>Змена пазней</b>Зніміце выбар, каб аднавіць прапанаваны час.</div>",
    "cs": "<p>Ne každá schůzka má konkrétní čas. Pro den dovolené, podnikový svátek nebo den, kdy řemeslník dorazí „někdy“, vyberte vedle dvou časových polí možnost <span class='knopfwort'>Celý den</span>.</p><ol class='schritte'><li>Vytvořte schůzku obvyklým způsobem a zadejte její název.</li><li>Vyberte <b>Celý den</b>.</li><li>Trvá-li schůzka několik dní, zadejte v poli <b>Do</b> poslední datum.</li><li>Obě nepotřebná časová pole zesvětlají a budou šrafovaná.</li><li>Klepněte na <span class='knopfwort'>Přidat schůzku</span>.</li></ol><p>V přehledu schůzek se místo času zobrazí kurzívou <i>Celý den</i> a záznam bude uveden před schůzkami s časem.</p><h3>Při exportu</h3><p>Jiné kalendářové programy včetně Thunderbird a Outlook rozpoznají exportované celodenní schůzky jako pruhy přes celý den.</p><div class='merke'><b>Pozdější změna</b>Zrušením volby obnovíte navrhované časy.</div>",
    "da": "<p>Ikke alle aftaler har et bestemt klokkeslæt. Ved en feriedag, en virksomhedsfridag eller en dag, hvor en håndværker kommer “på et tidspunkt”, vælger du <span class='knopfwort'>Hele dagen</span> ved siden af de to tidsfelter.</p><ol class='schritte'><li>Opret aftalen som normalt, og indtast titlen.</li><li>Vælg <b>Hele dagen</b>.</li><li>Hvis aftalen strækker sig over flere dage, indtaster du slutdatoen under <b>Til og med</b>.</li><li>De to tidsfelter bliver lyse og skraverede, fordi de ikke længere er nødvendige.</li><li>Klik <span class='knopfwort'>Tilføj aftale</span>.</li></ol><p>I aftaleoversigten vises <i>Hele dagen</i> i kursiv i stedet for et klokkeslæt og står før aftaler med fast tidspunkt.</p><h3>Ved eksport</h3><p>Andre kalenderprogrammer, blandt andet Thunderbird og Outlook, genkender eksporterede heldagsaftaler som bjælker hen over hele dagen.</p><div class='merke'><b>Skift senere</b>Fjern markeringen af den valgte indstilling for at få de foreslåede klokkeslæt tilbage.</div>",
    "es": "<p>No todas las citas tienen una hora concreta. Para un día de vacaciones, un día festivo de la empresa o una jornada en la que un operario llegará «en algún momento», seleccione <span class='knopfwort'>Todo el día</span> junto a los dos campos de hora.</p><ol class='schritte'><li>Cree la cita como de costumbre y escriba su título.</li><li>Seleccione <b>Todo el día</b>.</li><li>Si la cita abarca varios días, indique la fecha final en <b>Hasta</b>.</li><li>Los dos campos de hora se vuelven pálidos y rayados, porque ya no hacen falta.</li><li>Haga clic en <span class='knopfwort'>Añadir cita</span>.</li></ol><p>En el resumen de citas, <i>Todo el día</i> aparece en cursiva en lugar de una hora y se muestra antes que las citas con hora concreta.</p><h3>Al exportar</h3><p>Otros programas de calendario, como Thunderbird y Outlook, reconocen las citas de todo el día exportadas como barras que abarcan la jornada completa.</p><div class='merke'><b>Cambiarlo después</b>Desmarque la opción seleccionada para que vuelvan a proponerse horas.</div>",
    "fr": "<p>Tous les rendez-vous n’ont pas une heure précise. Pour un jour de congé, un jour férié d’entreprise ou une journée où un artisan doit arriver « à un moment quelconque », sélectionnez <span class='knopfwort'>Toute la journée</span> à côté des deux champs d’heure.</p><ol class='schritte'><li>Créez le rendez-vous comme d’habitude et saisissez son titre.</li><li>Sélectionnez <b>Toute la journée</b>.</li><li>Si le rendez-vous s’étend sur plusieurs jours, saisissez la date de fin sous <b>Jusqu’au</b>.</li><li>Les deux champs d’heure deviennent pâles et hachurés, car ils ne sont plus nécessaires.</li><li>Cliquez sur <span class='knopfwort'>Ajouter un rendez-vous</span>.</li></ol><p>Dans l’aperçu des rendez-vous, <i>Toute la journée</i> apparaît en italique à la place d’une heure et figure avant les rendez-vous ayant une heure précise.</p><h3>Lors de l’exportation</h3><p>Les autres programmes de calendrier, dont Thunderbird et Outlook, reconnaissent les rendez-vous sur toute la journée exportés et les affichent sous forme de barres couvrant la journée entière.</p><div class='merke'><b>Modifier ce réglage ultérieurement</b>Décochez l’option sélectionnée pour rétablir les horaires proposés.</div>",
    "hi": "<p>हर अपॉइंटमेंट का कोई निश्चित समय नहीं होता। छुट्टी के दिन, कंपनी के अवकाश या ऐसे दिन के लिए जब कोई कारीगर “किसी समय” आएगा, दोनों समय फ़ील्ड के पास <span class='knopfwort'>पूरे दिन</span> चुनें।</p><ol class='schritte'><li>अपॉइंटमेंट हमेशा की तरह बनाएँ और उसका शीर्षक दर्ज करें।</li><li><b>पूरे दिन</b> चुनें।</li><li>यदि अपॉइंटमेंट कई दिनों का है, तो <b>तक</b> में अंतिम तारीख दर्ज करें।</li><li>दोनों समय फ़ील्ड हल्के और धारीदार हो जाते हैं क्योंकि अब उनकी आवश्यकता नहीं है।</li><li><span class='knopfwort'>अपॉइंटमेंट जोड़ें</span> पर क्लिक करें।</li></ol><p>अपॉइंटमेंट अवलोकन में समय के स्थान पर <i>पूरे दिन</i> तिरछे अक्षरों में दिखाई देता है और समय वाले अपॉइंटमेंट से पहले सूचीबद्ध होता है।</p><h3>निर्यात करते समय</h3><p>Thunderbird और Outlook सहित अन्य कैलेंडर प्रोग्राम निर्यात किए गए पूरे-दिन के अपॉइंटमेंट को पूरे दिन फैली पट्टी के रूप में पहचानते हैं।</p><div class='merke'><b>बाद में बदलना</b>सुझाए गए समय फिर पाने के लिए चयनित विकल्प हटाएँ।</div>",
    "hsb": "<p>Njekóždy termin ma wěsty čas. Za dźeń dowola, zawodny swjaty dźeń abo dźeń, hdyž rjemjeslnik „něhdy“ přińdźe, wubjerće pódla dweju časoweju polow <span class='knopfwort'>Cyły dźeń</span>.</p><ol class='schritte'><li>Załožće termin kaž zwjetša a zapodajće jeho titul.</li><li>Wubjerće <b>Cyły dźeń</b>.</li><li>Hdyž termin wjacore dny traje, zapodajće pod <b>Hač do</b> posledni datum.</li><li>Wobej njetrěbnej časowej poli zblednjetaj a so šrafujetej.</li><li>Klikńće na <span class='knopfwort'>Termin přidać</span>.</li></ol><p>W přehladźe terminow steji <i>Cyły dźeń</i> kursiwnje město časa a před terminami z časom.</p><h3>Při eksporće</h3><p>Druhe protykowe programy, mjez nimi Thunderbird a Outlook, spóznaja eksportowane cyłodnjowske terminy jako paski přez cyły dźeń.</p><div class='merke'><b>Pozdźišo změnić</b>Zběhńće wuběr, zo byšće namjetowane časy wobnowili.</div>",
    "it": "<p>Non tutti gli appuntamenti hanno un orario preciso. Per un giorno di ferie, una chiusura aziendale o una giornata in cui un artigiano arriverà “a un certo punto”, selezionate <span class='knopfwort'>Tutto il giorno</span> accanto ai due campi dell'orario.</p><ol class='schritte'><li>Create l'appuntamento come di consueto e inserite il titolo.</li><li>Selezionate <b>Tutto il giorno</b>.</li><li>Se l'appuntamento dura più giorni, indicate la data finale in <b>Fino al</b>.</li><li>I due campi dell'orario diventano chiari e tratteggiati, perché non servono più.</li><li>Fate clic su <span class='knopfwort'>Aggiungi appuntamento</span>.</li></ol><p>Nella panoramica degli appuntamenti, <i>Tutto il giorno</i> compare in corsivo al posto di un orario ed è elencato prima degli appuntamenti con orario preciso.</p><h3>Durante l'esportazione</h3><p>Altri programmi di calendario, tra cui Thunderbird e Outlook, riconoscono gli appuntamenti di tutto il giorno esportati come barre che coprono l'intera giornata.</p><div class='merke'><b>Modificarlo in seguito</b>Deselezionate l'opzione scelta per far riproporre gli orari.</div>",
    "ja": "<p>すべての予定に特定の時刻があるとは限りません。休暇日、会社の休日、または業者が「いつか」来る日には、2 つの時刻欄の横にある <span class='knopfwort'>終日</span> を選びます。</p><ol class='schritte'><li>通常どおり予定を作成し、タイトルを入力します。</li><li><b>終日</b>を選びます。</li><li>予定が数日にわたる場合は、<b>終了日</b>に最終日を入力します。</li><li>不要になった 2 つの時刻欄が薄い網掛け表示になります。</li><li><span class='knopfwort'>予定を追加</span> をクリックします。</li></ol><p>予定の概要では、時刻の代わりに <i>終日</i> が斜体で表示され、時刻指定の予定より前に並びます。</p><h3>エクスポート時</h3><p>Thunderbird や Outlook を含む他のカレンダープログラムは、エクスポートされた終日の予定を一日全体にわたる帯として認識します。</p><div class='merke'><b>後から変更する</b>選択を解除すると、提案時刻が再び表示されます。</div>",
    "nb": "<p>Ikke alle avtaler har et bestemt klokkeslett. For en fridag, bedriftshelligdag eller en dag da en håndverker kommer «en eller annen gang», velger du <span class='knopfwort'>Hele dagen</span> ved siden av de to tidsfeltene.</p><ol class='schritte'><li>Opprett avtalen som vanlig, og skriv inn tittelen.</li><li>Velg <b>Hele dagen</b>.</li><li>Hvis avtalen varer flere dager, skriver du sluttdatoen under <b>Til og med</b>.</li><li>De to tidsfeltene blir lyse og skraverte fordi de ikke lenger trengs.</li><li>Klikk på <span class='knopfwort'>Legg til avtale</span>.</li></ol><p>I avtaleoversikten står <i>Hele dagen</i> i kursiv i stedet for et klokkeslett og før avtaler med tid.</p><h3>Ved eksport</h3><p>Andre kalenderprogrammer, blant annet Thunderbird og Outlook, gjenkjenner eksporterte heldagsavtaler som stolper over hele dagen.</p><div class='merke'><b>Endre dette senere</b>Fjern valget for å gjenopprette foreslåtte tider.</div>",
    "nl": "<p>Niet elke afspraak heeft een exact tijdstip. Voor een vrije dag, bedrijfssluiting of een dag waarop een vakman “ergens in de loop van de dag” langskomt, selecteert u <span class='knopfwort'>Hele dag</span> naast de twee tijdvelden.</p><ol class='schritte'><li>Maak de afspraak zoals gewoonlijk en voer de titel in.</li><li>Selecteer <b>Hele dag</b>.</li><li>Duurt de afspraak meerdere dagen, voer dan bij <b>Tot en met</b> de laatste datum in.</li><li>De twee tijdvelden worden licht en gearceerd omdat ze niet meer nodig zijn.</li><li>Klik op <span class='knopfwort'>Afspraak toevoegen</span>.</li></ol><p>In het afsprakenoverzicht verschijnt <i>Hele dag</i> cursief in plaats van een tijd, en staat vóór afspraken met een tijdstip.</p><h3>Bij exporteren</h3><p>Andere agendaprogramma's, waaronder Thunderbird en Outlook, herkennen geëxporteerde afspraken voor de hele dag als balken over de hele dag.</p><div class='merke'><b>Later wijzigen</b>Schakel de gekozen optie uit om de voorgestelde tijden terug te krijgen.</div>",
    "pl": "<p>Nie każde spotkanie ma określoną godzinę. Dla dnia urlopu, święta zakładowego lub dnia, w którym fachowiec przyjdzie „w pewnym momencie”, wybierz <span class='knopfwort'>Cały dzień</span> obok dwóch pól czasu.</p><ol class='schritte'><li>Utwórz spotkanie jak zwykle i wpisz jego tytuł.</li><li>Wybierz <b>Cały dzień</b>.</li><li>Jeśli spotkanie trwa kilka dni, podaj datę końcową w polu <b>Do</b>.</li><li>Dwa niepotrzebne pola czasu staną się blade i kreskowane.</li><li>Kliknij <span class='knopfwort'>Dodaj spotkanie</span>.</li></ol><p>W przeglądzie spotkań zamiast godziny pojawia się kursywą <i>Cały dzień</i>, przed spotkaniami z godziną.</p><h3>Podczas eksportu</h3><p>Inne programy kalendarzowe, w tym Thunderbird i Outlook, rozpoznają wyeksportowane spotkania całodniowe jako paski obejmujące cały dzień.</p><div class='merke'><b>Późniejsza zmiana</b>Usuń zaznaczenie, aby przywrócić sugerowane godziny.</div>",
    "pt": "<p>Nem todos os compromissos têm uma hora específica. Para um dia de férias, uma pausa da empresa ou um dia em que um técnico chegará “a qualquer hora”, selecione <span class='knopfwort'>Todo o dia</span> junto dos dois campos de hora.</p><ol class='schritte'><li>Crie o compromisso normalmente e introduza o título.</li><li>Selecione <b>Todo o dia</b>.</li><li>Se o compromisso durar vários dias, introduza a data final em <b>Até</b>.</li><li>Os dois campos de hora ficam esbatidos e tracejados, porque já não são necessários.</li><li>Clique em <span class='knopfwort'>Adicionar compromisso</span>.</li></ol><p>No resumo de compromissos, <i>Todo o dia</i> aparece em itálico em vez de uma hora e é listado antes dos compromissos com hora marcada.</p><h3>Ao exportar</h3><p>Outros programas de calendário, incluindo o Thunderbird e o Outlook, reconhecem os compromissos de todo o dia exportados como barras que cobrem o dia inteiro.</p><div class='merke'><b>Alterar mais tarde</b>Desmarque a opção selecionada para que voltem a ser propostas horas.</div>",
    "ru": "<p>Не у каждой встречи есть определённое время. Для дня отпуска, корпоративного праздника или дня, когда мастер придёт «когда-нибудь», выберите <span class='knopfwort'>Весь день</span> рядом с двумя полями времени.</p><ol class='schritte'><li>Создайте встречу как обычно и введите её название.</li><li>Выберите <b>Весь день</b>.</li><li>Если встреча длится несколько дней, укажите конечную дату в поле <b>До</b>.</li><li>Оба ненужных поля времени станут бледными и заштрихованными.</li><li>Нажмите <span class='knopfwort'>Добавить встречу</span>.</li></ol><p>В обзоре встреч вместо времени курсивом отображается <i>Весь день</i>, перед встречами с указанным временем.</p><h3>При экспорте</h3><p>Другие календарные программы, включая Thunderbird и Outlook, распознают экспортированные встречи на весь день как полосы, занимающие весь день.</p><div class='merke'><b>Изменение позднее</b>Снимите выбор, чтобы восстановить предлагаемые значения времени.</div>",
    "tr": "<p>Her randevunun belirli bir saati yoktur. İzin günü, şirket tatili veya bir ustanın “bir ara” geleceği gün için iki saat alanının yanındaki <span class='knopfwort'>tüm gün</span> seçeneğini işaretleyin.</p><ol class='schritte'><li>Randevuyu her zamanki gibi oluşturup başlığını girin.</li><li><b>tüm gün</b> seçeneğini işaretleyin.</li><li>Randevu birkaç gün sürüyorsa <b>Bitiş</b> alanına son tarihi girin.</li><li>Artık gerekmediği için iki saat alanı soluk ve taralı görünür.</li><li><span class='knopfwort'>Randevu ekle</span> düğmesine tıklayın.</li></ol><p>Randevu genel görünümünde saat yerine italik <i>tüm gün</i> yazısı görünür ve saatli randevulardan önce listelenir.</p><h3>Dışa aktarırken</h3><p>Thunderbird ve Outlook dahil diğer takvim programları, dışa aktarılan tüm günlük randevuları bütün güne yayılan çubuklar olarak tanır.</p><div class='merke'><b>Daha sonra değiştirme</b>Önerilen saatleri geri getirmek için işareti kaldırın.</div>",
    "uk": "<p>Не кожна зустріч має певний час. Для дня відпустки, корпоративного свята або дня, коли майстер прийде «колись», виберіть <span class='knopfwort'>Увесь день</span> поруч із двома полями часу.</p><ol class='schritte'><li>Створіть зустріч як звичайно та введіть її назву.</li><li>Виберіть <b>Увесь день</b>.</li><li>Якщо зустріч триває кілька днів, введіть кінцеву дату в полі <b>До</b>.</li><li>Обидва непотрібні поля часу стануть блідими й заштрихованими.</li><li>Натисніть <span class='knopfwort'>Додати зустріч</span>.</li></ol><p>В огляді зустрічей замість часу курсивом відображається <i>Увесь день</i>, перед зустрічами з указаним часом.</p><h3>Під час експорту</h3><p>Інші календарні програми, зокрема Thunderbird і Outlook, розпізнають експортовані цілоденні зустрічі як смуги на весь день.</p><div class='merke'><b>Зміна згодом</b>Зніміть вибір, щоб відновити запропонований час.</div>",
    "zh-cn": "<p>并非每个约会都有具体时间。对于休假日、公司假日或工匠会“某个时候”上门的日期，请选择两个时间字段旁的 <span class='knopfwort'>全天</span>。</p><ol class='schritte'><li>照常创建约会并输入标题。</li><li>选择<b>全天</b>。</li><li>如果约会持续数日，请在<b>截至</b>下输入最后日期。</li><li>两个时间字段会变淡并显示斜线阴影，因为不再需要它们。</li><li>点击 <span class='knopfwort'>添加约会</span>。</li></ol><p>在约会概览中，<i>全天</i>会以斜体代替时间，并列在有具体时间的约会之前。</p><h3>导出时</h3><p>Thunderbird 和 Outlook 等其他日历程序会将导出的全天约会识别为覆盖一整天的条带。</p><div class='merke'><b>稍后更改</b>清除所选选项即可恢复建议时间。</div>"
  },
  "writing-letters": {
    "en": "<p>Below each contact card is a row of small icon buttons.</p><h3>Letter</h3><p><span class='knopfwort'>Letter</span> creates a prepared document. If <b>LibreOffice Writer for Windows</b> is installed and associated with the document, it can open the result. Choose a compact sender line or a <b>DIN 5008 Form B</b> template with window address, date, fold marks, and hole-punch mark.</p><p>Enter your address under <span class='knopfwort'>Settings ▸ Contacts</span>. LibreOffice is not included with Magnolie Organizer and must be installed separately if required.</p><div class='merke'><b>Your address</b>It is also used as the starting point for a route.</div>",
    "de": "<p>Unter jeder Adresskarte befindet sich eine Reihe kleiner Symbolknöpfe.</p><h3>Brief</h3><p>Mit <span class='knopfwort'>Brief</span> erzeugen Sie ein vorbereitetes Dokument. Ist <b>LibreOffice Writer für Windows</b> installiert und der Datei zugeordnet, kann es das Ergebnis öffnen. Zur Wahl stehen eine kompakte Absenderzeile und eine Vorlage nach <b>DIN 5008 Form B</b> mit Fensteranschrift, Datum, Falt- und Lochmarken.</p><p>Tragen Sie Ihre Anschrift unter <span class='knopfwort'>Einstellungen ▸ Adressen</span> ein. LibreOffice ist nicht Bestandteil von Magnolie Organizer und muss bei Bedarf separat installiert werden.</p><div class='merke'><b>Ihre Anschrift</b>Sie dient auch als Ausgangspunkt einer Route.</div>",
    "ar": "<p>توجد أسفل كل بطاقة جهة اتصال مجموعة من أزرار الأيقونات الصغيرة.</p><h3>رسالة</h3><p>ينشئ <span class='knopfwort'>رسالة</span> مستندا معدا مسبقا. إذا كان <b>LibreOffice Writer for Windows</b> مثبتا ومرتبطا بالمستند، فيمكنه فتح النتيجة. اختر سطر مرسل مختصرا أو قالب <b>DIN 5008 Form B</b> يتضمن عنوان النافذة والتاريخ وعلامات الطي وعلامة التثقيب.</p><p>أدخل عنوانك ضمن <span class='knopfwort'>الإعدادات ▸ جهات الاتصال</span>. لا يأتي LibreOffice مع Magnolie Organizer ويجب تثبيته بشكل منفصل عند الحاجة.</p><div class='merke'><b>عنوانك</b>يُستخدم أيضا كنقطة انطلاق لمسار.</div>",
    "be": "<p>Пад кожнай карткай кантакту знаходзіцца рад малых кнопак са значкамі.</p><h3>Ліст</h3><p><span class='knopfwort'>Ліст</span> стварае падрыхтаваны дакумент. Калі <b>LibreOffice Writer for Windows</b> усталяваны і звязаны з дакументам, ён можа адкрыць вынік. Выберыце кампактны радок адпраўніка або шаблон <b>DIN 5008 Form B</b> з адрасам для акна канверта, датай, пазнакамі згіну і пазнакай дзіракола.</p><p>Увядзіце свой адрас у <span class='knopfwort'>Налады ▸ Кантакты</span>. LibreOffice не ўваходзіць у Magnolie Organizer і пры патрэбе ўсталёўваецца асобна.</p><div class='merke'><b>Ваш адрас</b>Ён таксама выкарыстоўваецца як пачатковы пункт маршруту.</div>",
    "cs": "<p>Pod každou kartou kontaktu je řada malých tlačítek s ikonami.</p><h3>Dopis</h3><p><span class='knopfwort'>Dopis</span> vytvoří připravený dokument. Je-li nainstalován <b>LibreOffice Writer for Windows</b> a dokument je s ním asociován, může výsledek otevřít. Vyberte kompaktní řádek odesílatele nebo šablonu <b>DIN 5008 Form B</b> s adresou v okénku, datem, značkami přehybu a značkou děrování.</p><p>Svou adresu zadejte v části <span class='knopfwort'>Nastavení ▸ Kontakty</span>. LibreOffice není součástí Magnolie Organizer a v případě potřeby se musí nainstalovat samostatně.</p><div class='merke'><b>Vaše adresa</b>Používá se také jako výchozí bod trasy.</div>",
    "da": "<p>Under hvert kontaktkort er der en række små ikonknapper.</p><h3>Brev</h3><p><span class='knopfwort'>Brev</span> opretter et forberedt dokument. Hvis <b>LibreOffice Writer til Windows</b> er installeret og knyttet til dokumentet, kan det åbne resultatet. Vælg en kompakt afsenderlinje eller en skabelon efter <b>DIN 5008 Form B</b> med rudeadresse, dato, foldemærker og hulmærke.</p><p>Indtast din adresse under <span class='knopfwort'>Indstillinger ▸ Kontakter</span>. LibreOffice følger ikke med Magnolie Organizer og skal installeres separat efter behov.</p><div class='merke'><b>Din adresse</b>Den bruges også som udgangspunkt for en rute.</div>",
    "es": "<p>Debajo de cada ficha de contacto hay una fila de pequeños botones con iconos.</p><h3>Carta</h3><p><span class='knopfwort'>Carta</span> crea un documento ya preparado. Si <b>LibreOffice Writer para Windows</b> está instalado y asociado al documento, puede abrir el resultado. Elija una línea de remitente compacta o una plantilla <b>DIN 5008 Form B</b> con dirección para sobre de ventana, fecha, marcas de plegado y marca de perforación.</p><p>Escriba su dirección en <span class='knopfwort'>Ajustes ▸ Contactos</span>. LibreOffice no forma parte de Magnolie Organizer y debe instalarse por separado si lo necesita.</p><div class='merke'><b>Su dirección</b>También sirve como punto de partida de una ruta.</div>",
    "fr": "<p>Sous chaque fiche de contact se trouve une rangée de petits boutons à icône.</p><h3>Lettre</h3><p><span class='knopfwort'>Lettre</span> crée un document déjà préparé. Si <b>LibreOffice Writer pour Windows</b> est installé et associé au document, il peut ouvrir le résultat. Choisissez une ligne d’expéditeur compacte ou un modèle <b>DIN 5008 forme B</b> avec adresse à fenêtre, date, marques de pliage et marque de perforation.</p><p>Saisissez votre adresse sous <span class='knopfwort'>Paramètres ▸ Contacts</span>. LibreOffice n’est pas fourni avec Magnolie Organizer et doit être installé séparément si nécessaire.</p><div class='merke'><b>Votre adresse</b>Elle sert également de point de départ pour un itinéraire.</div>",
    "hi": "<p>हर संपर्क कार्ड के नीचे छोटे आइकन बटनों की एक पंक्ति होती है।</p><h3>पत्र</h3><p><span class='knopfwort'>पत्र</span> एक तैयार दस्तावेज़ बनाता है। यदि <b>LibreOffice Writer for Windows</b> इंस्टॉल है और दस्तावेज़ से संबद्ध है, तो वह परिणाम खोल सकता है। संक्षिप्त प्रेषक पंक्ति या खिड़की वाले पते, तारीख, मोड़ चिह्न और छेद चिह्न वाला <b>DIN 5008 Form B</b> टेम्पलेट चुनें।</p><p>अपना पता <span class='knopfwort'>सेटिंग्स ▸ संपर्क</span> में दर्ज करें। LibreOffice, Magnolie Organizer में शामिल नहीं है और आवश्यकता होने पर इसे अलग से इंस्टॉल करना होगा।</p><div class='merke'><b>आपका पता</b>इसे मार्ग के आरंभिक बिंदु के रूप में भी उपयोग किया जाता है।</div>",
    "hsb": "<p>Pod kóždej kontaktowej kartu je rynk małych symbolowych tłóčatkow.</p><h3>List</h3><p><span class='knopfwort'>List</span> wutwori přihotowany dokument. Jeli je <b>LibreOffice Writer for Windows</b> instalowany a z dokumentom zwjazany, móže wuslědk wočinić. Wubjerće kompaktnu linku wotpósłarja abo předłohu <b>DIN 5008 Form B</b> z adresu za wokno, datumom, falcowanskimi markami a marku za dziurkowak.</p><p>Zapodajće swoju adresu pod <span class='knopfwort'>Nastajenja ▸ Kontakty</span>. LibreOffice njeje wobstatk Magnolie Organizer a dyrbi so po potrjebje separatnje instalować.</p><div class='merke'><b>Waša adresa</b>Wužiwa so tež jako spočatk roty.</div>",
    "it": "<p>Sotto ogni scheda di contatto si trova una fila di piccoli pulsanti con icone.</p><h3>Lettera</h3><p><span class='knopfwort'>Lettera</span> crea un documento già pronto. Se <b>LibreOffice Writer per Windows</b> è installato e associato al documento, può aprire il risultato. Scegliete una riga mittente compatta oppure un modello <b>DIN 5008 Form B</b> con indirizzo per busta a finestra, data, segni di piegatura e segno di foratura.</p><p>Inserite il vostro indirizzo in <span class='knopfwort'>Impostazioni ▸ Contatti</span>. LibreOffice non fa parte di Magnolie Organizer e va installato separatamente all'occorrenza.</p><div class='merke'><b>Il vostro indirizzo</b>Serve anche come punto di partenza di un itinerario.</div>",
    "ja": "<p>各連絡先カードの下には、小さなアイコンボタンが一列に並んでいます。</p><h3>手紙</h3><p><span class='knopfwort'>手紙</span> を使うと、準備済みの文書が作成されます。<b>LibreOffice Writer for Windows</b> がインストールされ、文書に関連付けられていれば、作成結果を開けます。簡潔な差出人行、または窓付き封筒用住所、日付、折り目、穴あけ位置を含む <b>DIN 5008 Form B</b> テンプレートを選べます。</p><p><span class='knopfwort'>設定 ▸ 連絡先</span> に自分の住所を入力します。LibreOffice は Magnolie Organizer に含まれていないため、必要に応じて別途インストールしてください。</p><div class='merke'><b>自分の住所</b>経路の出発地点としても使用されます。</div>",
    "nb": "<p>Under hvert kontaktkort finnes en rad med små ikonknapper.</p><h3>Brev</h3><p><span class='knopfwort'>Brev</span> oppretter et ferdig tilrettelagt dokument. Hvis <b>LibreOffice Writer for Windows</b> er installert og knyttet til dokumentet, kan det åpne resultatet. Velg en kompakt avsenderlinje eller en <b>DIN 5008 Form B</b>-mal med vindusadresse, dato, brettemerker og hullmerke.</p><p>Skriv inn adressen din under <span class='knopfwort'>Innstillinger ▸ Kontakter</span>. LibreOffice følger ikke med Magnolie Organizer og må om nødvendig installeres separat.</p><div class='merke'><b>Adressen din</b>Den brukes også som startpunkt for en rute.</div>",
    "nl": "<p>Onder elke contactkaart staat een rij kleine pictogramknoppen.</p><h3>Brief</h3><p><span class='knopfwort'>Brief</span> maakt een voorbereid document. Is <b>LibreOffice Writer voor Windows</b> geïnstalleerd en aan het document gekoppeld, dan kan het het resultaat openen. Kies een compacte afzenderregel of een sjabloon volgens <b>DIN 5008 Form B</b> met vensteradres, datum, vouwmarkeringen en perforatiemarkering.</p><p>Voer uw adres in bij <span class='knopfwort'>Instellingen ▸ Contacten</span>. LibreOffice hoort niet bij Magnolie Organizer en moet zo nodig apart worden geïnstalleerd.</p><div class='merke'><b>Uw adres</b>Het dient ook als beginpunt van een route.</div>",
    "pl": "<p>Pod każdą kartą kontaktu znajduje się rząd małych przycisków z ikonami.</p><h3>List</h3><p><span class='knopfwort'>List</span> tworzy przygotowany dokument. Jeśli <b>LibreOffice Writer for Windows</b> jest zainstalowany i skojarzony z dokumentem, może otworzyć wynik. Wybierz zwarty wiersz nadawcy albo szablon <b>DIN 5008 Form B</b> z adresem w okienku, datą, znacznikami zgięcia i znacznikiem dziurkowania.</p><p>Wpisz swój adres w <span class='knopfwort'>Ustawienia ▸ Kontakty</span>. LibreOffice nie jest częścią Magnolie Organizer i w razie potrzeby trzeba go zainstalować oddzielnie.</p><div class='merke'><b>Twój adres</b>Jest również używany jako punkt początkowy trasy.</div>",
    "pt": "<p>Por baixo de cada ficha de contacto há uma fila de pequenos botões com ícones.</p><h3>Carta</h3><p><span class='knopfwort'>Carta</span> cria um documento já preparado. Se o <b>LibreOffice Writer para Windows</b> estiver instalado e associado ao documento, pode abrir o resultado. Escolha uma linha de remetente compacta ou um modelo <b>DIN 5008 Form B</b> com endereço para envelope de janela, data, marcas de dobragem e marca de furação.</p><p>Introduza o seu endereço em <span class='knopfwort'>Definições ▸ Contactos</span>. O LibreOffice não faz parte do Magnolie Organizer e tem de ser instalado à parte, se necessário.</p><div class='merke'><b>O seu endereço</b>Serve também como ponto de partida de um itinerário.</div>",
    "ru": "<p>Под каждой карточкой контакта расположен ряд маленьких кнопок со значками.</p><h3>Письмо</h3><p><span class='knopfwort'>Письмо</span> создаёт подготовленный документ. Если <b>LibreOffice Writer for Windows</b> установлен и связан с документом, он может открыть результат. Выберите компактную строку отправителя или шаблон <b>DIN 5008 Form B</b> с адресом для окна конверта, датой, метками сгиба и меткой дырокола.</p><p>Введите свой адрес в <span class='knopfwort'>Настройки ▸ Контакты</span>. LibreOffice не входит в Magnolie Organizer и при необходимости устанавливается отдельно.</p><div class='merke'><b>Ваш адрес</b>Он также используется как начальная точка маршрута.</div>",
    "tr": "<p>Her kişi kartının altında küçük simge düğmelerinden oluşan bir sıra vardır.</p><h3>Mektup</h3><p><span class='knopfwort'>Mektup</span> hazırlanmış bir belge oluşturur. <b>LibreOffice Writer for Windows</b> kuruluysa ve belgeyle ilişkilendirilmişse sonucu açabilir. Kısa bir gönderen satırı veya pencere adresi, tarih, katlama işaretleri ve delgeç işareti içeren <b>DIN 5008 Form B</b> şablonunu seçin.</p><p>Adresinizi <span class='knopfwort'>Ayarlar ▸ Kişiler</span> bölümüne girin. LibreOffice, Magnolie Organizer ile birlikte gelmez ve gerekiyorsa ayrıca kurulmalıdır.</p><div class='merke'><b>Adresiniz</b>Bir rotanın başlangıç noktası olarak da kullanılır.</div>",
    "uk": "<p>Під кожною карткою контакту розташовано ряд малих кнопок із піктограмами.</p><h3>Лист</h3><p><span class='knopfwort'>Лист</span> створює підготовлений документ. Якщо <b>LibreOffice Writer for Windows</b> установлено й пов’язано з документом, він може відкрити результат. Виберіть компактний рядок відправника або шаблон <b>DIN 5008 Form B</b> з адресою для вікна конверта, датою, позначками згину та позначкою діркопробивача.</p><p>Введіть свою адресу в <span class='knopfwort'>Налаштування ▸ Контакти</span>. LibreOffice не входить до Magnolie Organizer і за потреби встановлюється окремо.</p><div class='merke'><b>Ваша адреса</b>Вона також використовується як початкова точка маршруту.</div>",
    "zh-cn": "<p>每张联系人卡片下方都有一排小图标按钮。</p><h3>信件</h3><p><span class='knopfwort'>信件</span>可创建准备好的文档。如果已安装 <b>LibreOffice Writer for Windows</b> 并将其与该文档关联，它便可打开结果。您可以选择紧凑的发件人行，或带窗口地址、日期、折叠标记和打孔标记的 <b>DIN 5008 Form B</b> 模板。</p><p>请在 <span class='knopfwort'>设置 ▸ 联系人</span> 中输入您的地址。Magnolie Organizer 不包含 LibreOffice，需要时必须另行安装。</p><div class='merke'><b>您的地址</b>该地址也用作路线的起点。</div>"
  },
  "maps-routes-and-messages": {
    "en": "<h3>Map and route</h3><p><span class='knopfwort'>Map</span> opens the address with OpenStreetMap or the selected map service in the Windows default browser. A route uses your saved address as its start.</p><h3>Email</h3><p>Click an email address or <span class='knopfwort'>Message</span> to open an addressed message in the Windows default mail application.</p><h3>Calls and SMS</h3><p>The phone icon can ask your paired Android phone to dial when <b>dial_request</b> is granted. Incoming-call display, answering, and ending are separately granted actions and remain subject to Android permissions and roles. Audio stays on the phone. The SMS icon composes through a paired <b>KDE Connect</b> device; Magnolie Notes and Personal Sync do not carry SMS.</p><h3>Social media</h3><p>Services saved under <b>More fields ▸ Social media</b> open through an installed Windows application or a secure HTTPS profile address.</p>",
    "de": "<h3>Karte und Route</h3><p><span class='knopfwort'>Karte</span> öffnet die Anschrift mit OpenStreetMap oder dem gewählten Kartendienst im Windows-Standardbrowser. Eine Route verwendet Ihre gespeicherte Anschrift als Start.</p><h3>E-Mail</h3><p>Klicken Sie eine E-Mail-Adresse oder <span class='knopfwort'>Nachricht</span> an, um eine adressierte Nachricht im Windows-Standardprogramm zu öffnen.</p><h3>Anrufe und SMS</h3><p>Das Hörersymbol kann Ihr gekoppeltes Android-Telefon mit der Freigabe <b>dial_request</b> zum Wählen auffordern. Anzeige eingehender Anrufe, Annehmen und Beenden sind getrennt freizugebende Aktionen und hängen zusätzlich von Android-Berechtigungen und -Rollen ab. Der Ton bleibt am Telefon. Das SMS-Symbol schreibt über ein gekoppeltes <b>KDE Connect</b>-Gerät; Magnolie Notes und der persönliche Abgleich übertragen keine SMS.</p><h3>Soziale Medien</h3><p>Unter <b>Weitere Felder ▸ Soziale Medien</b> gespeicherte Dienste öffnen sich über eine installierte Windows-Anwendung oder eine sichere HTTPS-Profiladresse.</p>",
    "ar": "<h3>الخريطة والمسار</h3><p>يفتح <span class='knopfwort'>الخريطة</span> العنوان باستخدام OpenStreetMap أو خدمة الخرائط المحددة في متصفح Windows الافتراضي. ويستخدم المسار عنوانك المحفوظ كنقطة بداية.</p><h3>البريد الإلكتروني</h3><p>انقر على عنوان بريد إلكتروني أو <span class='knopfwort'>رسالة</span> لفتح رسالة معنونة في تطبيق البريد الافتراضي في Windows.</p><h3>المكالمات والرسائل القصيرة</h3><p>يمكن لأيقونة الهاتف أن تطلب من هاتف Android المقترن إجراء اتصال عند منح <b dir='ltr'>dial_request</b>. ويخضع عرض المكالمات الواردة والرد عليها وإنهاؤها لإجراءات منح منفصلة، كما تظل خاضعة لأذونات Android وأدواره. يبقى الصوت على الهاتف. تنشئ أيقونة SMS الرسالة عبر جهاز <b dir='ltr'>KDE Connect</b> مقترن؛ ولا ينقل Magnolie Notes ولا مزامنة جهات الاتصال رسائل SMS.</p><h3>وسائل التواصل الاجتماعي</h3><p>تُفتح الخدمات المحفوظة ضمن <b>حقول إضافية ▸ وسائل التواصل الاجتماعي</b> بواسطة تطبيق Windows مثبت أو عنوان ملف تعريف آمن عبر HTTPS.</p>",
    "be": "<h3>Карта і маршрут</h3><p><span class='knopfwort'>Карта</span> адкрывае адрас у OpenStreetMap або выбраным картаграфічным сэрвісе ў прадвызначаным браўзеры Windows. Маршрут выкарыстоўвае ваш захаваны адрас як пачатак.</p><h3>Электронная пошта</h3><p>Пстрыкніце адрас электроннай пошты або <span class='knopfwort'>Паведамленне</span>, каб адкрыць адрасаванае паведамленне ў прадвызначанай паштовай праграме Windows.</p><h3>Выклікі і SMS</h3><p>Значок тэлефона можа папрасіць спалучаны Android-тэлефон набраць нумар, калі дадзены дазвол <b>dial_request</b>. Паказ уваходнага выкліку, адказ і завяршэнне з’яўляюцца асобна дазволенымі дзеяннямі і таксама залежаць ад дазволаў і роляў Android. Гук застаецца на тэлефоне. Значок SMS стварае паведамленне праз спалучаную прыладу <b>KDE Connect</b>; Magnolie Notes і Personal Sync не перадаюць SMS.</p><h3>Сацыяльныя сеткі</h3><p>Сэрвісы, захаваныя ў <b>Дадатковыя палі ▸ Сацыяльныя сеткі</b>, адкрываюцца праз усталяваную праграму Windows або бяспечны HTTPS-адрас профілю.</p>",
    "cs": "<h3>Mapa a trasa</h3><p><span class='knopfwort'>Mapa</span> otevře adresu v OpenStreetMap nebo zvolené mapové službě ve výchozím prohlížeči Windows. Trasa začíná na vaší uložené adrese.</p><h3>E-mail</h3><p>Klepnutím na e-mailovou adresu nebo <span class='knopfwort'>Zpráva</span> otevřete adresovanou zprávu ve výchozí poštovní aplikaci Windows.</p><h3>Hovory a SMS</h3><p>Ikona telefonu může požádat spárovaný telefon s Androidem o vytočení čísla, pokud je uděleno oprávnění <b>dial_request</b>. Zobrazení příchozího hovoru, přijetí a ukončení jsou samostatně povolované akce a nadále podléhají oprávněním a rolím Androidu. Zvuk zůstává v telefonu. Ikona SMS vytváří zprávu prostřednictvím spárovaného zařízení <b>KDE Connect</b>; Magnolie Notes ani Synchronizace kontaktů SMS nepřenášejí.</p><h3>Sociální sítě</h3><p>Služby uložené v části <b>Další pole ▸ Sociální sítě</b> se otevírají pomocí nainstalované aplikace Windows nebo bezpečné adresy profilu HTTPS.</p>",
    "da": "<h3>Kort og rute</h3><p><span class='knopfwort'>Kort</span> åbner adressen med OpenStreetMap eller den valgte korttjeneste i Windows' standardbrowser. En rute går ud fra din gemte adresse.</p><h3>E-mail</h3><p>Klik på en e-mailadresse eller på <span class='knopfwort'>Besked</span> for at åbne en adresseret besked i Windows' standardprogram til e-mail.</p><h3>Opkald og sms</h3><p>Telefonikonet kan bede din parrede Android-telefon om at ringe op, når <b>dial_request</b> er givet. Visning af indgående opkald, at tage og at afslutte opkald er handlinger, der gives hver for sig, og de er fortsat underlagt Androids tilladelser og roller. Lyden bliver på telefonen. Sms-ikonet skriver beskeden via en parret <b>KDE Connect</b>-enhed; Magnolie Notes og Personal Sync transporterer ikke sms.</p><h3>Sociale medier</h3><p>Tjenester, der er gemt under <b>Flere felter ▸ Sociale medier</b>, åbnes via et installeret Windows-program eller en sikker HTTPS-profiladresse.</p>",
    "es": "<h3>Mapa y ruta</h3><p><span class='knopfwort'>Mapa</span> abre la dirección con OpenStreetMap o con el servicio de mapas elegido, en el navegador predeterminado de Windows. Una ruta parte de su dirección guardada.</p><h3>Correo electrónico</h3><p>Haga clic en una dirección de correo o en <span class='knopfwort'>Mensaje</span> para abrir un mensaje ya dirigido en la aplicación de correo predeterminada de Windows.</p><h3>Llamadas y SMS</h3><p>El icono del teléfono puede pedir a su teléfono Android emparejado que marque el número cuando se ha concedido <b>dial_request</b>. Mostrar las llamadas entrantes, descolgar y colgar son acciones que se conceden por separado y siguen sujetas a los permisos y roles de Android. El sonido permanece en el teléfono. El icono de SMS redacta el mensaje mediante un dispositivo <b>KDE Connect</b> emparejado; Magnolie Notes y Personal Sync no transportan SMS.</p><h3>Redes sociales</h3><p>Los servicios guardados en <b>Más campos ▸ Redes sociales</b> se abren mediante una aplicación de Windows instalada o una dirección de perfil HTTPS segura.</p>",
    "fr": "<h3>Carte et itinéraire</h3><p><span class='knopfwort'>Carte</span> ouvre l’adresse avec OpenStreetMap ou le service de cartographie choisi, dans le navigateur par défaut de Windows. Un itinéraire part de votre adresse enregistrée.</p><h3>Courriel</h3><p>Cliquez sur une adresse électronique ou sur <span class='knopfwort'>Message</span> pour ouvrir un message déjà adressé dans l’application de messagerie par défaut de Windows.</p><h3>Appels et SMS</h3><p>L’icône du téléphone peut demander à votre téléphone Android appairé de composer le numéro lorsque <b>dial_request</b> est accordé. L’affichage des appels entrants, la prise et la fin d’appel sont des actions accordées séparément et restent soumises aux autorisations et aux rôles Android. Le son reste sur le téléphone. L’icône SMS rédige le message via un appareil <b>KDE Connect</b> appairé ; Magnolie Notes et Personal Sync ne transportent pas de SMS.</p><h3>Réseaux sociaux</h3><p>Les services enregistrés sous <b>Autres champs ▸ Réseaux sociaux</b> s’ouvrent via une application Windows installée ou une adresse de profil HTTPS sécurisée.</p>",
    "hi": "<h3>मानचित्र और मार्ग</h3><p><span class='knopfwort'>मानचित्र</span> पते को OpenStreetMap या चुनी हुई नक्शा सेवा के साथ Windows के डिफ़ॉल्ट ब्राउज़र में खोलता है। मार्ग आपके सहेजे हुए पते को आरंभिक बिंदु के रूप में उपयोग करता है।</p><h3>ईमेल</h3><p>Windows के डिफ़ॉल्ट मेल एप्लिकेशन में पते सहित संदेश खोलने के लिए किसी ईमेल पते या <span class='knopfwort'>संदेश</span> पर क्लिक करें।</p><h3>कॉल और SMS</h3><p><b>dial_request</b> की अनुमति मिलने पर फ़ोन आइकन आपके युग्मित Android फ़ोन से नंबर मिलाने को कह सकता है। आने वाली कॉल दिखाना, उत्तर देना और समाप्त करना अलग-अलग स्वीकृत क्रियाएँ हैं और उन पर Android अनुमतियाँ और भूमिकाएँ भी लागू रहती हैं। ऑडियो फ़ोन पर ही रहता है। SMS आइकन युग्मित <b>KDE Connect</b> डिवाइस के माध्यम से संदेश तैयार करता है; Magnolie Notes और संपर्क सिंक्रनाइज़ेशन SMS नहीं पहुँचाते।</p><h3>सोशल मीडिया</h3><p><b>और फ़ील्ड ▸ सोशल मीडिया</b> में सहेजी गई सेवाएँ किसी इंस्टॉल किए गए Windows एप्लिकेशन या सुरक्षित HTTPS प्रोफ़ाइल पते से खुलती हैं।</p>",
    "hsb": "<h3>Karta a rota</h3><p><span class='knopfwort'>Karta</span> wočini adresu z OpenStreetMap abo wubranej kartowej słužbu w standardnym wobhladowaku Windows. Rota wužiwa wašu składowanu adresu jako spočatk.</p><h3>E-mejl</h3><p>Klikńće na e-mejlowu adresu abo <span class='knopfwort'>Powěsć</span>, zo byšće adresowanu powěsć w standardnym mejlowym nałoženju Windows wočinili.</p><h3>Zawołanja a SMS</h3><p>Telefonowy symbol móže sparowany telefon z Androidom wo wuzwolenje čisła prosyć, hdyž je <b>dial_request</b> dowoleny. Pokazanje dochadźaceho zawołanja, přiwzaće a skónčenje su separatnje dowolene akcije a wostanu wot dowolnosćow a rólow Androida wotwisne. Zynk wostanje na telefonje. SMS-symbol zestaja powěsć přez sparowany grat <b>KDE Connect</b>; Magnolie Notes a Synchronizacija kontaktow SMS njepřenjesujetej.</p><h3>Socialne medije</h3><p>Słužby, kotrež su pod <b>Dalše pola ▸ Socialne medije</b> składowane, so přez instalowane nałoženje Windows abo wěstu HTTPS-adresu profila wočinjeja.</p>",
    "it": "<h3>Mappa e itinerario</h3><p><span class='knopfwort'>Mappa</span> apre l'indirizzo con OpenStreetMap o con il servizio di mappe scelto, nel browser predefinito di Windows. Un itinerario parte dal vostro indirizzo salvato.</p><h3>Posta elettronica</h3><p>Fate clic su un indirizzo di posta o su <span class='knopfwort'>Messaggio</span> per aprire un messaggio già indirizzato nell'applicazione di posta predefinita di Windows.</p><h3>Chiamate e SMS</h3><p>L'icona del telefono può chiedere al vostro telefono Android accoppiato di comporre il numero quando è concesso <b>dial_request</b>. La visualizzazione delle chiamate in arrivo, la risposta e la chiusura sono azioni concesse separatamente e restano soggette alle autorizzazioni e ai ruoli di Android. L'audio resta sul telefono. L'icona SMS scrive il messaggio tramite un dispositivo <b>KDE Connect</b> accoppiato; Magnolie Notes e Personal Sync non trasportano SMS.</p><h3>Social media</h3><p>I servizi salvati in <b>Altri campi ▸ Social media</b> si aprono tramite un'applicazione Windows installata o un indirizzo di profilo HTTPS sicuro.</p>",
    "ja": "<h3>地図と経路</h3><p><span class='knopfwort'>地図</span> は、OpenStreetMap または選択した地図サービスを使って、Windows の既定のブラウザーで住所を開きます。経路では保存済みの自分の住所が出発地点になります。</p><h3>メール</h3><p>メールアドレスまたは <span class='knopfwort'>メッセージ</span> をクリックすると、Windows の既定のメールアプリケーションで宛先入力済みのメッセージが開きます。</p><h3>通話と SMS</h3><p><b>dial_request</b> が許可されていれば、電話アイコンからペアリング済み Android スマートフォンに発信を依頼できます。着信表示、応答、終了は個別に許可する操作であり、Android の権限とロールにも従います。音声はスマートフォン側に残ります。SMS アイコンはペアリング済みの <b>KDE Connect</b> デバイスを介してメッセージを作成します。Magnolie Notes と連絡先の同期は SMS を転送しません。</p><h3>ソーシャルメディア</h3><p><b>その他のフィールド ▸ ソーシャルメディア</b> に保存したサービスは、インストール済み Windows アプリケーションまたは安全な HTTPS プロフィールアドレスで開きます。</p>",
    "nb": "<h3>Kart og rute</h3><p><span class='knopfwort'>Kart</span> åpner adressen med OpenStreetMap eller den valgte karttjenesten i standardnettleseren i Windows. En rute bruker den lagrede adressen din som start.</p><h3>E-post</h3><p>Klikk på en e-postadresse eller <span class='knopfwort'>Melding</span> for å åpne en adressert melding i standard e-postprogram i Windows.</p><h3>Anrop og SMS</h3><p>Telefonikonet kan be den parede Android-telefonen om å ringe når <b>dial_request</b> er innvilget. Visning av innkommende anrop, svar og avslutning er separat innvilgede handlinger og er fortsatt underlagt Android-tillatelser og -roller. Lyden forblir på telefonen. SMS-ikonet skriver via en paret <b>KDE Connect</b>-enhet; Magnolie Notes og Personal Sync overfører ikke SMS.</p><h3>Sosiale medier</h3><p>Tjenester som er lagret under <b>Flere felt ▸ Sosiale medier</b>, åpnes gjennom et installert Windows-program eller en sikker HTTPS-profiladresse.</p>",
    "nl": "<h3>Kaart en route</h3><p><span class='knopfwort'>Kaart</span> opent het adres met OpenStreetMap of met de gekozen kaartdienst in de standaardbrowser van Windows. Een route begint bij uw opgeslagen adres.</p><h3>E-mail</h3><p>Klik op een e-mailadres of op <span class='knopfwort'>Bericht</span> om een geadresseerd bericht te openen in de standaard-e-mailtoepassing van Windows.</p><h3>Bellen en sms</h3><p>Het telefoonpictogram kan uw gekoppelde Android-telefoon vragen te bellen wanneer <b>dial_request</b> is verleend. Weergave van inkomende oproepen, opnemen en beëindigen zijn afzonderlijk verleende acties en blijven onderworpen aan de rechten en rollen van Android. Het geluid blijft op de telefoon. Het sms-pictogram stelt het bericht op via een gekoppeld <b>KDE Connect</b>-apparaat; Magnolie Notes en Personal Sync vervoeren geen sms.</p><h3>Sociale media</h3><p>Diensten die onder <b>Meer velden ▸ Sociale media</b> zijn opgeslagen, openen via een geïnstalleerde Windows-toepassing of een beveiligd HTTPS-profieladres.</p>",
    "pl": "<h3>Mapa i trasa</h3><p><span class='knopfwort'>Mapa</span> otwiera adres w OpenStreetMap lub wybranej usłudze mapowej w domyślnej przeglądarce Windows. Trasa rozpoczyna się pod zapisanym adresem użytkownika.</p><h3>E-mail</h3><p>Kliknij adres e-mail lub <span class='knopfwort'>Wiadomość</span>, aby otworzyć zaadresowaną wiadomość w domyślnej aplikacji pocztowej Windows.</p><h3>Połączenia i SMS</h3><p>Ikona telefonu może poprosić sparowany telefon z Androidem o wybranie numeru, jeśli udzielono <b>dial_request</b>. Wyświetlanie połączenia przychodzącego, odbieranie i kończenie są osobno przyznawanymi działaniami i nadal podlegają uprawnieniom oraz rolom Androida. Dźwięk pozostaje w telefonie. Ikona SMS tworzy wiadomość przez sparowane urządzenie <b>KDE Connect</b>; Magnolie Notes i Synchronizacja kontaktów nie przenoszą SMS-ów.</p><h3>Media społecznościowe</h3><p>Usługi zapisane w <b>Więcej pól ▸ Media społecznościowe</b> otwierają się w zainstalowanej aplikacji Windows lub pod bezpiecznym adresem profilu HTTPS.</p>",
    "pt": "<h3>Mapa e itinerário</h3><p><span class='knopfwort'>Mapa</span> abre o endereço com o OpenStreetMap ou com o serviço de mapas escolhido, no navegador predefinido do Windows. Um itinerário parte do seu endereço guardado.</p><h3>Correio eletrónico</h3><p>Clique num endereço de correio ou em <span class='knopfwort'>Mensagem</span> para abrir uma mensagem já endereçada na aplicação de correio predefinida do Windows.</p><h3>Chamadas e SMS</h3><p>O ícone do telefone pode pedir ao seu telemóvel Android emparelhado que marque o número quando <b>dial_request</b> estiver concedido. Mostrar chamadas recebidas, atender e desligar são ações concedidas em separado e continuam sujeitas às permissões e aos papéis do Android. O som permanece no telemóvel. O ícone de SMS redige a mensagem através de um dispositivo <b>KDE Connect</b> emparelhado; o Magnolie Notes e o Personal Sync não transportam SMS.</p><h3>Redes sociais</h3><p>Os serviços guardados em <b>Mais campos ▸ Redes sociais</b> abrem-se através de uma aplicação do Windows instalada ou de um endereço de perfil HTTPS seguro.</p>",
    "ru": "<h3>Карта и маршрут</h3><p><span class='knopfwort'>Карта</span> открывает адрес в OpenStreetMap или выбранной картографической службе в браузере Windows по умолчанию. Маршрут начинается с вашего сохранённого адреса.</p><h3>Электронная почта</h3><p>Щёлкните адрес электронной почты или <span class='knopfwort'>Сообщение</span>, чтобы открыть адресованное сообщение в почтовом приложении Windows по умолчанию.</p><h3>Звонки и SMS</h3><p>Значок телефона может попросить сопряжённый телефон Android набрать номер, если предоставлено разрешение <b>dial_request</b>. Показ входящего звонка, ответ и завершение являются отдельно разрешаемыми действиями и также зависят от разрешений и ролей Android. Звук остаётся на телефоне. Значок SMS составляет сообщение через сопряжённое устройство <b>KDE Connect</b>; Magnolie Notes и Personal Sync не передают SMS.</p><h3>Социальные сети</h3><p>Службы, сохранённые в <b>Дополнительные поля ▸ Социальные сети</b>, открываются через установленное приложение Windows или безопасный HTTPS-адрес профиля.</p>",
    "tr": "<h3>Harita ve rota</h3><p><span class='knopfwort'>Harita</span>, adresi OpenStreetMap veya seçilen harita hizmetiyle varsayılan Windows tarayıcısında açar. Rota, kayıtlı adresinizi başlangıç olarak kullanır.</p><h3>E-posta</h3><p>Varsayılan Windows posta uygulamasında adreslenmiş bir ileti açmak için e-posta adresine veya <span class='knopfwort'>İleti</span> düğmesine tıklayın.</p><h3>Aramalar ve SMS</h3><p><b>dial_request</b> izni verildiğinde telefon simgesi eşleştirilmiş Android telefonunuzdan numarayı çevirmesini isteyebilir. Gelen aramayı gösterme, yanıtlama ve sonlandırma ayrı ayrı izin verilen eylemlerdir ve Android izinleri ile rollerine bağlı kalır. Ses telefonda kalır. SMS simgesi eşleştirilmiş bir <b>KDE Connect</b> aygıtı üzerinden ileti oluşturur; Magnolie Notes ve Kişi eşzamanlama SMS taşımaz.</p><h3>Sosyal medya</h3><p><b>Daha fazla alan ▸ Sosyal medya</b> altında kayıtlı hizmetler, kurulu bir Windows uygulaması veya güvenli bir HTTPS profil adresi üzerinden açılır.</p>",
    "uk": "<h3>Карта й маршрут</h3><p><span class='knopfwort'>Карта</span> відкриває адресу в OpenStreetMap або вибраній картографічній службі в типовому браузері Windows. Маршрут починається з вашої збереженої адреси.</p><h3>Електронна пошта</h3><p>Клацніть адресу електронної пошти або <span class='knopfwort'>Повідомлення</span>, щоб відкрити адресоване повідомлення в типовій поштовій програмі Windows.</p><h3>Виклики та SMS</h3><p>Піктограма телефону може попросити сполучений Android-телефон набрати номер, якщо надано дозвіл <b>dial_request</b>. Показ вхідного виклику, відповідь і завершення є окремо дозволеними діями й надалі залежать від дозволів і ролей Android. Звук залишається на телефоні. Піктограма SMS складає повідомлення через сполучений пристрій <b>KDE Connect</b>; Magnolie Notes і Personal Sync не передають SMS.</p><h3>Соціальні мережі</h3><p>Служби, збережені в <b>Додаткові поля ▸ Соціальні мережі</b>, відкриваються через установлену програму Windows або безпечну HTTPS-адресу профілю.</p>",
    "zh-cn": "<h3>地图和路线</h3><p><span class='knopfwort'>地图</span>使用 OpenStreetMap 或所选地图服务，在 Windows 默认浏览器中打开地址。路线使用您保存的地址作为起点。</p><h3>电子邮件</h3><p>点击电子邮件地址或 <span class='knopfwort'>消息</span>，可在 Windows 默认邮件应用程序中打开已填写收件人的邮件。</p><h3>通话和 SMS</h3><p>授予 <b>dial_request</b> 后，电话图标可请求已配对的 Android 手机拨号。来电显示、接听和挂断是分别授权的操作，并且仍受 Android 权限和角色约束。音频留在手机上。SMS 图标通过已配对的 <b>KDE Connect</b> 设备编写消息；Magnolie Notes 和联系人同步不传输 SMS。</p><h3>社交媒体</h3><p>保存在<b>更多字段 ▸ 社交媒体</b>下的服务会通过已安装的 Windows 应用程序或安全的 HTTPS 个人资料地址打开。</p>"
  },
  "appointment-reminders": {
    "en": "<p>The Organizer can remind you of appointments and due tasks while Magnolie Organizer is running or remains open in the Windows notification area.</p><ol class='schritte'><li>Open <span class='knopfwort'>Settings ▸ Notification</span>.</li><li>Enable reminders.</li><li>Select the required lead time.</li><li>Close the settings sheet.</li></ol><p>If you minimize or close the window to the notification area, reminders continue. If you quit the application completely, no reminders are generated until the next launch.</p><h3>Missed appointments</h3><p>On the next launch, the Organizer can report missed appointments if that option is enabled.</p><div class='merke'><b>Try a preview</b>Use <span class='knopfwort'>Show preview</span> to test the display and sound.</div>",
    "de": "<p>Der Organizer kann Sie an Termine und fällige Aufgaben erinnern, solange Magnolie Organizer läuft oder im Windows-Infobereich geöffnet bleibt.</p><ol class='schritte'><li>Öffnen Sie <span class='knopfwort'>Einstellungen ▸ Benachrichtigung</span>.</li><li>Schalten Sie Erinnerungen ein.</li><li>Wählen Sie den gewünschten Vorlauf.</li><li>Schließen Sie das Einstellungsblatt.</li></ol><p>Beim Minimieren oder Schließen in den Infobereich laufen Erinnerungen weiter. Beenden Sie die Anwendung vollständig, werden bis zum nächsten Start keine Erinnerungen ausgelöst.</p><h3>Verpasste Termine</h3><p>Nach dem nächsten Start kann der Organizer verpasste Termine melden, wenn diese Option eingeschaltet ist.</p><div class='merke'><b>Vorschau prüfen</b>Mit <span class='knopfwort'>Vorschau anzeigen</span> testen Sie Anzeige und Klang.</div>",
    "ar": "<p>يمكن لـ Organizer تذكيرك بالمواعيد والمهام المستحقة ما دام Magnolie Organizer قيد التشغيل أو مفتوحا في منطقة إعلام Windows.</p><ol class='schritte'><li>افتح <span class='knopfwort'>الإعدادات ▸ الإشعارات</span>.</li><li>فعّل التذكيرات.</li><li>حدد مهلة التنبيه المطلوبة.</li><li>أغلق صفحة الإعدادات.</li></ol><p>إذا صغرت النافذة أو أغلقتها إلى منطقة الإعلام، تستمر التذكيرات. وإذا أنهيت التطبيق بالكامل، فلن تُنشأ تذكيرات حتى التشغيل التالي.</p><h3>المواعيد الفائتة</h3><p>عند التشغيل التالي، يمكن لـ Organizer الإبلاغ عن المواعيد الفائتة إذا كان هذا الخيار مفعلا.</p><div class='merke'><b>جرّب معاينة</b>استخدم <span class='knopfwort'>إظهار المعاينة</span> لاختبار العرض والصوت.</div>",
    "be": "<p>Organizer можа нагадваць пра сустрэчы і заданні з тэрмінам, пакуль Magnolie Organizer працуе або застаецца адкрытым у вобласці апавяшчэнняў Windows.</p><ol class='schritte'><li>Адкрыйце <span class='knopfwort'>Налады ▸ Апавяшчэнні</span>.</li><li>Уключыце напаміны.</li><li>Выберыце патрэбны папярэдні інтэрвал.</li><li>Закрыйце аркуш налад.</li></ol><p>Калі згарнуць або закрыць акно ў вобласць апавяшчэнняў, напаміны працягнуць працаваць. Калі цалкам выйсці з праграмы, да наступнага запуску напаміны не ствараюцца.</p><h3>Прапушчаныя сустрэчы</h3><p>Пры наступным запуску Organizer можа паведаміць пра прапушчаныя сустрэчы, калі гэтая функцыя ўключана.</p><div class='merke'><b>Праверце папярэдні прагляд</b>Выкарыстайце <span class='knopfwort'>Паказаць папярэдні прагляд</span>, каб праверыць выгляд і гук.</div>",
    "cs": "<p>Organizer může připomínat schůzky a splatné úkoly, když Magnolie Organizer běží nebo zůstává otevřený v oznamovací oblasti Windows.</p><ol class='schritte'><li>Otevřete <span class='knopfwort'>Nastavení ▸ Oznámení</span>.</li><li>Zapněte připomínky.</li><li>Vyberte požadovaný předstih.</li><li>Zavřete list nastavení.</li></ol><p>Při minimalizaci nebo zavření okna do oznamovací oblasti připomínky pokračují. Ukončíte-li aplikaci úplně, do dalšího spuštění se žádné připomínky nevytvářejí.</p><h3>Zmeškané schůzky</h3><p>Při příštím spuštění může Organizer hlásit zmeškané schůzky, je-li tato možnost zapnuta.</p><div class='merke'><b>Vyzkoušejte náhled</b>Pomocí <span class='knopfwort'>Zobrazit náhled</span> otestujte zobrazení a zvuk.</div>",
    "da": "<p>Organizeren kan minde dig om aftaler og forfaldne opgaver, så længe Magnolie Organizer kører eller forbliver åben i Windows' meddelelsesområde.</p><ol class='schritte'><li>Åbn <span class='knopfwort'>Indstillinger ▸ Meddelelser</span>.</li><li>Slå påmindelser til.</li><li>Vælg det ønskede varsel.</li><li>Luk indstillingsarket.</li></ol><p>Minimerer eller lukker du vinduet til meddelelsesområdet, fortsætter påmindelserne. Afslutter du programmet helt, udløses ingen påmindelser før næste start.</p><h3>Mistede aftaler</h3><p>Ved næste start kan Organizeren melde mistede aftaler, hvis den indstilling er slået til.</p><div class='merke'><b>Prøv en forhåndsvisning</b>Brug <span class='knopfwort'>Vis forhåndsvisning</span> til at afprøve visning og lyd.</div>",
    "es": "<p>El Organizador puede recordarle citas y tareas pendientes mientras Magnolie Organizer esté en ejecución o siga abierto en el área de notificación de Windows.</p><ol class='schritte'><li>Abra <span class='knopfwort'>Ajustes ▸ Notificaciones</span>.</li><li>Active los recordatorios.</li><li>Elija la antelación deseada.</li><li>Cierre la hoja de ajustes.</li></ol><p>Si minimiza o cierra la ventana en el área de notificación, los recordatorios continúan. Si cierra la aplicación por completo, no se genera ningún recordatorio hasta el siguiente inicio.</p><h3>Citas perdidas</h3><p>En el siguiente inicio, el Organizador puede informar de las citas perdidas si esa opción está activada.</p><div class='merke'><b>Pruebe una vista previa</b>Utilice <span class='knopfwort'>Mostrar vista previa</span> para comprobar la presentación y el sonido.</div>",
    "fr": "<p>L’Organizer peut vous rappeler vos rendez-vous et vos tâches à échéance tant que Magnolie Organizer est en cours d’exécution ou reste ouvert dans la zone de notification de Windows.</p><ol class='schritte'><li>Ouvrez <span class='knopfwort'>Paramètres ▸ Notifications</span>.</li><li>Activez les rappels.</li><li>Choisissez le délai de préavis souhaité.</li><li>Fermez la feuille des paramètres.</li></ol><p>Si vous réduisez ou fermez la fenêtre dans la zone de notification, les rappels se poursuivent. Si vous quittez complètement l’application, plus aucun rappel n’est déclenché jusqu’au prochain démarrage.</p><h3>Rendez-vous manqués</h3><p>Au démarrage suivant, l’Organizer peut signaler les rendez-vous manqués si cette option est activée.</p><div class='merke'><b>Essayez un aperçu</b>Utilisez <span class='knopfwort'>Afficher l’aperçu</span> pour tester l’affichage et le son.</div>",
    "hi": "<p>जब Magnolie Organizer चल रहा हो या Windows सूचना क्षेत्र में खुला रहे, तब Organizer आपको अपॉइंटमेंट और नियत कार्यों की याद दिला सकता है।</p><ol class='schritte'><li><span class='knopfwort'>सेटिंग्स ▸ सूचनाएँ</span> खोलें।</li><li>रिमाइंडर चालू करें।</li><li>आवश्यक अग्रिम समय चुनें।</li><li>सेटिंग्स पृष्ठ बंद करें।</li></ol><p>यदि आप विंडो को छोटा करते हैं या सूचना क्षेत्र में बंद करते हैं, तो रिमाइंडर जारी रहते हैं। यदि एप्लिकेशन पूरी तरह बंद कर देते हैं, तो अगली बार शुरू होने तक कोई रिमाइंडर नहीं बनता।</p><h3>छूटे हुए अपॉइंटमेंट</h3><p>विकल्प चालू होने पर अगली बार शुरू होने पर Organizer छूटे हुए अपॉइंटमेंट की सूचना दे सकता है।</p><div class='merke'><b>पूर्वावलोकन आजमाएँ</b>डिस्प्ले और ध्वनि जाँचने के लिए <span class='knopfwort'>पूर्वावलोकन दिखाएँ</span> का उपयोग करें।</div>",
    "hsb": "<p>Organizer móže was na terminy a dospěte nadawki dopominać, doniž Magnolie Organizer běži abo we wobłuku zdźělenkow Windows wočinjeny wostanje.</p><ol class='schritte'><li>Wočińće <span class='knopfwort'>Nastajenja ▸ Zdźělenki</span>.</li><li>Zmóžńće dopominanja.</li><li>Wubjerće trěbny předčas.</li><li>Začińće łopjeno nastajenjow.</li></ol><p>Po miniměrowanju abo začinjenju wokna do wobłuka zdźělenkow dopominanja dale běža. Hdyž nałoženje dospołnje skónčiće, so hač do přichodneho starta žane dopominanja njewutworja.</p><h3>Zapasene terminy</h3><p>Při přichodnym starće móže Organizer zapasene terminy zdźělić, jeli je tuta opcija zmóžnjena.</p><div class='merke'><b>Přehlad wupruwować</b>Wužiwajće <span class='knopfwort'>Přehlad pokazać</span>, zo byšće pokazanje a zynk testowali.</div>",
    "it": "<p>L'Organizer può ricordarvi appuntamenti e attività in scadenza finché Magnolie Organizer è in esecuzione o resta aperto nell'area di notifica di Windows.</p><ol class='schritte'><li>Aprite <span class='knopfwort'>Impostazioni ▸ Notifiche</span>.</li><li>Attivate i promemoria.</li><li>Scegliete l'anticipo desiderato.</li><li>Chiudete il foglio delle impostazioni.</li></ol><p>Se riducete a icona o chiudete la finestra nell'area di notifica, i promemoria proseguono. Se chiudete completamente l'applicazione, non viene generato alcun promemoria fino al prossimo avvio.</p><h3>Appuntamenti mancati</h3><p>Al prossimo avvio l'Organizer può segnalare gli appuntamenti mancati, se l'opzione è attiva.</p><div class='merke'><b>Provate un'anteprima</b>Usate <span class='knopfwort'>Mostra anteprima</span> per verificare visualizzazione e suono.</div>",
    "ja": "<p>Magnolie Organizer の実行中、または Windows の通知領域で開いたままになっている間、Organizer は予定や期限の来たタスクを通知できます。</p><ol class='schritte'><li><span class='knopfwort'>設定 ▸ 通知</span> を開きます。</li><li>リマインダーを有効にします。</li><li>必要な事前通知時間を選びます。</li><li>設定シートを閉じます。</li></ol><p>ウィンドウを通知領域に最小化または閉じても、通知は続きます。アプリケーションを完全に終了すると、次回起動まで通知は生成されません。</p><h3>見逃した予定</h3><p>このオプションが有効なら、次回起動時に見逃した予定を Organizer が報告できます。</p><div class='merke'><b>プレビューを試す</b><span class='knopfwort'>プレビューを表示</span> で表示と音をテストできます。</div>",
    "nb": "<p>Organizeren kan minne deg på avtaler og forfalte oppgaver mens Magnolie Organizer kjører eller forblir åpent i systemstatusfeltet i Windows.</p><ol class='schritte'><li>Åpne <span class='knopfwort'>Innstillinger ▸ Varsling</span>.</li><li>Slå på påminnelser.</li><li>Velg ønsket varslingstid.</li><li>Lukk innstillingsarket.</li></ol><p>Hvis du minimerer eller lukker vinduet til systemstatusfeltet, fortsetter påminnelsene. Hvis du avslutter programmet helt, genereres ingen påminnelser før neste oppstart.</p><h3>Tapte avtaler</h3><p>Ved neste oppstart kan Organizeren rapportere tapte avtaler hvis dette valget er slått på.</p><div class='merke'><b>Prøv en forhåndsvisning</b>Bruk <span class='knopfwort'>Vis forhåndsvisning</span> for å teste visning og lyd.</div>",
    "nl": "<p>De Organizer kan u aan afspraken en te vervallen taken herinneren zolang Magnolie Organizer draait of geopend blijft in het Windows-systeemvak.</p><ol class='schritte'><li>Open <span class='knopfwort'>Instellingen ▸ Meldingen</span>.</li><li>Schakel herinneringen in.</li><li>Kies de gewenste voorlooptijd.</li><li>Sluit het instellingenblad.</li></ol><p>Verkleint of sluit u het venster naar het systeemvak, dan gaan de herinneringen door. Sluit u de toepassing volledig af, dan wordt tot de volgende start geen herinnering gegeven.</p><h3>Gemiste afspraken</h3><p>Bij de volgende start kan de Organizer gemiste afspraken melden, als die optie is ingeschakeld.</p><div class='merke'><b>Probeer een voorbeeld</b>Gebruik <span class='knopfwort'>Voorbeeld tonen</span> om weergave en geluid te testen.</div>",
    "pl": "<p>Organizer może przypominać o spotkaniach i zadaniach z terminem, dopóki Magnolie Organizer działa lub pozostaje otwarty w obszarze powiadomień Windows.</p><ol class='schritte'><li>Otwórz <span class='knopfwort'>Ustawienia ▸ Powiadomienia</span>.</li><li>Włącz przypomnienia.</li><li>Wybierz wymagane wyprzedzenie.</li><li>Zamknij arkusz ustawień.</li></ol><p>Po zminimalizowaniu lub zamknięciu okna do obszaru powiadomień przypomnienia nadal działają. Po całkowitym zakończeniu aplikacji przypomnienia nie są tworzone aż do następnego uruchomienia.</p><h3>Przegapione spotkania</h3><p>Przy następnym uruchomieniu Organizer może zgłosić przegapione spotkania, jeśli ta opcja jest włączona.</p><div class='merke'><b>Wypróbuj podgląd</b>Użyj <span class='knopfwort'>Pokaż podgląd</span>, aby sprawdzić wygląd i dźwięk.</div>",
    "pt": "<p>O Organizador pode lembrá-lo de compromissos e tarefas a vencer enquanto o Magnolie Organizer estiver em execução ou continuar aberto na área de notificação do Windows.</p><ol class='schritte'><li>Abra <span class='knopfwort'>Definições ▸ Notificações</span>.</li><li>Ative os lembretes.</li><li>Escolha a antecedência pretendida.</li><li>Feche a folha de definições.</li></ol><p>Se minimizar ou fechar a janela na área de notificação, os lembretes continuam. Se sair completamente da aplicação, não é gerado qualquer lembrete até ao arranque seguinte.</p><h3>Compromissos perdidos</h3><p>No arranque seguinte, o Organizador pode comunicar os compromissos perdidos, se essa opção estiver ativada.</p><div class='merke'><b>Experimente uma pré-visualização</b>Utilize <span class='knopfwort'>Mostrar pré-visualização</span> para testar a apresentação e o som.</div>",
    "ru": "<p>Organizer может напоминать о встречах и задачах с истекающим сроком, пока Magnolie Organizer работает или остаётся открытым в области уведомлений Windows.</p><ol class='schritte'><li>Откройте <span class='knopfwort'>Настройки ▸ Уведомления</span>.</li><li>Включите напоминания.</li><li>Выберите требуемое время упреждения.</li><li>Закройте лист настроек.</li></ol><p>После сворачивания или закрытия окна в область уведомлений напоминания продолжают работать. Если полностью завершить приложение, напоминания не создаются до следующего запуска.</p><h3>Пропущенные встречи</h3><p>При следующем запуске Organizer может сообщить о пропущенных встречах, если эта функция включена.</p><div class='merke'><b>Попробуйте предпросмотр</b>Используйте <span class='knopfwort'>Показать предпросмотр</span>, чтобы проверить изображение и звук.</div>",
    "tr": "<p>Magnolie Organizer çalışırken veya Windows bildirim alanında açık kalırken Organizer size randevuları ve süresi gelen görevleri hatırlatabilir.</p><ol class='schritte'><li><span class='knopfwort'>Ayarlar ▸ Bildirimler</span> bölümünü açın.</li><li>Hatırlatıcıları etkinleştirin.</li><li>İstenen ön uyarı süresini seçin.</li><li>Ayarlar sayfasını kapatın.</li></ol><p>Pencereyi bildirim alanına küçültür veya kapatırsanız hatırlatıcılar devam eder. Uygulamadan tamamen çıkarsanız bir sonraki başlatmaya kadar hatırlatıcı oluşturulmaz.</p><h3>Kaçırılan randevular</h3><p>Seçenek etkinse Organizer bir sonraki başlatmada kaçırılan randevuları bildirebilir.</p><div class='merke'><b>Önizlemeyi deneyin</b>Görüntü ve sesi sınamak için <span class='knopfwort'>Önizlemeyi göster</span> seçeneğini kullanın.</div>",
    "uk": "<p>Organizer може нагадувати про зустрічі й завдання з терміном, доки Magnolie Organizer працює або залишається відкритим в області сповіщень Windows.</p><ol class='schritte'><li>Відкрийте <span class='knopfwort'>Налаштування ▸ Сповіщення</span>.</li><li>Увімкніть нагадування.</li><li>Виберіть потрібний час випередження.</li><li>Закрийте аркуш налаштувань.</li></ol><p>Після згортання або закриття вікна в область сповіщень нагадування продовжують працювати. Якщо повністю завершити програму, нагадування не створюються до наступного запуску.</p><h3>Пропущені зустрічі</h3><p>Під час наступного запуску Organizer може повідомити про пропущені зустрічі, якщо цю функцію ввімкнено.</p><div class='merke'><b>Спробуйте попередній перегляд</b>Скористайтеся <span class='knopfwort'>Показати попередній перегляд</span>, щоб перевірити вигляд і звук.</div>",
    "zh-cn": "<p>只要 Magnolie Organizer 正在运行或仍在 Windows 通知区域中打开，Organizer 就可以提醒您约会和到期任务。</p><ol class='schritte'><li>打开 <span class='knopfwort'>设置 ▸ 通知</span>。</li><li>启用提醒。</li><li>选择所需的提前时间。</li><li>关闭设置页面。</li></ol><p>如果将窗口最小化或关闭到通知区域，提醒会继续工作。如果完全退出应用程序，则在下次启动前不会生成提醒。</p><h3>错过的约会</h3><p>如果启用了相应选项，下次启动时 Organizer 可以报告错过的约会。</p><div class='merke'><b>尝试预览</b>使用 <span class='knopfwort'>显示预览</span> 测试显示和声音。</div>"
  },
  "appearance-sound-and-anniversaries": {
    "en": "<h3>Display and sound</h3><p>Windows notifications appear in the notification area. Magnolie's chime can also be played. The Windows settings under <i>System ▸ Notifications</i> also determine which notices may be visible or audible.</p><h3>Log only for troubleshooting</h3><p>Troubleshooting logging is off by default. Enable it only temporarily while reproducing a problem.</p><div class='achtung'><b>With password protection</b>Under <i>Settings ▸ Security</i>, check whether reminder data may be made available despite password protection. Confidential appointments require separate consent.</div>",
    "de": "<h3>Anzeige und Klang</h3><p>Windows-Benachrichtigungen erscheinen im Benachrichtigungsbereich. Zusätzlich kann der Magnolie-Klang abgespielt werden. Welche Hinweise sichtbar oder hörbar sind, bestimmen auch die Windows-Einstellungen unter <i>System ▸ Benachrichtigungen</i>.</p><h3>Nur zur Fehlersuche protokollieren</h3><p>Das Fehlerprotokoll ist voreingestellt aus. Schalten Sie es nur vorübergehend ein, während Sie ein Problem nachstellen.</p><div class='achtung'><b>Bei Kennwortschutz</b>Prüfen Sie unter <i>Einstellungen ▸ Sicherheit</i>, ob Erinnerungsdaten trotz Kennwortschutz bereitgestellt werden dürfen. Vertrauliche Termine benötigen eine zusätzliche Zustimmung.</div>",
    "ar": "<h3>العرض والصوت</h3><p>تظهر إشعارات Windows في منطقة الإعلام. ويمكن أيضا تشغيل نغمة Magnolie. وتحدد إعدادات Windows ضمن <i>النظام ▸ الإشعارات</i> كذلك الإشعارات التي يمكن رؤيتها أو سماعها.</p><h3>التسجيل لاستكشاف الأخطاء فقط</h3><p>يكون تسجيل استكشاف الأخطاء معطلا افتراضيا. فعّله مؤقتا فقط أثناء إعادة إحداث مشكلة.</p><div class='achtung'><b>مع الحماية بكلمة مرور</b>تحقق ضمن <i>الإعدادات ▸ الأمان</i> مما إذا كان يجوز إتاحة بيانات التذكير رغم الحماية بكلمة مرور. تتطلب المواعيد السرية موافقة منفصلة.</div>",
    "be": "<h3>Выгляд і гук</h3><p>Апавяшчэнні Windows з’яўляюцца ў вобласці апавяшчэнняў. Таксама можа прайгравацца сігнал Magnolie. Налады Windows у <i>Сістэма ▸ Апавяшчэнні</i> таксама вызначаюць, якія паведамленні будуць бачныя або чутныя.</p><h3>Журнал толькі для пошуку непаладак</h3><p>Журнал пошуку непаладак прадвызначана выключаны. Уключайце яго толькі часова падчас паўтарэння праблемы.</p><div class='achtung'><b>Пры абароне паролем</b>У <i>Налады ▸ Бяспека</i> праверце, ці можна рабіць даныя напамінаў даступнымі нягледзячы на абарону паролем. Канфідэнцыйныя сустрэчы патрабуюць асобнай згоды.</div>",
    "cs": "<h3>Zobrazení a zvuk</h3><p>Oznámení Windows se zobrazují v oznamovací oblasti. Lze přehrát také zvuk Magnolie. O tom, která oznámení mohou být viditelná nebo slyšitelná, rozhodují i nastavení Windows v části <i>Systém ▸ Oznámení</i>.</p><h3>Protokol jen pro řešení potíží</h3><p>Protokolování řešení potíží je ve výchozím nastavení vypnuto. Zapínejte je jen dočasně při opakování problému.</p><div class='achtung'><b>Při ochraně heslem</b>V části <i>Nastavení ▸ Zabezpečení</i> zkontrolujte, zda mohou být data připomínek zpřístupněna navzdory ochraně heslem. Důvěrné schůzky vyžadují samostatný souhlas.</div>",
    "da": "<h3>Visning og lyd</h3><p>Windows-meddelelser vises i meddelelsesområdet. Magnolie-klangen kan også afspilles. Windows-indstillingerne under <i>System ▸ Meddelelser</i> er også med til at bestemme, hvilke beskeder der må ses eller høres.</p><h3>Log kun til fejlsøgning</h3><p>Fejlsøgningsloggen er slået fra som standard. Slå den kun til midlertidigt, mens du genskaber et problem.</p><div class='achtung'><b>Ved adgangskodebeskyttelse</b>Kontrollér under <i>Indstillinger ▸ Sikkerhed</i>, om påmindelsesdata må stilles til rådighed trods adgangskodebeskyttelsen. Fortrolige aftaler kræver særskilt samtykke.</div>",
    "es": "<h3>Presentación y sonido</h3><p>Las notificaciones de Windows aparecen en el área de notificación. También puede reproducirse el sonido de Magnolie. Los ajustes de Windows en <i>Sistema ▸ Notificaciones</i> determinan asimismo qué avisos pueden verse u oírse.</p><h3>Registro solo para diagnóstico</h3><p>El registro de diagnóstico está desactivado de forma predeterminada. Actívelo solo de forma temporal mientras reproduce un problema.</p><div class='achtung'><b>Cuando hay una contraseña establecida</b>En <i>Ajustes ▸ Seguridad</i>, compruebe si los datos de los recordatorios pueden facilitarse pese a la protección por contraseña. Las citas confidenciales requieren un consentimiento aparte.</div>",
    "fr": "<h3>Affichage et son</h3><p>Les notifications Windows apparaissent dans la zone de notification. Le carillon de Magnolie peut également être joué. Les paramètres Windows sous <i>Système ▸ Notifications</i> déterminent eux aussi quels avis peuvent être visibles ou audibles.</p><h3>Journaliser uniquement pour le dépannage</h3><p>La journalisation de dépannage est désactivée par défaut. Ne l’activez que temporairement, le temps de reproduire un problème.</p><div class='achtung'><b>Avec la protection par mot de passe</b>Sous <i>Paramètres ▸ Sécurité</i>, vérifiez si les données de rappel peuvent être mises à disposition malgré la protection par mot de passe. Les rendez-vous confidentiels nécessitent un consentement distinct.</div>",
    "hi": "<h3>डिस्प्ले और ध्वनि</h3><p>Windows सूचनाएँ सूचना क्षेत्र में दिखाई देती हैं। Magnolie की घंटी भी बजाई जा सकती है। <i>सिस्टम ▸ सूचनाएँ</i> के अंतर्गत Windows सेटिंग्स भी तय करती हैं कि कौन-सी सूचनाएँ दिखाई या सुनाई दे सकती हैं।</p><h3>लॉग केवल समस्या निवारण के लिए</h3><p>समस्या निवारण लॉगिंग डिफ़ॉल्ट रूप से बंद है। किसी समस्या को दोहराते समय ही इसे अस्थायी रूप से चालू करें।</p><div class='achtung'><b>पासवर्ड सुरक्षा के साथ</b><i>सेटिंग्स ▸ सुरक्षा</i> में जाँचें कि पासवर्ड सुरक्षा के बावजूद रिमाइंडर डेटा उपलब्ध कराया जा सकता है या नहीं। गोपनीय अपॉइंटमेंट के लिए अलग सहमति आवश्यक है।</div>",
    "hsb": "<h3>Pokazanje a zynk</h3><p>Zdźělenki Windows so we wobłuku zdźělenkow zjewja. Tež zynk Magnolie hodźi so wothrać. Nastajenja Windows pod <i>System ▸ Zdźělenki</i> tež postajeja, kotre pokiwy smědźa widźomne abo słyšomne być.</p><h3>Protokol jenož za pytanje zmylkow</h3><p>Protokolowanje za pytanje zmylkow je standardnje znjemóžnjene. Zmóžńće jo jenož nachwilu, mjeztym zo problem wospjetujeće.</p><div class='achtung'><b>Při hesłowym škiće</b>Přepruwujće pod <i>Nastajenja ▸ Wěstota</i>, hač smědźa dopominanske daty najebać hesłoweho škita k dispoziciji być. Dowěrliwe terminy trjebaja separatne přizwolenje.</div>",
    "it": "<h3>Visualizzazione e suono</h3><p>Le notifiche di Windows compaiono nell'area di notifica. Può essere riprodotto anche il suono di Magnolie. Anche le impostazioni di Windows in <i>Sistema ▸ Notifiche</i> determinano quali avvisi possono essere visibili o udibili.</p><h3>Registro solo per la diagnostica</h3><p>Il registro diagnostico è disattivato per impostazione predefinita. Attivatelo solo temporaneamente, mentre riproducete un problema.</p><div class='achtung'><b>Con protezione con password</b>In <i>Impostazioni ▸ Sicurezza</i> verificate se i dati dei promemoria possono essere resi disponibili nonostante la protezione con password. Gli appuntamenti riservati richiedono un consenso separato.</div>",
    "ja": "<h3>表示と音</h3><p>Windows の通知は通知領域に表示されます。Magnolie のチャイムも鳴らせます。<i>システム ▸ 通知</i> にある Windows の設定も、どの通知を表示または再生できるかを決めます。</p><h3>トラブルシューティング時だけ記録する</h3><p>トラブルシューティングログは既定で無効です。問題を再現するときだけ一時的に有効にしてください。</p><div class='achtung'><b>パスワード保護を使用している場合</b><i>設定 ▸ セキュリティ</i> で、パスワード保護中でもリマインダーデータを利用可能にするか確認します。機密の予定には別途同意が必要です。</div>",
    "nb": "<h3>Visning og lyd</h3><p>Windows-varsler vises i systemstatusfeltet. Magnolie-klangen kan også spilles av. Windows-innstillingene under <i>System ▸ Varsler</i> avgjør også hvilke meldinger som kan være synlige eller hørbare.</p><h3>Logging bare for feilsøking</h3><p>Feilsøkingslogging er slått av som standard. Slå den bare på midlertidig mens du gjenskaper et problem.</p><div class='achtung'><b>Med passordbeskyttelse</b>Kontroller under <i>Innstillinger ▸ Sikkerhet</i> om påminnelsesdata kan gjøres tilgjengelige til tross for passordbeskyttelsen. Fortrolige avtaler krever separat samtykke.</div>",
    "nl": "<h3>Weergave en geluid</h3><p>Windows-meldingen verschijnen in het systeemvak. Ook de Magnolie-klank kan worden afgespeeld. De Windows-instellingen onder <i>Systeem ▸ Meldingen</i> bepalen mede welke meldingen zichtbaar of hoorbaar mogen zijn.</p><h3>Alleen loggen voor foutopsporing</h3><p>Het foutopsporingslogboek staat standaard uit. Schakel het alleen tijdelijk in terwijl u een probleem nabootst.</p><div class='achtung'><b>Bij wachtwoordbeveiliging</b>Controleer onder <i>Instellingen ▸ Beveiliging</i> of herinneringsgegevens ondanks de wachtwoordbeveiliging beschikbaar mogen worden gesteld. Vertrouwelijke afspraken vereisen aparte toestemming.</div>",
    "pl": "<h3>Wygląd i dźwięk</h3><p>Powiadomienia Windows pojawiają się w obszarze powiadomień. Może też być odtwarzany sygnał Magnolie. Ustawienia Windows w <i>System ▸ Powiadomienia</i> również określają, które komunikaty mogą być widoczne lub słyszalne.</p><h3>Dziennik tylko do rozwiązywania problemów</h3><p>Rejestrowanie diagnostyczne jest domyślnie wyłączone. Włączaj je tylko tymczasowo podczas odtwarzania problemu.</p><div class='achtung'><b>Przy ochronie hasłem</b>W <i>Ustawienia ▸ Bezpieczeństwo</i> sprawdź, czy dane przypomnień mogą być udostępniane pomimo ochrony hasłem. Poufne spotkania wymagają osobnej zgody.</div>",
    "pt": "<h3>Apresentação e som</h3><p>As notificações do Windows aparecem na área de notificação. Também pode ser reproduzido o som do Magnolie. As definições do Windows em <i>Sistema ▸ Notificações</i> determinam igualmente que avisos podem ser vistos ou ouvidos.</p><h3>Registo apenas para diagnóstico</h3><p>O registo de diagnóstico está desativado por predefinição. Ative-o apenas temporariamente, enquanto reproduz um problema.</p><div class='achtung'><b>Com proteção por palavra-passe</b>Em <i>Definições ▸ Segurança</i>, verifique se os dados dos lembretes podem ser disponibilizados apesar da proteção por palavra-passe. Os compromissos confidenciais exigem um consentimento à parte.</div>",
    "ru": "<h3>Отображение и звук</h3><p>Уведомления Windows появляются в области уведомлений. Также может воспроизводиться сигнал Magnolie. Настройки Windows в <i>Система ▸ Уведомления</i> также определяют, какие сообщения могут быть видны или слышны.</p><h3>Журнал только для устранения неполадок</h3><p>Диагностическое журналирование по умолчанию выключено. Включайте его только временно при воспроизведении проблемы.</p><div class='achtung'><b>При защите паролем</b>В <i>Настройки ▸ Безопасность</i> проверьте, можно ли предоставлять данные напоминаний несмотря на защиту паролем. Для конфиденциальных встреч требуется отдельное согласие.</div>",
    "tr": "<h3>Görüntü ve ses</h3><p>Windows bildirimleri bildirim alanında görünür. Magnolie zil sesi de çalınabilir. <i>Sistem ▸ Bildirimler</i> altındaki Windows ayarları da hangi bildirimlerin görünür veya duyulur olacağını belirler.</p><h3>Yalnızca sorun giderme için günlük</h3><p>Sorun giderme günlüğü varsayılan olarak kapalıdır. Yalnızca bir sorunu yeniden oluştururken geçici olarak etkinleştirin.</p><div class='achtung'><b>Parola korumasıyla</b><i>Ayarlar ▸ Güvenlik</i> bölümünde, parola korumasına rağmen hatırlatıcı verilerinin kullanılabilir olup olmayacağını denetleyin. Gizli randevular için ayrıca onay gerekir.</div>",
    "uk": "<h3>Вигляд і звук</h3><p>Сповіщення Windows з’являються в області сповіщень. Також може відтворюватися сигнал Magnolie. Налаштування Windows у <i>Система ▸ Сповіщення</i> теж визначають, які повідомлення можуть бути видимими або чутними.</p><h3>Журнал лише для усунення несправностей</h3><p>Діагностичне журналювання типово вимкнено. Вмикайте його лише тимчасово під час відтворення проблеми.</p><div class='achtung'><b>За захисту паролем</b>У <i>Налаштування ▸ Безпека</i> перевірте, чи можна надавати дані нагадувань попри захист паролем. Конфіденційні зустрічі потребують окремої згоди.</div>",
    "zh-cn": "<h3>显示和声音</h3><p>Windows 通知会出现在通知区域中，也可以播放 Magnolie 提示音。Windows 的<i>系统 ▸ 通知</i>设置也会决定哪些通知可以显示或发声。</p><h3>仅为故障排除记录日志</h3><p>故障排除日志默认关闭。仅在重现问题时临时启用。</p><div class='achtung'><b>使用密码保护时</b>请在<i>设置 ▸ 安全</i>中检查是否允许在有密码保护的情况下提供提醒数据。机密约会需要单独同意。</div>"
  },
  "importing-data-from-other-programs": {
    "en": "<p>Under <span class='knopfwort'>Settings ▸ Import</span>, import files from other programs.</p><h3>Complete Magnolie archive (.magnolie)</h3><p>A complete archive transfers all application data between Windows and Linux: appointments, tasks, contacts with photos, notes with images and PDF attachments, anniversaries, planner, health, and recycle bin. The archive is checked before replacement and the old data are backed up automatically. An optional archive password protects the file across platforms.</p><h3>Individual formats</h3><p>ICS imports calendars and tasks; VCF imports contacts and photos; Claws XML and LDIF import address books; and the dedicated Lotus Organizer CSV importer handles classic Lotus files.</p><div class='merke'><b>For moving computers</b>Use the complete Magnolie archive when everything must be transferred. ICS, VCF, LDIF, and CSV exchange individual areas.</div>",
    "de": "<p>Unter <span class='knopfwort'>Einstellungen ▸ Import</span> übernehmen Sie Dateien anderer Programme.</p><h3>Magnolie-Gesamtarchiv (.magnolie)</h3><p>Ein Gesamtarchiv überträgt den vollständigen Datenbestand zwischen Windows und Linux: Termine, Aufgaben, Adressen mit Kontaktfotos, Notizen mit Bildern und PDF-Anhängen, Jahrestage, Planer, Gesundheit und Papierkorb. Das Archiv wird vor dem Ersetzen geprüft; der bisherige Bestand wird automatisch gesichert. Ein optionales Archivkennwort schützt die Datei plattformübergreifend.</p><h3>Einzelformate</h3><p>ICS importiert Kalender und Aufgaben, VCF Adressen und Fotos, Claws-XML und LDIF Adressbücher. Für klassische Lotus-Dateien steht ein eigener Lotus-Organizer-CSV-Import bereit.</p><div class='merke'><b>Für den Rechnerwechsel</b>Verwenden Sie das Magnolie-Gesamtarchiv, wenn wirklich alles mitgenommen werden soll. ICS, VCF, LDIF und CSV tauschen einzelne Bereiche aus.</div>",
    "ar": "<p>من <span class='knopfwort'>الإعدادات ▸ الاستيراد</span>، استورد ملفات من برامج أخرى.</p><h3>أرشيف Magnolie الكامل (.magnolie)</h3><p>ينقل الأرشيف الكامل جميع بيانات التطبيق بين Windows وLinux: المواعيد والمهام وجهات الاتصال مع الصور والملاحظات مع الصور ومرفقات PDF والمناسبات السنوية والمخطط والصحة وسلة المحذوفات. يُفحص الأرشيف قبل الاستبدال وتُنسخ البيانات القديمة احتياطيا تلقائيا. وتحمي كلمة مرور اختيارية للأرشيف الملف عبر الأنظمة الأساسية.</p><h3>التنسيقات الفردية</h3><p>يستورد ICS التقويمات والمهام؛ ويستورد VCF جهات الاتصال والصور؛ ويستورد Claws XML وLDIF دفاتر العناوين؛ ويتعامل مستورد Lotus Organizer CSV المخصص مع ملفات Lotus التقليدية.</p><div class='merke'><b>عند الانتقال إلى حاسوب آخر</b>استخدم أرشيف Magnolie الكامل عندما يجب نقل كل شيء. ويتبادل ICS وVCF وLDIF وCSV أقساما منفردة.</div>",
    "be": "<p>Праз <span class='knopfwort'>Налады ▸ Імпарт</span> імпартуйце файлы з іншых праграм.</p><h3>Поўны архіў Magnolie (.magnolie)</h3><p>Поўны архіў пераносіць усе даныя праграмы паміж Windows і Linux: сустрэчы, заданні, кантакты з фотаздымкамі, нататкі з выявамі і PDF-далучэннямі, памятныя даты, планавальнік, здароўе і сметніцу. Архіў правяраецца перад заменай, а старыя даныя аўтаматычна рэзервуюцца. Неабавязковы пароль архіва абараняе файл на абедзвюх платформах.</p><h3>Асобныя фарматы</h3><p>ICS імпартуе календары і заданні; VCF імпартуе кантакты і фотаздымкі; Claws XML і LDIF імпартуюць адрасныя кнігі; асобны імпарцёр Lotus Organizer CSV апрацоўвае класічныя файлы Lotus.</p><div class='merke'><b>Для пераезду на іншы камп’ютар</b>Выкарыстоўвайце поўны архіў Magnolie, калі трэба перанесці ўсё. ICS, VCF, LDIF і CSV прызначаны для абмену данымі асобных раздзелаў.</div>",
    "cs": "<p>V části <span class='knopfwort'>Nastavení ▸ Importovat</span> importujte soubory z jiných programů.</p><h3>Úplný archiv Magnolie (.magnolie)</h3><p>Úplný archiv přenáší všechna data aplikace mezi Windows a Linuxem: schůzky, úkoly, kontakty s fotografiemi, poznámky s obrázky a přílohami PDF, výročí, plánovač, zdraví a koš. Archiv se před nahrazením zkontroluje a stará data se automaticky zazálohují. Volitelné heslo archivu chrání soubor na obou platformách.</p><h3>Jednotlivé formáty</h3><p>ICS importuje kalendáře a úkoly; VCF kontakty a fotografie; Claws XML a LDIF adresáře; vyhrazený importér Lotus Organizer CSV zpracovává klasické soubory Lotus.</p><div class='merke'><b>Při změně počítače</b>Potřebujete-li přenést vše, použijte úplný archiv Magnolie. ICS, VCF, LDIF a CSV vyměňují jednotlivé oblasti.</div>",
    "da": "<p>Under <span class='knopfwort'>Indstillinger ▸ Importér</span> importerer du filer fra andre programmer.</p><h3>Komplet Magnolie-arkiv (.magnolie)</h3><p>Et komplet arkiv overfører alle programdata mellem Windows og Linux: aftaler, opgaver, kontakter med billeder, noter med billeder og PDF-vedhæftninger, mærkedage, planlægger, sundhed og papirkurv. Arkivet kontrolleres, før noget erstattes, og de gamle data sikres automatisk. En valgfri arkivadgangskode beskytter filen på tværs af platforme.</p><h3>Enkelte formater</h3><p>ICS importerer kalendere og opgaver; VCF importerer kontakter og billeder; Claws XML og LDIF importerer adressebøger; og den særlige CSV-import til Lotus Organizer klarer klassiske Lotus-filer.</p><div class='merke'><b>Ved skift af computer</b>Brug det komplette Magnolie-arkiv, når alt skal med. ICS, VCF, LDIF og CSV udveksler enkelte områder.</div>",
    "es": "<p>En <span class='knopfwort'>Ajustes ▸ Importar</span> puede importar archivos de otros programas.</p><h3>Archivo completo de Magnolie (.magnolie)</h3><p>Un archivo completo traslada todos los datos de la aplicación entre Windows y Linux: citas, tareas, contactos con fotos, notas con imágenes y adjuntos PDF, aniversarios, planificador, salud y papelera. El archivo se comprueba antes de sustituir nada y los datos antiguos se guardan automáticamente. Una contraseña de archivo opcional protege el fichero entre plataformas.</p><h3>Formatos sueltos</h3><p>ICS importa calendarios y tareas; VCF importa contactos y fotos; Claws XML y LDIF importan libretas de direcciones; y el importador CSV específico de Lotus Organizer se ocupa de los ficheros clásicos de Lotus.</p><div class='merke'><b>Para cambiar de ordenador</b>Utilice el archivo completo de Magnolie cuando deba trasladarse todo. ICS, VCF, LDIF y CSV intercambian áreas sueltas.</div>",
    "fr": "<p>Sous <span class='knopfwort'>Paramètres ▸ Importer</span>, importez des fichiers provenant d’autres programmes.</p><h3>Archive Magnolie complète (.magnolie)</h3><p>Une archive complète transfère toutes les données de l’application entre Windows et Linux : rendez-vous, tâches, contacts avec photos, notes avec images et pièces jointes PDF, dates anniversaires, planning, santé et corbeille. L’archive est vérifiée avant tout remplacement et les anciennes données sont sauvegardées automatiquement. Un mot de passe d’archive facultatif protège le fichier d’une plateforme à l’autre.</p><h3>Formats individuels</h3><p>ICS importe les calendriers et les tâches ; VCF importe les contacts et les photos ; Claws XML et LDIF importent les carnets d’adresses ; et l’importateur CSV dédié à Lotus Organizer prend en charge les fichiers Lotus classiques.</p><div class='merke'><b>Pour changer d’ordinateur</b>Utilisez l’archive Magnolie complète lorsque tout doit être transféré. ICS, VCF, LDIF et CSV échangent des domaines isolés.</div>",
    "hi": "<p><span class='knopfwort'>सेटिंग्स ▸ आयात करें</span> में दूसरे प्रोग्राम की फ़ाइलें आयात करें।</p><h3>संपूर्ण Magnolie संग्रह (.magnolie)</h3><p>संपूर्ण संग्रह Windows और Linux के बीच एप्लिकेशन का सारा डेटा स्थानांतरित करता है: अपॉइंटमेंट, कार्य, फ़ोटो सहित संपर्क, चित्र और PDF संलग्नक सहित नोट्स, वर्षगाँठ, योजनाकार, स्वास्थ्य और रीसायकल बिन। बदलने से पहले संग्रह की जाँच होती है और पुराने डेटा का बैकअप अपने-आप बनता है। वैकल्पिक संग्रह पासवर्ड सभी प्लेटफ़ॉर्म पर फ़ाइल की रक्षा करता है।</p><h3>अलग-अलग प्रारूप</h3><p>ICS कैलेंडर और कार्य आयात करता है; VCF संपर्क और फ़ोटो आयात करता है; Claws XML और LDIF पता पुस्तिकाएँ आयात करते हैं; और समर्पित Lotus Organizer CSV आयातक पुरानी Lotus फ़ाइलें संभालता है।</p><div class='merke'><b>कंप्यूटर बदलने के लिए</b>जब सब कुछ स्थानांतरित करना हो, तब संपूर्ण Magnolie संग्रह उपयोग करें। ICS, VCF, LDIF और CSV अलग-अलग क्षेत्रों का आदान-प्रदान करते हैं।</div>",
    "hsb": "<p>Pod <span class='knopfwort'>Nastajenja ▸ Importować</span> importujće dataje z druhich programow.</p><h3>Dospołny archiw Magnolie (.magnolie)</h3><p>Dospołny archiw přenjesuje wšitke nałoženske daty mjez Windows a Linuxom: terminy, nadawki, kontakty z fotami, noticy z wobrazami a PDF-přiwěškami, róčnicy, planowak, strowotu a papjerowy koš. Archiw so před narunanjom přepruwuje a stare daty so awtomatisce zawěsćeja. Opcionalne archiwowe hesło škita dataju na woběmaj platformomaj.</p><h3>Jednotliwe formaty</h3><p>ICS importuje protyki a nadawki; VCF kontakty a fota; Claws XML a LDIF adresniki; wosebity importowak Lotus Organizer CSV wobdźěła klasiske dataje Lotus.</p><div class='merke'><b>Za změnu ličaka</b>Wužiwajće dospołny archiw Magnolie, hdyž dyrbi so wšitko přenjesć. ICS, VCF, LDIF a CSV wuměnjeja jednotliwe wobłuki.</div>",
    "it": "<p>In <span class='knopfwort'>Impostazioni ▸ Importa</span> potete importare file di altri programmi.</p><h3>Archivio Magnolie completo (.magnolie)</h3><p>Un archivio completo trasferisce tutti i dati dell'applicazione tra Windows e Linux: appuntamenti, attività, contatti con foto, note con immagini e allegati PDF, ricorrenze, pianificatore, salute e cestino. L'archivio viene verificato prima di sostituire qualcosa e i dati precedenti vengono salvati automaticamente. Una password d'archivio facoltativa protegge il file da una piattaforma all'altra.</p><h3>Formati singoli</h3><p>ICS importa calendari e attività; VCF importa contatti e foto; Claws XML e LDIF importano rubriche; e l'importatore CSV dedicato a Lotus Organizer gestisce i file Lotus classici.</p><div class='merke'><b>Per cambiare computer</b>Usate l'archivio Magnolie completo quando va trasferito tutto. ICS, VCF, LDIF e CSV scambiano singole aree.</div>",
    "ja": "<p><span class='knopfwort'>設定 ▸ インポート</span> で、他のプログラムからファイルをインポートします。</p><h3>完全な Magnolie アーカイブ (.magnolie)</h3><p>完全なアーカイブは、予定、タスク、写真付き連絡先、画像や PDF 添付ファイル付きメモ、記念日、プランナー、健康管理、ごみ箱など、すべてのアプリケーションデータを Windows と Linux の間で転送します。置き換える前にアーカイブが検査され、古いデータは自動的にバックアップされます。任意のアーカイブパスワードで、プラットフォームをまたいでファイルを保護できます。</p><h3>個別の形式</h3><p>ICS はカレンダーとタスク、VCF は連絡先と写真、Claws XML と LDIF はアドレス帳をインポートします。専用の Lotus Organizer CSV インポーターは従来の Lotus ファイルを処理します。</p><div class='merke'><b>コンピューターを移行する場合</b>すべてを転送する必要がある場合は、完全な Magnolie アーカイブを使用します。ICS、VCF、LDIF、CSV は個別の領域を交換します。</div>",
    "nb": "<p>Under <span class='knopfwort'>Innstillinger ▸ Importer</span> importerer du filer fra andre programmer.</p><h3>Komplett Magnolie-arkiv (.magnolie)</h3><p>Et komplett arkiv overfører alle programdata mellom Windows og Linux: avtaler, oppgaver, kontakter med bilder, notater med bilder og PDF-vedlegg, merkedager, planlegger, helse og papirkurv. Arkivet kontrolleres før erstatning, og gamle data sikkerhetskopieres automatisk. Et valgfritt arkivpassord beskytter filen på tvers av plattformer.</p><h3>Enkeltformater</h3><p>ICS importerer kalendere og oppgaver; VCF importerer kontakter og bilder; Claws XML og LDIF importerer adressebøker; den egne Lotus Organizer CSV-importen håndterer klassiske Lotus-filer.</p><div class='merke'><b>Ved bytte av datamaskin</b>Bruk det komplette Magnolie-arkivet når alt må overføres. ICS, VCF, LDIF og CSV utveksler enkeltområder.</div>",
    "nl": "<p>Onder <span class='knopfwort'>Instellingen ▸ Importeren</span> importeert u bestanden uit andere programma's.</p><h3>Volledig Magnolie-archief (.magnolie)</h3><p>Een volledig archief brengt alle toepassingsgegevens over tussen Windows en Linux: afspraken, taken, contacten met foto's, notities met afbeeldingen en PDF-bijlagen, jaardagen, planner, gezondheid en prullenbak. Het archief wordt gecontroleerd voordat er iets wordt vervangen, en de oude gegevens worden automatisch veiliggesteld. Een optioneel archiefwachtwoord beschermt het bestand over platformen heen.</p><h3>Losse indelingen</h3><p>ICS importeert agenda's en taken; VCF importeert contacten en foto's; Claws XML en LDIF importeren adresboeken; en de speciale CSV-import voor Lotus Organizer verwerkt klassieke Lotus-bestanden.</p><div class='merke'><b>Bij verhuizen naar een andere computer</b>Gebruik het volledige Magnolie-archief wanneer alles mee moet. ICS, VCF, LDIF en CSV wisselen losse gebieden uit.</div>",
    "pl": "<p>W <span class='knopfwort'>Ustawienia ▸ Importuj</span> importuj pliki z innych programów.</p><h3>Kompletne archiwum Magnolie (.magnolie)</h3><p>Kompletne archiwum przenosi wszystkie dane aplikacji między Windows i Linuxem: spotkania, zadania, kontakty ze zdjęciami, notatki z obrazami i załącznikami PDF, rocznice, planer, zdrowie oraz kosz. Archiwum jest sprawdzane przed zastąpieniem, a stare dane są automatycznie archiwizowane. Opcjonalne hasło archiwum chroni plik na obu platformach.</p><h3>Poszczególne formaty</h3><p>ICS importuje kalendarze i zadania; VCF kontakty i zdjęcia; Claws XML i LDIF książki adresowe; specjalny importer Lotus Organizer CSV obsługuje klasyczne pliki Lotus.</p><div class='merke'><b>Przy zmianie komputera</b>Użyj kompletnego archiwum Magnolie, gdy trzeba przenieść wszystko. ICS, VCF, LDIF i CSV wymieniają poszczególne obszary.</div>",
    "pt": "<p>Em <span class='knopfwort'>Definições ▸ Importar</span> pode importar ficheiros de outros programas.</p><h3>Arquivo Magnolie completo (.magnolie)</h3><p>Um arquivo completo transfere todos os dados da aplicação entre o Windows e o Linux: compromissos, tarefas, contactos com fotografias, notas com imagens e anexos PDF, datas comemorativas, planeador, saúde e lixo. O arquivo é verificado antes de substituir seja o que for e os dados anteriores são guardados automaticamente. Uma palavra-passe de arquivo opcional protege o ficheiro entre plataformas.</p><h3>Formatos avulsos</h3><p>O ICS importa calendários e tarefas; o VCF importa contactos e fotografias; o Claws XML e o LDIF importam livros de endereços; e o importador CSV dedicado ao Lotus Organizer trata dos ficheiros clássicos do Lotus.</p><div class='merke'><b>Para mudar de computador</b>Utilize o arquivo Magnolie completo quando tiver de transferir tudo. ICS, VCF, LDIF e CSV trocam áreas avulsas.</div>",
    "ru": "<p>В разделе <span class='knopfwort'>Настройки ▸ Импорт</span> импортируйте файлы из других программ.</p><h3>Полный архив Magnolie (.magnolie)</h3><p>Полный архив переносит все данные приложения между Windows и Linux: встречи, задачи, контакты с фотографиями, заметки с изображениями и вложениями PDF, памятные даты, планировщик, здоровье и корзину. Архив проверяется перед заменой, а прежние данные автоматически сохраняются в резервной копии. Необязательный пароль архива защищает файл на обеих платформах.</p><h3>Отдельные форматы</h3><p>ICS импортирует календари и задачи; VCF — контакты и фотографии; Claws XML и LDIF — адресные книги; специальный импортёр Lotus Organizer CSV обрабатывает классические файлы Lotus.</p><div class='merke'><b>При переходе на другой компьютер</b>Используйте полный архив Magnolie, если нужно перенести всё. ICS, VCF, LDIF и CSV служат для обмена данными отдельных разделов.</div>",
    "tr": "<p><span class='knopfwort'>Ayarlar ▸ İçe aktar</span> altında diğer programların dosyalarını içe aktarın.</p><h3>Tam Magnolie arşivi (.magnolie)</h3><p>Tam arşiv Windows ile Linux arasında tüm uygulama verilerini taşır: randevular, görevler, fotoğraflı kişiler, resim ve PDF ekli notlar, yıldönümleri, planlayıcı, sağlık ve geri dönüşüm kutusu. Arşiv değiştirme öncesinde denetlenir ve eski veriler otomatik olarak yedeklenir. İsteğe bağlı arşiv parolası dosyayı platformlar arasında korur.</p><h3>Tek tek biçimler</h3><p>ICS takvimleri ve görevleri; VCF kişileri ve fotoğrafları; Claws XML ve LDIF adres defterlerini içe aktarır. Özel Lotus Organizer CSV içe aktarıcısı klasik Lotus dosyalarını işler.</p><div class='merke'><b>Bilgisayar değiştirirken</b>Her şeyin taşınması gerekiyorsa tam Magnolie arşivini kullanın. ICS, VCF, LDIF ve CSV ayrı alanları aktarır.</div>",
    "uk": "<p>У <span class='knopfwort'>Налаштування ▸ Імпорт</span> імпортуйте файли з інших програм.</p><h3>Повний архів Magnolie (.magnolie)</h3><p>Повний архів переносить усі дані програми між Windows і Linux: зустрічі, завдання, контакти з фотографіями, нотатки із зображеннями й PDF-вкладеннями, річниці, планувальник, здоров’я та кошик. Архів перевіряється перед заміною, а старі дані автоматично резервуються. Необов’язковий пароль архіву захищає файл на обох платформах.</p><h3>Окремі формати</h3><p>ICS імпортує календарі й завдання; VCF — контакти й фотографії; Claws XML і LDIF — адресні книги; спеціальний імпортер Lotus Organizer CSV обробляє класичні файли Lotus.</p><div class='merke'><b>Для переходу на інший комп’ютер</b>Скористайтеся повним архівом Magnolie, коли треба перенести все. ICS, VCF, LDIF і CSV призначені для обміну даними окремих розділів.</div>",
    "zh-cn": "<p>在 <span class='knopfwort'>设置 ▸ 导入</span> 中导入其他程序的文件。</p><h3>完整的 Magnolie 存档 (.magnolie)</h3><p>完整存档会在 Windows 与 Linux 之间传输所有应用程序数据：约会、任务、带照片的联系人、带图像和 PDF 附件的笔记、纪念日、计划表、健康数据和回收站。替换数据前会检查存档，并自动备份旧数据。可选的存档密码可跨平台保护文件。</p><h3>单独格式</h3><p>ICS 导入日历和任务；VCF 导入联系人和照片；Claws XML 和 LDIF 导入通讯录；专用 Lotus Organizer CSV 导入器处理传统 Lotus 文件。</p><div class='merke'><b>更换电脑时</b>需要传输所有内容时，请使用完整的 Magnolie 存档。ICS、VCF、LDIF 和 CSV 用于交换单独的区域。</div>"
  },
  "moving-from-lotus-organizer": {
    "en": "<p>If you used Lotus Organizer on Windows, transfer its data with CSV files.</p><h3>In Lotus Organizer</h3><ol class='schritte'><li>Open the required section.</li><li>Select <i>File ▸ Export</i>.</li><li>Select a delimited ASCII or CSV file.</li><li>Save the file and repeat this for the other sections.</li></ol><h3>In Magnolie Organizer for Windows</h3><ol class='schritte'><li>Open <span class='knopfwort'>Settings ▸ Import</span>.</li><li>Click <span class='knopfwort'>Lotus Organizer CSV...</span>.</li><li>Select each file in the Windows file dialog.</li></ol><p>The Organizer recognizes the section from the column headings and understands different separators, character sets, and German, international, and US date formats.</p>",
    "de": "<p>Wenn Sie Lotus Organizer unter Windows verwendet haben, übernehmen Sie die Daten über CSV-Dateien.</p><h3>In Lotus Organizer</h3><ol class='schritte'><li>Öffnen Sie den gewünschten Bereich.</li><li>Wählen Sie <i>Datei ▸ Exportieren</i>.</li><li>Wählen Sie eine begrenzte ASCII- oder CSV-Datei.</li><li>Speichern Sie die Datei und wiederholen Sie dies für die anderen Bereiche.</li></ol><h3>In Magnolie Organizer für Windows</h3><ol class='schritte'><li>Öffnen Sie <span class='knopfwort'>Einstellungen ▸ Import</span>.</li><li>Klicken Sie auf <span class='knopfwort'>Lotus Organizer CSV...</span>.</li><li>Wählen Sie jede Datei im Windows-Dateidialog.</li></ol><p>Der Organizer erkennt den Bereich anhand der Spaltenüberschriften und versteht unterschiedliche Trennzeichen, Zeichensätze sowie deutsche, internationale und US-Datumsformate.</p>",
    "ar": "<p>إذا كنت تستخدم Lotus Organizer على Windows، فانقل بياناته باستخدام ملفات CSV.</p><h3>في Lotus Organizer</h3><ol class='schritte'><li>افتح القسم المطلوب.</li><li>حدد <i>ملف ▸ تصدير</i>.</li><li>حدد ملف ASCII محدد الفواصل أو ملف CSV.</li><li>احفظ الملف وكرر ذلك للأقسام الأخرى.</li></ol><h3>في Magnolie Organizer لنظام Windows</h3><ol class='schritte'><li>افتح <span class='knopfwort'>الإعدادات ▸ الاستيراد</span>.</li><li>انقر على <span class='knopfwort'>Lotus Organizer CSV …</span>.</li><li>حدد كل ملف في مربع حوار ملفات Windows.</li></ol><p>يتعرف Organizer على القسم من عناوين الأعمدة ويفهم الفواصل ومجموعات المحارف المختلفة وتنسيقات التاريخ الألمانية والدولية والأمريكية.</p>",
    "be": "<p>Калі вы карысталіся Lotus Organizer у Windows, перанясіце яго даныя праз файлы CSV.</p><h3>У Lotus Organizer</h3><ol class='schritte'><li>Адкрыйце патрэбны раздзел.</li><li>Выберыце <i>Файл ▸ Экспарт</i>.</li><li>Выберыце ASCII-файл з раздзяляльнікамі або файл CSV.</li><li>Захавайце файл і паўтарыце гэта для іншых раздзелаў.</li></ol><h3>У Magnolie Organizer для Windows</h3><ol class='schritte'><li>Адкрыйце <span class='knopfwort'>Налады ▸ Імпарт</span>.</li><li>Націсніце <span class='knopfwort'>Lotus Organizer CSV …</span>.</li><li>Выберыце кожны файл у дыялогу файлаў Windows.</li></ol><p>Organizer распазнае раздзел па загалоўках слупкоў і разумее розныя раздзяляльнікі, кадаванні, а таксама нямецкія, міжнародныя і амерыканскія фарматы даты.</p>",
    "cs": "<p>Pokud jste ve Windows používali Lotus Organizer, přeneste jeho data pomocí souborů CSV.</p><h3>V Lotus Organizer</h3><ol class='schritte'><li>Otevřete požadovanou část.</li><li>Vyberte <i>Soubor ▸ Exportovat</i>.</li><li>Vyberte oddělovaný soubor ASCII nebo CSV.</li><li>Soubor uložte a postup zopakujte pro ostatní části.</li></ol><h3>V Magnolie Organizer pro Windows</h3><ol class='schritte'><li>Otevřete <span class='knopfwort'>Nastavení ▸ Importovat</span>.</li><li>Klepněte na <span class='knopfwort'>Lotus Organizer CSV...</span>.</li><li>Vyberte jednotlivé soubory v dialogu souborů Windows.</li></ol><p>Organizer rozpozná část podle záhlaví sloupců a rozumí různým oddělovačům, znakovým sadám i německým, mezinárodním a americkým formátům data.</p>",
    "da": "<p>Har du brugt Lotus Organizer på Windows, overfører du dine data med CSV-filer.</p><h3>I Lotus Organizer</h3><ol class='schritte'><li>Åbn det ønskede afsnit.</li><li>Vælg <i>Filer ▸ Eksportér</i>.</li><li>Vælg en afgrænset ASCII- eller CSV-fil.</li><li>Gem filen, og gentag dette for de øvrige afsnit.</li></ol><h3>I Magnolie Organizer til Windows</h3><ol class='schritte'><li>Åbn <span class='knopfwort'>Indstillinger ▸ Importér</span>.</li><li>Klik på <span class='knopfwort'>Lotus Organizer CSV …</span>.</li><li>Vælg hver fil i Windows' fildialog.</li></ol><p>Organizeren genkender afsnittet ud fra kolonneoverskrifterne og forstår forskellige skilletegn, forskellige tegnsæt og tyske, internationale og amerikanske datoformater.</p>",
    "es": "<p>Si utilizó Lotus Organizer en Windows, traslade sus datos mediante archivos CSV.</p><h3>En Lotus Organizer</h3><ol class='schritte'><li>Abra la sección que desee.</li><li>Seleccione <i>Archivo ▸ Exportar</i>.</li><li>Elija un archivo ASCII delimitado o CSV.</li><li>Guarde el archivo y repita la operación con las demás secciones.</li></ol><h3>En Magnolie Organizer para Windows</h3><ol class='schritte'><li>Abra <span class='knopfwort'>Ajustes ▸ Importar</span>.</li><li>Haga clic en <span class='knopfwort'>Lotus Organizer CSV …</span>.</li><li>Elija cada archivo en el diálogo de archivos de Windows.</li></ol><p>El Organizador reconoce la sección por los encabezados de columna y entiende distintos separadores, distintos juegos de caracteres y los formatos de fecha alemán, internacional y estadounidense.</p>",
    "fr": "<p>Si vous avez utilisé Lotus Organizer sous Windows, transférez ses données à l’aide de fichiers CSV.</p><h3>Dans Lotus Organizer</h3><ol class='schritte'><li>Ouvrez la section voulue.</li><li>Sélectionnez <i>Fichier ▸ Exporter</i>.</li><li>Choisissez un fichier ASCII délimité ou CSV.</li><li>Enregistrez le fichier, puis répétez l’opération pour les autres sections.</li></ol><h3>Dans Magnolie Organizer pour Windows</h3><ol class='schritte'><li>Ouvrez <span class='knopfwort'>Paramètres ▸ Importer</span>.</li><li>Cliquez sur <span class='knopfwort'>Lotus Organizer CSV …</span>.</li><li>Sélectionnez chaque fichier dans la boîte de dialogue de fichiers de Windows.</li></ol><p>L’Organizer identifie la section à partir des en-têtes de colonnes et comprend différents séparateurs, différents jeux de caractères ainsi que les formats de date allemand, international et américain.</p>",
    "hi": "<p>यदि आपने Windows पर Lotus Organizer उपयोग किया है, तो उसका डेटा CSV फ़ाइलों से स्थानांतरित करें।</p><h3>Lotus Organizer में</h3><ol class='schritte'><li>आवश्यक अनुभाग खोलें।</li><li><i>फ़ाइल ▸ निर्यात</i> चुनें।</li><li>सीमांकित ASCII या CSV फ़ाइल चुनें।</li><li>फ़ाइल सहेजें और अन्य अनुभागों के लिए इसे दोहराएँ।</li></ol><h3>Windows के लिए Magnolie Organizer में</h3><ol class='schritte'><li><span class='knopfwort'>सेटिंग्स ▸ आयात करें</span> खोलें।</li><li><span class='knopfwort'>Lotus Organizer CSV …</span> पर क्लिक करें।</li><li>Windows फ़ाइल संवाद में हर फ़ाइल चुनें।</li></ol><p>Organizer कॉलम शीर्षकों से अनुभाग पहचानता है और अलग-अलग विभाजक, वर्ण सेट तथा जर्मन, अंतरराष्ट्रीय और अमेरिकी तारीख प्रारूप समझता है।</p>",
    "hsb": "<p>Jeli sće Lotus Organizer pod Windows wužiwali, přenjesće jeho daty z CSV-datajemi.</p><h3>W Lotus Organizer</h3><ol class='schritte'><li>Wočińće trěbny wobłuk.</li><li>Wubjerće <i>Dataja ▸ Eksportować</i>.</li><li>Wubjerće dźěleny ASCII- abo CSV-dataj.</li><li>Składujće dataju a wospjetujće to za druhe wobłuki.</li></ol><h3>W Magnolie Organizer za Windows</h3><ol class='schritte'><li>Wočińće <span class='knopfwort'>Nastajenja ▸ Importować</span>.</li><li>Klikńće na <span class='knopfwort'>Lotus Organizer CSV...</span>.</li><li>Wubjerće kóždy dataj w datajowym dialogu Windows.</li></ol><p>Organizer spóznaje wobłuk po nadpismach stołpikow a rozumi rozdźělne dźělenske znamješka, znamješkowe sadźby kaž tež němske, mjezynarodne a US-datumowe formaty.</p>",
    "it": "<p>Se avete usato Lotus Organizer su Windows, trasferite i suoi dati con file CSV.</p><h3>In Lotus Organizer</h3><ol class='schritte'><li>Aprite la sezione desiderata.</li><li>Selezionate <i>File ▸ Esporta</i>.</li><li>Scegliete un file ASCII delimitato o CSV.</li><li>Salvate il file e ripetete l'operazione per le altre sezioni.</li></ol><h3>In Magnolie Organizer per Windows</h3><ol class='schritte'><li>Aprite <span class='knopfwort'>Impostazioni ▸ Importa</span>.</li><li>Fate clic su <span class='knopfwort'>Lotus Organizer CSV …</span>.</li><li>Scegliete ogni file nella finestra di dialogo dei file di Windows.</li></ol><p>L'Organizer riconosce la sezione dalle intestazioni di colonna e comprende separatori diversi, set di caratteri diversi e i formati di data tedesco, internazionale e statunitense.</p>",
    "ja": "<p>Windows で Lotus Organizer を使用していた場合は、CSV ファイルでデータを移行します。</p><h3>Lotus Organizer で</h3><ol class='schritte'><li>必要なセクションを開きます。</li><li><i>ファイル ▸ エクスポート</i> を選びます。</li><li>区切り文字付き ASCII または CSV ファイルを選びます。</li><li>ファイルを保存し、他のセクションでも繰り返します。</li></ol><h3>Windows 版 Magnolie Organizer で</h3><ol class='schritte'><li><span class='knopfwort'>設定 ▸ インポート</span> を開きます。</li><li><span class='knopfwort'>Lotus Organizer CSV …</span> をクリックします。</li><li>Windows のファイルダイアログで各ファイルを選びます。</li></ol><p>Organizer は列見出しからセクションを識別し、さまざまな区切り文字、文字セット、ドイツ式、国際式、米国式の日付形式を解釈します。</p>",
    "nb": "<p>Hvis du brukte Lotus Organizer på Windows, kan du overføre dataene med CSV-filer.</p><h3>I Lotus Organizer</h3><ol class='schritte'><li>Åpne ønsket del.</li><li>Velg <i>Fil ▸ Eksporter</i>.</li><li>Velg en avgrenset ASCII- eller CSV-fil.</li><li>Lagre filen, og gjenta dette for de andre delene.</li></ol><h3>I Magnolie Organizer for Windows</h3><ol class='schritte'><li>Åpne <span class='knopfwort'>Innstillinger ▸ Importer</span>.</li><li>Klikk på <span class='knopfwort'>Lotus Organizer CSV...</span>.</li><li>Velg hver fil i Windows-fildialogen.</li></ol><p>Organizeren gjenkjenner delen fra kolonneoverskriftene og forstår ulike skilletegn, tegnsett og tyske, internasjonale og amerikanske datoformater.</p>",
    "nl": "<p>Gebruikte u Lotus Organizer op Windows, breng de gegevens dan over met CSV-bestanden.</p><h3>In Lotus Organizer</h3><ol class='schritte'><li>Open het gewenste onderdeel.</li><li>Kies <i>Bestand ▸ Exporteren</i>.</li><li>Kies een gescheiden ASCII- of CSV-bestand.</li><li>Sla het bestand op en herhaal dit voor de overige onderdelen.</li></ol><h3>In Magnolie Organizer voor Windows</h3><ol class='schritte'><li>Open <span class='knopfwort'>Instellingen ▸ Importeren</span>.</li><li>Klik op <span class='knopfwort'>Lotus Organizer CSV …</span>.</li><li>Kies elk bestand in het Windows-bestandsvenster.</li></ol><p>De Organizer herkent het onderdeel aan de kolomkoppen en begrijpt verschillende scheidingstekens, verschillende tekensets en de Duitse, internationale en Amerikaanse datumnotaties.</p>",
    "pl": "<p>Jeśli używano Lotus Organizer w Windows, przenieś jego dane za pomocą plików CSV.</p><h3>W Lotus Organizer</h3><ol class='schritte'><li>Otwórz wymagany dział.</li><li>Wybierz <i>Plik ▸ Eksportuj</i>.</li><li>Wybierz rozdzielany plik ASCII lub CSV.</li><li>Zapisz plik i powtórz czynność dla pozostałych działów.</li></ol><h3>W Magnolie Organizer dla Windows</h3><ol class='schritte'><li>Otwórz <span class='knopfwort'>Ustawienia ▸ Importuj</span>.</li><li>Kliknij <span class='knopfwort'>Lotus Organizer CSV...</span>.</li><li>Wybierz każdy plik w oknie wyboru plików Windows.</li></ol><p>Organizer rozpoznaje dział po nagłówkach kolumn i obsługuje różne separatory, zestawy znaków oraz niemieckie, międzynarodowe i amerykańskie formaty daty.</p>",
    "pt": "<p>Se utilizou o Lotus Organizer no Windows, transfira os seus dados através de ficheiros CSV.</p><h3>No Lotus Organizer</h3><ol class='schritte'><li>Abra a secção pretendida.</li><li>Selecione <i>Ficheiro ▸ Exportar</i>.</li><li>Escolha um ficheiro ASCII delimitado ou CSV.</li><li>Guarde o ficheiro e repita a operação para as restantes secções.</li></ol><h3>No Magnolie Organizer para Windows</h3><ol class='schritte'><li>Abra <span class='knopfwort'>Definições ▸ Importar</span>.</li><li>Clique em <span class='knopfwort'>Lotus Organizer CSV …</span>.</li><li>Escolha cada ficheiro na caixa de diálogo de ficheiros do Windows.</li></ol><p>O Organizador reconhece a secção pelos cabeçalhos das colunas e compreende separadores diferentes, conjuntos de caracteres diferentes e os formatos de data alemão, internacional e norte-americano.</p>",
    "ru": "<p>Если вы использовали Lotus Organizer в Windows, перенесите его данные с помощью файлов CSV.</p><h3>В Lotus Organizer</h3><ol class='schritte'><li>Откройте нужный раздел.</li><li>Выберите <i>Файл ▸ Экспорт</i>.</li><li>Выберите файл ASCII с разделителями или CSV.</li><li>Сохраните файл и повторите это для других разделов.</li></ol><h3>В Magnolie Organizer для Windows</h3><ol class='schritte'><li>Откройте <span class='knopfwort'>Настройки ▸ Импорт</span>.</li><li>Нажмите <span class='knopfwort'>CSV Lotus Organizer …</span>.</li><li>Выберите каждый файл в диалоге файлов Windows.</li></ol><p>Organizer определяет раздел по заголовкам столбцов и понимает разные разделители, кодировки, а также немецкие, международные и американские форматы даты.</p>",
    "tr": "<p>Windows üzerinde Lotus Organizer kullandıysanız verilerini CSV dosyalarıyla aktarın.</p><h3>Lotus Organizer içinde</h3><ol class='schritte'><li>Gerekli bölümü açın.</li><li><i>Dosya ▸ Dışa aktar</i> seçeneğini seçin.</li><li>Sınırlayıcılarla ayrılmış ASCII veya CSV dosyası seçin.</li><li>Dosyayı kaydedin ve diğer bölümler için yineleyin.</li></ol><h3>Windows için Magnolie Organizer içinde</h3><ol class='schritte'><li><span class='knopfwort'>Ayarlar ▸ İçe aktar</span> bölümünü açın.</li><li><span class='knopfwort'>Lotus Organizer CSV …</span> düğmesine tıklayın.</li><li>Windows dosya iletişim kutusunda her dosyayı seçin.</li></ol><p>Organizer bölümü sütun başlıklarından tanır; farklı ayırıcıları, karakter kümelerini ve Alman, uluslararası ve ABD tarih biçimlerini anlar.</p>",
    "uk": "<p>Якщо ви користувалися Lotus Organizer у Windows, перенесіть його дані за допомогою файлів CSV.</p><h3>У Lotus Organizer</h3><ol class='schritte'><li>Відкрийте потрібний розділ.</li><li>Виберіть <i>Файл ▸ Експорт</i>.</li><li>Виберіть файл ASCII з роздільниками або CSV.</li><li>Збережіть файл і повторіть це для інших розділів.</li></ol><h3>У Magnolie Organizer для Windows</h3><ol class='schritte'><li>Відкрийте <span class='knopfwort'>Налаштування ▸ Імпорт</span>.</li><li>Натисніть <span class='knopfwort'>Lotus Organizer CSV …</span>.</li><li>Виберіть кожен файл у діалозі файлів Windows.</li></ol><p>Organizer розпізнає розділ за заголовками стовпців і розуміє різні роздільники, кодування, а також німецькі, міжнародні й американські формати дати.</p>",
    "zh-cn": "<p>如果您曾在 Windows 上使用 Lotus Organizer，请通过 CSV 文件传输其数据。</p><h3>在 Lotus Organizer 中</h3><ol class='schritte'><li>打开所需分区。</li><li>选择<i>文件 ▸ 导出</i>。</li><li>选择分隔 ASCII 文件或 CSV 文件。</li><li>保存文件，并对其他分区重复此操作。</li></ol><h3>在 Windows 版 Magnolie Organizer 中</h3><ol class='schritte'><li>打开 <span class='knopfwort'>设置 ▸ 导入</span>。</li><li>点击 <span class='knopfwort'>Lotus Organizer CSV …</span>。</li><li>在 Windows 文件对话框中依次选择各个文件。</li></ol><p>Organizer 会根据列标题识别分区，并能理解不同的分隔符、字符集以及德式、国际和美式日期格式。</p>"
  },
  "exporting-data-to-other-programs": {
    "en": "<p>Under <span class='knopfwort'>Settings ▸ Export</span>, export data as ICS, VCF, LDIF, or Lotus CSV.</p><h3>Complete Magnolie archive (.magnolie)</h3><p>For a move between Windows and Linux, export a complete archive. It includes all application data, contact photos, and images and PDF files in notes and the recycle bin. You can assign an archive password; without one, the Organizer explicitly warns that the file is unencrypted.</p><h3>Individual formats</h3><p>ICS is intended for calendars and tasks, VCF and LDIF for address books, and Lotus CSV for classic Lotus appointments. Standard formats cannot represent every Magnolie property, so use a complete archive for a complete round trip.</p>",
    "de": "<p>Unter <span class='knopfwort'>Einstellungen ▸ Export</span> geben Sie Daten als ICS, VCF, LDIF oder Lotus-CSV weiter.</p><h3>Magnolie-Gesamtarchiv (.magnolie)</h3><p>Für einen Wechsel zwischen Windows und Linux exportieren Sie ein Gesamtarchiv. Es enthält alle Anwendungsdaten, Kontaktfotos sowie Bilder und PDF-Dateien in Notizen und Papierkorb. Sie können ein Archivkennwort vergeben; ohne Kennwort weist der Organizer ausdrücklich auf die unverschlüsselte Datei hin.</p><h3>Einzelformate</h3><p>ICS eignet sich für Kalender und Aufgaben, VCF und LDIF für Adressbücher und Lotus-CSV für klassische Lotus-Termine. Standardformate können nicht jede Magnolie-Eigenschaft darstellen; für einen vollständigen Rundlauf verwenden Sie deshalb ein Gesamtarchiv.</p>",
    "ar": "<p>من <span class='knopfwort'>الإعدادات ▸ التصدير</span>، صدّر البيانات بصيغة ICS أو VCF أو LDIF أو Lotus CSV.</p><h3>أرشيف Magnolie الكامل (.magnolie)</h3><p>للانتقال بين Windows وLinux، صدّر أرشيفا كاملا. فهو يتضمن جميع بيانات التطبيق وصور جهات الاتصال والصور وملفات PDF في الملاحظات وسلة المحذوفات. يمكنك تعيين كلمة مرور للأرشيف؛ ومن دونها يحذر Organizer صراحة من أن الملف غير مشفر.</p><h3>التنسيقات الفردية</h3><p>خُصص ICS للتقويمات والمهام، وVCF وLDIF لدفاتر العناوين، وLotus CSV لمواعيد Lotus التقليدية. لا تستطيع التنسيقات القياسية تمثيل كل خصائص Magnolie، لذا استخدم أرشيفا كاملا لإجراء نقل كامل ذهابا وإيابا.</p>",
    "be": "<p>Праз <span class='knopfwort'>Налады ▸ Экспартаваць</span> экспартуйце даныя ў ICS, VCF, LDIF або Lotus CSV.</p><h3>Поўны архіў Magnolie (.magnolie)</h3><p>Для пераезду паміж Windows і Linux экспартуйце поўны архіў. Ён змяшчае ўсе даныя праграмы, фотаздымкі кантактаў, а таксама выявы і PDF-файлы ў нататках і сметніцы. Можна задаць пароль архіва; без яго Organizer яўна папярэджвае, што файл не зашыфраваны.</p><h3>Асобныя фарматы</h3><p>ICS прызначаны для календароў і заданняў, VCF і LDIF — для адрасных кніг, Lotus CSV — для класічных сустрэч Lotus. Стандартныя фарматы не могуць прадставіць кожную ўласцівасць Magnolie, таму для поўнага пераносу ў абодва бакі карыстайцеся поўным архівам.</p>",
    "cs": "<p>V části <span class='knopfwort'>Nastavení ▸ Exportovat</span> exportujte data jako ICS, VCF, LDIF nebo Lotus CSV.</p><h3>Úplný archiv Magnolie (.magnolie)</h3><p>Pro přesun mezi Windows a Linuxem exportujte úplný archiv. Obsahuje všechna data aplikace, fotografie kontaktů a obrázky i soubory PDF v poznámkách a koši. Můžete nastavit heslo archivu; bez něj Organizer výslovně upozorní, že soubor není šifrován.</p><h3>Jednotlivé formáty</h3><p>ICS je určen pro kalendáře a úkoly, VCF a LDIF pro adresáře a Lotus CSV pro klasické schůzky Lotus. Standardní formáty nedokážou zachytit každou vlastnost Magnolie, proto pro úplný obousměrný přenos použijte úplný archiv.</p>",
    "da": "<p>Under <span class='knopfwort'>Indstillinger ▸ Eksportér</span> eksporterer du data som ICS, VCF, LDIF eller Lotus-CSV.</p><h3>Komplet Magnolie-arkiv (.magnolie)</h3><p>Ved flytning mellem Windows og Linux eksporterer du et komplet arkiv. Det indeholder alle programdata, kontaktbilleder samt billeder og PDF-filer i noter og papirkurv. Du kan tildele en arkivadgangskode; uden en sådan advarer Organizeren udtrykkeligt om, at filen ikke er krypteret.</p><h3>Enkelte formater</h3><p>ICS er beregnet til kalendere og opgaver, VCF og LDIF til adressebøger og Lotus-CSV til klassiske Lotus-aftaler. Standardformater kan ikke gengive alle Magnolies egenskaber, så brug et komplet arkiv til en fuldstændig tur-retur.</p>",
    "es": "<p>En <span class='knopfwort'>Ajustes ▸ Exportar</span> puede exportar sus datos como ICS, VCF, LDIF o CSV de Lotus.</p><h3>Archivo completo de Magnolie (.magnolie)</h3><p>Para un traslado entre Windows y Linux, exporte un archivo completo. Incluye todos los datos de la aplicación, las fotos de los contactos y las imágenes y los ficheros PDF de las notas y de la papelera. Puede asignar una contraseña de archivo; si no lo hace, el Organizador advierte expresamente de que el fichero no está cifrado.</p><h3>Formatos sueltos</h3><p>ICS está pensado para calendarios y tareas, VCF y LDIF para libretas de direcciones, y el CSV de Lotus para las citas clásicas de Lotus. Los formatos estándar no pueden representar todas las propiedades de Magnolie, así que utilice un archivo completo para una ida y vuelta completa.</p>",
    "fr": "<p>Sous <span class='knopfwort'>Paramètres ▸ Exporter</span>, exportez vos données au format ICS, VCF, LDIF ou CSV Lotus.</p><h3>Archive Magnolie complète (.magnolie)</h3><p>Pour un déménagement entre Windows et Linux, exportez une archive complète. Elle contient toutes les données de l’application, les photos des contacts ainsi que les images et fichiers PDF des notes et de la corbeille. Vous pouvez attribuer un mot de passe d’archive ; à défaut, l’Organizer avertit explicitement que le fichier n’est pas chiffré.</p><h3>Formats individuels</h3><p>ICS est destiné aux calendriers et aux tâches, VCF et LDIF aux carnets d’adresses, et le CSV Lotus aux rendez-vous Lotus classiques. Les formats standard ne peuvent pas représenter toutes les propriétés de Magnolie ; pour un aller-retour complet, utilisez donc une archive complète.</p>",
    "hi": "<p><span class='knopfwort'>सेटिंग्स ▸ निर्यात करें</span> में डेटा को ICS, VCF, LDIF या Lotus CSV के रूप में निर्यात करें।</p><h3>संपूर्ण Magnolie संग्रह (.magnolie)</h3><p>Windows और Linux के बीच जाने के लिए संपूर्ण संग्रह निर्यात करें। इसमें एप्लिकेशन का सारा डेटा, संपर्क फ़ोटो तथा नोट्स और रीसायकल बिन में चित्र और PDF फ़ाइलें शामिल हैं। आप संग्रह पासवर्ड निर्धारित कर सकते हैं; पासवर्ड न होने पर Organizer स्पष्ट चेतावनी देता है कि फ़ाइल एन्क्रिप्टेड नहीं है।</p><h3>अलग-अलग प्रारूप</h3><p>ICS कैलेंडर और कार्यों के लिए, VCF और LDIF पता पुस्तिकाओं के लिए तथा Lotus CSV पुराने Lotus अपॉइंटमेंट के लिए है। मानक प्रारूप Magnolie की हर विशेषता नहीं दिखा सकते, इसलिए पूर्ण आदान-प्रदान के लिए संपूर्ण संग्रह उपयोग करें।</p>",
    "hsb": "<p>Pod <span class='knopfwort'>Nastajenja ▸ Eksportować</span> eksportujće daty jako ICS, VCF, LDIF abo Lotus CSV.</p><h3>Dospołny archiw Magnolie (.magnolie)</h3><p>Za změnu mjez Windows a Linuxom eksportujće dospołny archiw. Wobsahuje wšitke nałoženske daty, kontaktowe fota kaž tež wobrazy a PDF-dataje w noticach a papjerowym košu. Móžeće archiwowe hesło postajić; bjez njeho Organizer wuraznje warnuje, zo dataja njeje zaklučowana.</p><h3>Jednotliwe formaty</h3><p>ICS je za protyki a nadawki, VCF a LDIF za adresniki a Lotus CSV za klasiske terminy Lotus. Standardne formaty njemóža kóždu kajkosć Magnolie zwobraznić, tuž wužiwajće za dospołny přenos tam a wróćo dospołny archiw.</p>",
    "it": "<p>In <span class='knopfwort'>Impostazioni ▸ Esporta</span> potete esportare i dati come ICS, VCF, LDIF o CSV Lotus.</p><h3>Archivio Magnolie completo (.magnolie)</h3><p>Per un trasloco tra Windows e Linux esportate un archivio completo. Contiene tutti i dati dell'applicazione, le foto dei contatti e le immagini e i file PDF delle note e del cestino. Potete assegnare una password d'archivio; senza, l'Organizer avverte espressamente che il file non è cifrato.</p><h3>Formati singoli</h3><p>ICS è pensato per calendari e attività, VCF e LDIF per le rubriche e il CSV Lotus per gli appuntamenti Lotus classici. I formati standard non possono rappresentare ogni proprietà di Magnolie: per un ciclo completo usate quindi un archivio completo.</p>",
    "ja": "<p><span class='knopfwort'>設定 ▸ エクスポート</span> で、データを ICS、VCF、LDIF、または Lotus CSV としてエクスポートします。</p><h3>完全な Magnolie アーカイブ (.magnolie)</h3><p>Windows と Linux の間で移行するには、完全なアーカイブをエクスポートします。すべてのアプリケーションデータ、連絡先写真、メモとごみ箱内の画像および PDF ファイルが含まれます。アーカイブパスワードを設定できます。設定しない場合は、ファイルが暗号化されていないことを Organizer が明示的に警告します。</p><h3>個別の形式</h3><p>ICS はカレンダーとタスク用、VCF と LDIF はアドレス帳用、Lotus CSV は従来の Lotus の予定用です。標準形式では Magnolie のすべての属性を表せないため、完全な往復には完全なアーカイブを使用します。</p>",
    "nb": "<p>Under <span class='knopfwort'>Innstillinger ▸ Eksporter</span> eksporterer du data som ICS, VCF, LDIF eller Lotus CSV.</p><h3>Komplett Magnolie-arkiv (.magnolie)</h3><p>Eksporter et komplett arkiv ved flytting mellom Windows og Linux. Det inneholder alle programdata, kontaktbilder samt bilder og PDF-filer i notater og papirkurv. Du kan angi et arkivpassord; uten passord advarer Organizeren uttrykkelig om at filen er ukryptert.</p><h3>Enkeltformater</h3><p>ICS er beregnet for kalendere og oppgaver, VCF og LDIF for adressebøker og Lotus CSV for klassiske Lotus-avtaler. Standardformater kan ikke gjengi alle Magnolie-egenskaper, så bruk et komplett arkiv for en fullstendig overføring begge veier.</p>",
    "nl": "<p>Onder <span class='knopfwort'>Instellingen ▸ Exporteren</span> exporteert u gegevens als ICS, VCF, LDIF of Lotus-CSV.</p><h3>Volledig Magnolie-archief (.magnolie)</h3><p>Voor een verhuizing tussen Windows en Linux exporteert u een volledig archief. Het bevat alle toepassingsgegevens, contactfoto's en de afbeeldingen en PDF-bestanden in notities en de prullenbak. U kunt een archiefwachtwoord toekennen; zonder waarschuwt de Organizer uitdrukkelijk dat het bestand niet versleuteld is.</p><h3>Losse indelingen</h3><p>ICS is bedoeld voor agenda's en taken, VCF en LDIF voor adresboeken en Lotus-CSV voor klassieke Lotus-afspraken. Standaardindelingen kunnen niet elke eigenschap van Magnolie weergeven; gebruik daarom een volledig archief voor een volledige heen-en-terugweg.</p>",
    "pl": "<p>W <span class='knopfwort'>Ustawienia ▸ Eksportuj</span> eksportuj dane jako ICS, VCF, LDIF lub Lotus CSV.</p><h3>Kompletne archiwum Magnolie (.magnolie)</h3><p>Przy przenoszeniu między Windows i Linuxem wyeksportuj kompletne archiwum. Zawiera wszystkie dane aplikacji, zdjęcia kontaktów oraz obrazy i pliki PDF w notatkach i koszu. Można nadać hasło archiwum; bez niego Organizer wyraźnie ostrzega, że plik jest niezaszyfrowany.</p><h3>Poszczególne formaty</h3><p>ICS służy do kalendarzy i zadań, VCF i LDIF do książek adresowych, a Lotus CSV do klasycznych spotkań Lotus. Standardowe formaty nie oddają wszystkich właściwości Magnolie, dlatego do pełnego przeniesienia w obie strony użyj kompletnego archiwum.</p>",
    "pt": "<p>Em <span class='knopfwort'>Definições ▸ Exportar</span> pode exportar os seus dados como ICS, VCF, LDIF ou CSV do Lotus.</p><h3>Arquivo Magnolie completo (.magnolie)</h3><p>Para uma mudança entre o Windows e o Linux, exporte um arquivo completo. Inclui todos os dados da aplicação, as fotografias dos contactos e as imagens e ficheiros PDF das notas e do lixo. Pode atribuir uma palavra-passe de arquivo; sem ela, o Organizador avisa expressamente de que o ficheiro não está cifrado.</p><h3>Formatos avulsos</h3><p>O ICS destina-se a calendários e tarefas, o VCF e o LDIF a livros de endereços, e o CSV do Lotus aos compromissos clássicos do Lotus. Os formatos padrão não conseguem representar todas as propriedades do Magnolie, por isso utilize um arquivo completo para uma ida e volta completa.</p>",
    "ru": "<p>В разделе <span class='knopfwort'>Настройки ▸ Экспорт</span> экспортируйте данные как ICS, VCF, LDIF или Lotus CSV.</p><h3>Полный архив Magnolie (.magnolie)</h3><p>Для перехода между Windows и Linux экспортируйте полный архив. Он содержит все данные приложения, фотографии контактов, а также изображения и файлы PDF в заметках и корзине. Можно назначить пароль архива; без него Organizer явно предупреждает, что файл не зашифрован.</p><h3>Отдельные форматы</h3><p>ICS предназначен для календарей и задач, VCF и LDIF — для адресных книг, Lotus CSV — для классических встреч Lotus. Стандартные форматы не могут представить все свойства Magnolie, поэтому для полного переноса в обе стороны используйте полный архив.</p>",
    "tr": "<p><span class='knopfwort'>Ayarlar ▸ Dışa aktar</span> altında verileri ICS, VCF, LDIF veya Lotus CSV olarak dışa aktarın.</p><h3>Tam Magnolie arşivi (.magnolie)</h3><p>Windows ile Linux arasında taşınmak için tam arşiv dışa aktarın. Bu arşiv tüm uygulama verilerini, kişi fotoğraflarını ve notlar ile geri dönüşüm kutusundaki resim ve PDF dosyalarını içerir. Arşiv parolası atayabilirsiniz; parola yoksa Organizer dosyanın şifrelenmemiş olduğunu açıkça bildirir.</p><h3>Tek tek biçimler</h3><p>ICS takvimler ve görevler, VCF ve LDIF adres defterleri, Lotus CSV ise klasik Lotus randevuları içindir. Standart biçimler her Magnolie özelliğini gösteremez; eksiksiz gidiş dönüş için tam arşiv kullanın.</p>",
    "uk": "<p>У <span class='knopfwort'>Налаштування ▸ Експортувати</span> експортуйте дані як ICS, VCF, LDIF або Lotus CSV.</p><h3>Повний архів Magnolie (.magnolie)</h3><p>Для переходу між Windows і Linux експортуйте повний архів. Він містить усі дані програми, фотографії контактів, а також зображення й файли PDF у нотатках і кошику. Можна призначити пароль архіву; без нього Organizer явно попереджає, що файл не зашифровано.</p><h3>Окремі формати</h3><p>ICS призначено для календарів і завдань, VCF і LDIF — для адресних книг, Lotus CSV — для класичних зустрічей Lotus. Стандартні формати не можуть подати кожну властивість Magnolie, тому для повного перенесення в обидва боки використовуйте повний архів.</p>",
    "zh-cn": "<p>在 <span class='knopfwort'>设置 ▸ 导出</span> 中将数据导出为 ICS、VCF、LDIF 或 Lotus CSV。</p><h3>完整的 Magnolie 存档 (.magnolie)</h3><p>在 Windows 与 Linux 之间迁移时，请导出完整存档。它包含所有应用程序数据、联系人照片，以及笔记和回收站中的图像与 PDF 文件。您可以设置存档密码；如果不设置，Organizer 会明确警告该文件未加密。</p><h3>单独格式</h3><p>ICS 用于日历和任务，VCF 与 LDIF 用于通讯录，Lotus CSV 用于传统 Lotus 约会。标准格式无法表示所有 Magnolie 属性，因此完整往返传输应使用完整存档。</p>"
  },
  "synchronizing-with-online-accounts": {
    "en": "<p>On Windows, Magnolie can synchronize contacts with two sources.</p><h3>Local Windows Contacts folder</h3><p>Your profile's <i>Contacts</i> folder is available without signing in. Magnolie reads and writes only .contact files and does not delete unrelated files.</p><h3>Outlook.com and Microsoft 365</h3><p>Modern Microsoft contacts can optionally be connected through Microsoft Graph. Enter the client ID of your own Microsoft Entra app registration, enable device-code flow, and grant delegated <i>Contacts.ReadWrite</i>. No client secret is needed or stored.</p><p>Magnolie displays a device code and opens Microsoft's verification page. The refresh token is protected for your Windows account with Windows DPAPI and is deleted when you sign out.</p><div class='merke'><b>Without an app registration</b>Local Windows Contacts synchronization and all file imports remain available.</div>",
    "de": "<p>Unter Windows kann Magnolie Kontakte mit zwei Quellen abgleichen.</p><h3>Lokaler Windows-Kontakteordner</h3><p>Der Ordner <i>Kontakte</i> Ihres Windows-Benutzerprofils steht ohne Anmeldung bereit. Magnolie liest und schreibt nur .contact-Dateien und löscht keine fremden Dateien.</p><h3>Outlook.com und Microsoft 365</h3><p>Der moderne Microsoft-Kontaktbestand kann optional über Microsoft Graph angebunden werden. Tragen Sie die Client-ID Ihrer eigenen Microsoft-Entra-Appregistrierung ein, aktivieren Sie den Gerätecodefluss und erlauben Sie die delegierte Berechtigung <i>Contacts.ReadWrite</i>. Ein Client Secret wird weder benötigt noch gespeichert.</p><p>Magnolie zeigt einen Gerätecode und öffnet die Microsoft-Prüfseite. Das Aktualisierungstoken wird mit Windows-DPAPI ausschließlich für Ihr Windows-Benutzerkonto geschützt und beim Abmelden gelöscht.</p><div class='merke'><b>Ohne Appregistrierung</b>Der lokale Windows-Kontakteabgleich und alle Dateiimporte bleiben verfügbar.</div>",
    "ar": "<p>يمكن لـ Magnolie على Windows مزامنة جهات الاتصال مع مصدرين.</p><h3>مجلد جهات اتصال Windows المحلي</h3><p>يتوفر مجلد <i dir='ltr'>Contacts</i> في ملفك الشخصي من دون تسجيل الدخول. يقرأ Magnolie ملفات .contact ويكتبها فقط، ولا يحذف الملفات غير المرتبطة به.</p><h3>Outlook.com وMicrosoft 365</h3><p>يمكن اختياريا ربط جهات اتصال Microsoft الحديثة عبر Microsoft Graph. أدخل معرّف العميل لتسجيل تطبيق Microsoft Entra الخاص بك، وفعّل تدفق رمز الجهاز، وامنح الإذن المفوض <i dir='ltr'>Contacts.ReadWrite</i>. لا يلزم أي سر عميل ولا يُخزن.</p><p>يعرض Magnolie رمز جهاز ويفتح صفحة التحقق لدى Microsoft. يُحمى رمز التحديث لحساب Windows الخاص بك باستخدام Windows DPAPI ويُحذف عند تسجيل الخروج.</p><div class='merke'><b>من دون تسجيل تطبيق</b>تظل مزامنة جهات اتصال Windows المحلية وجميع عمليات استيراد الملفات متاحة.</div>",
    "be": "<p>У Windows Magnolie можа сінхранізаваць кантакты з дзвюма крыніцамі.</p><h3>Лакальная папка Кантакты Windows</h3><p>Папка <i>Кантакты</i> вашага профілю даступная без уваходу. Magnolie чытае і запісвае толькі файлы .contact і не выдаляе староннія файлы.</p><h3>Outlook.com і Microsoft 365</h3><p>Сучасныя кантакты Microsoft можна неабавязкова падключыць праз Microsoft Graph. Увядзіце ідэнтыфікатар кліента ўласнай рэгістрацыі праграмы Microsoft Entra, уключыце паток кода прылады і дайце дэлегаваны дазвол <i>Contacts.ReadWrite</i>. Сакрэт кліента не патрабуецца і не захоўваецца.</p><p>Magnolie паказвае код прылады і адкрывае старонку праверкі Microsoft. Токен абнаўлення абараняецца для вашага ўліковага запісу Windows праз Windows DPAPI і выдаляецца пры выхадзе.</p><div class='merke'><b>Без рэгістрацыі праграмы</b>Лакальная сінхранізацыя Кантактаў Windows і ўвесь імпарт файлаў застаюцца даступнымі.</div>",
    "cs": "<p>Ve Windows může Magnolie synchronizovat kontakty se dvěma zdroji.</p><h3>Místní složka Kontakty Windows</h3><p>Složka <i>Kontakty</i> ve vašem profilu je dostupná bez přihlášení. Magnolie čte a zapisuje pouze soubory .contact a nemaže nesouvisející soubory.</p><h3>Outlook.com a Microsoft 365</h3><p>Moderní kontakty Microsoft lze volitelně připojit přes Microsoft Graph. Zadejte ID klienta vlastní registrace aplikace Microsoft Entra, zapněte tok kódu zařízení a udělte delegované oprávnění <i>Contacts.ReadWrite</i>. Tajný klíč klienta není potřeba ani se neukládá.</p><p>Magnolie zobrazí kód zařízení a otevře ověřovací stránku Microsoft. Obnovovací token je pro váš účet Windows chráněn pomocí Windows DPAPI a při odhlášení se odstraní.</p><div class='merke'><b>Bez registrace aplikace</b>Místní synchronizace Kontaktů Windows a všechny importy souborů zůstávají dostupné.</div>",
    "da": "<p>På Windows kan Magnolie synkronisere kontakter med to kilder.</p><h3>Den lokale Windows-mappe Kontakter</h3><p>Mappen <i>Kontakter</i> i din profil er tilgængelig uden at logge ind. Magnolie læser og skriver kun .contact-filer og sletter ikke fremmede filer.</p><h3>Outlook.com og Microsoft 365</h3><p>Moderne Microsoft-kontakter kan efter ønske forbindes via Microsoft Graph. Indtast klient-id'et for din egen Microsoft Entra-appregistrering, slå enhedskodeflowet til, og giv den delegerede tilladelse <i>Contacts.ReadWrite</i>. Der kræves og gemmes ingen klienthemmelighed.</p><p>Magnolie viser en enhedskode og åbner Microsofts bekræftelsesside. Opdateringstokenet beskyttes for din Windows-konto med Windows DPAPI og slettes, når du logger ud.</p><div class='merke'><b>Uden appregistrering</b>Synkronisering med de lokale Windows-kontakter og alle filimporter er fortsat tilgængelige.</div>",
    "es": "<p>En Windows, Magnolie puede sincronizar contactos con dos orígenes.</p><h3>Carpeta local Contactos de Windows</h3><p>La carpeta <i>Contactos</i> de su perfil está disponible sin iniciar sesión. Magnolie lee y escribe únicamente ficheros .contact y no borra ficheros ajenos.</p><h3>Outlook.com y Microsoft 365</h3><p>Los contactos modernos de Microsoft pueden conectarse opcionalmente mediante Microsoft Graph. Introduzca el identificador de cliente de su propio registro de aplicación de Microsoft Entra, active el flujo de código de dispositivo y conceda el permiso delegado <i>Contacts.ReadWrite</i>. No hace falta ningún secreto de cliente ni se guarda ninguno.</p><p>Magnolie muestra un código de dispositivo y abre la página de verificación de Microsoft. El token de actualización queda protegido para su cuenta de Windows con Windows DPAPI y se borra cuando cierra la sesión.</p><div class='merke'><b>Sin registro de aplicación</b>La sincronización con los Contactos locales de Windows y todas las importaciones de ficheros siguen estando disponibles.</div>",
    "fr": "<p>Sous Windows, Magnolie peut synchroniser les contacts avec deux sources.</p><h3>Dossier Contacts local de Windows</h3><p>Le dossier <i>Contacts</i> de votre profil est disponible sans connexion à un compte. Magnolie lit et écrit uniquement des fichiers .contact et ne supprime aucun fichier étranger.</p><h3>Outlook.com et Microsoft 365</h3><p>Les contacts Microsoft modernes peuvent être reliés en option via Microsoft Graph. Saisissez l’identifiant client de votre propre inscription d’application Microsoft Entra, activez le flux par code d’appareil et accordez l’autorisation déléguée <i>Contacts.ReadWrite</i>. Aucun secret client n’est nécessaire ni conservé.</p><p>Magnolie affiche un code d’appareil et ouvre la page de vérification de Microsoft. Le jeton d’actualisation est protégé pour votre compte Windows par Windows DPAPI et il est supprimé lorsque vous vous déconnectez.</p><div class='merke'><b>Sans inscription d’application</b>La synchronisation des Contacts locaux de Windows et toutes les importations de fichiers restent disponibles.</div>",
    "hi": "<p>Windows पर Magnolie दो स्रोतों के साथ संपर्क सिंक्रनाइज़ कर सकता है।</p><h3>स्थानीय Windows Contacts फ़ोल्डर</h3><p>आपकी प्रोफ़ाइल का <i>Contacts</i> फ़ोल्डर साइन इन किए बिना उपलब्ध है। Magnolie केवल .contact फ़ाइलें पढ़ता और लिखता है तथा असंबंधित फ़ाइलें नहीं हटाता।</p><h3>Outlook.com और Microsoft 365</h3><p>आधुनिक Microsoft संपर्कों को वैकल्पिक रूप से Microsoft Graph से जोड़ा जा सकता है। अपने Microsoft Entra ऐप पंजीकरण की क्लाइंट ID दर्ज करें, डिवाइस-कोड प्रवाह चालू करें और प्रत्यायोजित <i>Contacts.ReadWrite</i> अनुमति दें। किसी क्लाइंट सीक्रेट की आवश्यकता नहीं है और उसे सहेजा नहीं जाता।</p><p>Magnolie एक डिवाइस कोड दिखाता है और Microsoft का सत्यापन पृष्ठ खोलता है। रिफ़्रेश टोकन Windows DPAPI द्वारा आपके Windows खाते के लिए सुरक्षित किया जाता है और साइन आउट करने पर हटा दिया जाता है।</p><div class='merke'><b>ऐप पंजीकरण के बिना</b>स्थानीय Windows Contacts सिंक्रनाइज़ेशन और सभी फ़ाइल आयात उपलब्ध रहते हैं।</div>",
    "hsb": "<p>Pod Windows móže Magnolie kontakty z dwěmaj žórłomaj synchronizować.</p><h3>Lokalny zapis Kontakty Windows</h3><p>Zapis <i>Kontakty</i> wašeho profila steji bjez přizjewjenja k dispoziciji. Magnolie čita a pisa jenož .contact-dataje a njezhaša žane druhe dataje.</p><h3>Outlook.com a Microsoft 365</h3><p>Moderne kontakty Microsoft hodźa so opcionalnje přez Microsoft Graph zwjazać. Zapodajće ID klienta swójskeje registracije nałoženja Microsoft Entra, zmóžńće proces gratoweho koda a dajće delegowanu dowolnosć <i>Contacts.ReadWrite</i>. Tajny kluč klienta njetrjeba so ani njeskładuje.</p><p>Magnolie pokazuje gratowy kod a wočini pruwowansku stronu Microsoft. Wobnowjenski token so za waše konto Windows z Windows DPAPI škita a při wotzjewjenju zhaša.</p><div class='merke'><b>Bjez registracije nałoženja</b>Lokalna synchronizacija Kontaktow Windows a wšitke datajowe importy dale k dispoziciji wostanu.</div>",
    "it": "<p>Su Windows, Magnolie può sincronizzare i contatti con due origini.</p><h3>Cartella Contatti locale di Windows</h3><p>La cartella <i>Contatti</i> del vostro profilo è disponibile senza accedere a un account. Magnolie legge e scrive solo file .contact e non elimina file estranei.</p><h3>Outlook.com e Microsoft 365</h3><p>I contatti Microsoft moderni possono essere collegati facoltativamente tramite Microsoft Graph. Inserite l'ID client della vostra registrazione applicazione Microsoft Entra, attivate il flusso con codice dispositivo e concedete l'autorizzazione delegata <i>Contacts.ReadWrite</i>. Non serve né viene conservato alcun segreto client.</p><p>Magnolie mostra un codice dispositivo e apre la pagina di verifica di Microsoft. Il token di aggiornamento è protetto per il vostro account Windows con Windows DPAPI e viene eliminato quando uscite.</p><div class='merke'><b>Senza registrazione applicazione</b>La sincronizzazione con i Contatti locali di Windows e tutte le importazioni di file restano disponibili.</div>",
    "ja": "<p>Windows 上の Magnolie は、2 つのソースと連絡先を同期できます。</p><h3>ローカルの Windows の連絡先フォルダー</h3><p>プロフィールの <i>連絡先</i> フォルダーはサインインせずに利用できます。Magnolie が読み書きするのは .contact ファイルだけで、無関係なファイルは削除しません。</p><h3>Outlook.com と Microsoft 365</h3><p>最新の Microsoft 連絡先は、必要に応じて Microsoft Graph 経由で接続できます。自分の Microsoft Entra アプリ登録のクライアント ID を入力し、デバイスコードフローを有効にして、委任された <i>Contacts.ReadWrite</i> を許可します。クライアントシークレットは不要で、保存もされません。</p><p>Magnolie はデバイスコードを表示して Microsoft の確認ページを開きます。更新トークンは Windows DPAPI によって Windows アカウント用に保護され、サインアウト時に削除されます。</p><div class='merke'><b>アプリ登録がない場合</b>ローカルの Windows 連絡先との同期とすべてのファイルインポートは引き続き利用できます。</div>",
    "nb": "<p>På Windows kan Magnolie synkronisere kontakter med to kilder.</p><h3>Lokal Windows-kontaktmappe</h3><p>Profilens mappe <i>Kontakter</i> er tilgjengelig uten innlogging. Magnolie leser og skriver bare .contact-filer og sletter ikke uvedkommende filer.</p><h3>Outlook.com og Microsoft 365</h3><p>Moderne Microsoft-kontakter kan valgfritt kobles til via Microsoft Graph. Skriv inn client ID fra din egen Microsoft Entra-appregistrering, aktiver enhetskodeflyt, og gi delegert <i>Contacts.ReadWrite</i>. Ingen client secret er nødvendig eller lagres.</p><p>Magnolie viser en enhetskode og åpner Microsofts bekreftelsesside. Refresh token beskyttes for Windows-kontoen med Windows DPAPI og slettes når du logger av.</p><div class='merke'><b>Uten appregistrering</b>Lokal synkronisering med Windows-kontakter og all filimport er fortsatt tilgjengelig.</div>",
    "nl": "<p>Op Windows kan Magnolie contacten met twee bronnen synchroniseren.</p><h3>Lokale Windows-map Contacten</h3><p>De map <i>Contacten</i> van uw profiel is beschikbaar zonder aanmelden. Magnolie leest en schrijft alleen .contact-bestanden en verwijdert geen vreemde bestanden.</p><h3>Outlook.com en Microsoft 365</h3><p>Moderne Microsoft-contacten kunnen desgewenst via Microsoft Graph worden gekoppeld. Voer de client-id van uw eigen Microsoft Entra-appregistratie in, schakel de apparaatcodestroom in en verleen de gedelegeerde rechten <i>Contacts.ReadWrite</i>. Een clientgeheim is niet nodig en wordt niet bewaard.</p><p>Magnolie toont een apparaatcode en opent de verificatiepagina van Microsoft. Het vernieuwingstoken wordt voor uw Windows-account beschermd met Windows DPAPI en wordt verwijderd wanneer u zich afmeldt.</p><div class='merke'><b>Zonder appregistratie</b>Synchronisatie met de lokale Windows-contacten en alle bestandsimporten blijven beschikbaar.</div>",
    "pl": "<p>W Windows Magnolie może synchronizować kontakty z dwoma źródłami.</p><h3>Lokalny folder Kontakty Windows</h3><p>Folder <i>Kontakty</i> profilu jest dostępny bez logowania. Magnolie odczytuje i zapisuje wyłącznie pliki .contact i nie usuwa innych plików.</p><h3>Outlook.com i Microsoft 365</h3><p>Nowoczesne kontakty Microsoft można opcjonalnie połączyć przez Microsoft Graph. Wpisz identyfikator klienta własnej rejestracji aplikacji Microsoft Entra, włącz przepływ kodu urządzenia i przyznaj delegowane uprawnienie <i>Contacts.ReadWrite</i>. Klucz tajny klienta nie jest potrzebny ani zapisywany.</p><p>Magnolie wyświetla kod urządzenia i otwiera stronę weryfikacji Microsoft. Token odświeżania jest chroniony dla konta Windows przez Windows DPAPI i usuwany przy wylogowaniu.</p><div class='merke'><b>Bez rejestracji aplikacji</b>Lokalna synchronizacja Kontaktów Windows i wszystkie importy plików pozostają dostępne.</div>",
    "pt": "<p>No Windows, o Magnolie pode sincronizar contactos com duas origens.</p><h3>Pasta local Contactos do Windows</h3><p>A pasta <i>Contactos</i> do seu perfil está disponível sem iniciar sessão. O Magnolie lê e escreve apenas ficheiros .contact e não apaga ficheiros alheios.</p><h3>Outlook.com e Microsoft 365</h3><p>Os contactos modernos da Microsoft podem ser ligados opcionalmente através do Microsoft Graph. Introduza o identificador de cliente do seu próprio registo de aplicação Microsoft Entra, ative o fluxo por código de dispositivo e conceda a permissão delegada <i>Contacts.ReadWrite</i>. Não é preciso nem é guardado qualquer segredo de cliente.</p><p>O Magnolie mostra um código de dispositivo e abre a página de verificação da Microsoft. O token de atualização fica protegido para a sua conta do Windows com o Windows DPAPI e é apagado quando termina a sessão.</p><div class='merke'><b>Sem registo de aplicação</b>A sincronização com os Contactos locais do Windows e todas as importações de ficheiros continuam disponíveis.</div>",
    "ru": "<p>В Windows Magnolie может синхронизировать контакты с двумя источниками.</p><h3>Локальная папка Контакты Windows</h3><p>Папка <i>Контакты</i> вашего профиля доступна без входа. Magnolie читает и записывает только файлы .contact и не удаляет посторонние файлы.</p><h3>Outlook.com и Microsoft 365</h3><p>Современные контакты Microsoft можно при желании подключить через Microsoft Graph. Введите идентификатор клиента собственной регистрации приложения Microsoft Entra, включите поток кода устройства и предоставьте делегированное разрешение <i>Contacts.ReadWrite</i>. Секрет клиента не требуется и не сохраняется.</p><p>Magnolie показывает код устройства и открывает страницу проверки Microsoft. Токен обновления защищается для вашей учётной записи Windows с помощью Windows DPAPI и удаляется при выходе.</p><div class='merke'><b>Без регистрации приложения</b>Локальная синхронизация Контактов Windows и весь импорт файлов остаются доступны.</div>",
    "tr": "<p>Magnolie, Windows üzerinde kişileri iki kaynakla eşitleyebilir.</p><h3>Yerel Windows Contacts klasörü</h3><p>Profilinizdeki <i>Contacts</i> klasörü oturum açmadan kullanılabilir. Magnolie yalnızca .contact dosyalarını okur ve yazar; ilgisiz dosyaları silmez.</p><h3>Outlook.com ve Microsoft 365</h3><p>Modern Microsoft kişileri isteğe bağlı olarak Microsoft Graph üzerinden bağlanabilir. Kendi Microsoft Entra uygulama kaydınızın istemci kimliğini girin, aygıt kodu akışını etkinleştirin ve temsilci <i>Contacts.ReadWrite</i> iznini verin. İstemci gizli anahtarı gerekmez ve saklanmaz.</p><p>Magnolie bir aygıt kodu gösterir ve Microsoft doğrulama sayfasını açar. Yenileme belirteci Windows hesabınız için Windows DPAPI ile korunur ve oturumu kapattığınızda silinir.</p><div class='merke'><b>Uygulama kaydı olmadan</b>Yerel Windows Contacts eşitlemesi ve tüm dosya içe aktarmaları kullanılabilir kalır.</div>",
    "uk": "<p>У Windows Magnolie може синхронізувати контакти з двома джерелами.</p><h3>Локальна папка Контакти Windows</h3><p>Папка <i>Контакти</i> вашого профілю доступна без входу. Magnolie читає й записує лише файли .contact і не видаляє сторонні файли.</p><h3>Outlook.com і Microsoft 365</h3><p>Сучасні контакти Microsoft можна за бажання під’єднати через Microsoft Graph. Введіть ідентифікатор клієнта власної реєстрації програми Microsoft Entra, увімкніть потік коду пристрою й надайте делегований дозвіл <i>Contacts.ReadWrite</i>. Секрет клієнта не потрібен і не зберігається.</p><p>Magnolie показує код пристрою й відкриває сторінку перевірки Microsoft. Токен оновлення захищається для вашого облікового запису Windows за допомогою Windows DPAPI і видаляється під час виходу.</p><div class='merke'><b>Без реєстрації програми</b>Локальна синхронізація Контактів Windows і весь імпорт файлів залишаються доступними.</div>",
    "zh-cn": "<p>在 Windows 上，Magnolie 可以与两个来源同步联系人。</p><h3>本地 Windows 联系人文件夹</h3><p>无需登录即可使用您个人资料中的 <i>联系人</i> 文件夹。Magnolie 只读写 .contact 文件，不会删除无关文件。</p><h3>Outlook.com 和 Microsoft 365</h3><p>可以选择通过 Microsoft Graph 连接现代 Microsoft 联系人。输入您自己的 Microsoft Entra 应用注册的客户端 ID，启用设备代码流，并授予委派的 <i>Contacts.ReadWrite</i> 权限。不需要也不会存储客户端密钥。</p><p>Magnolie 会显示设备代码并打开 Microsoft 的验证页面。刷新令牌通过 Windows DPAPI 针对您的 Windows 账户进行保护，并在您注销时删除。</p><div class='merke'><b>没有应用注册时</b>本地 Windows 联系人同步和所有文件导入功能仍然可用。</div>"
  },
  "font-size-and-color": {
    "en": "<p>Under <span class='knopfwort'>Settings ▸ Font</span>, choose the font, color, and size of your entries and inspect the preview.</p><h3>Paper, accessibility, and weather</h3><p>General settings control lined paper, mouse-wheel direction, and the optional keyboard focus frame. Calendar settings control the weather strip and its update interval.</p><h3>Windows notification area</h3><p>The Organizer can remain active beside the Windows clock when minimized or closed. Click its icon to show or hide the window; use the context menu to open it or quit completely.</p><p>Personal window and application settings are stored under <i>%LOCALAPPDATA%\\Magnolie Organizer</i>.</p>",
    "de": "<p>Unter <span class='knopfwort'>Einstellungen ▸ Schrift</span> bestimmen Sie Schriftart, Farbe und Größe Ihrer Einträge und prüfen das Ergebnis in der Vorschau.</p><h3>Papier, Barrierefreiheit und Wetter</h3><p>Die allgemeinen Einstellungen steuern Linienpapier, Mausradrichtung und den optionalen Tastatur-Fokusrahmen. In den Kalendereinstellungen wählen Sie Wetterleiste und Aktualisierungsabstand.</p><h3>Windows-Infobereich</h3><p>Der Organizer kann beim Minimieren oder Schließen neben der Windows-Uhr weiterlaufen. Ein Klick auf sein Symbol zeigt oder verbirgt das Fenster; über das Kontextmenü öffnen oder beenden Sie es vollständig.</p><p>Persönliche Fenster- und Programmeinstellungen liegen unter <i>%LOCALAPPDATA%\\Magnolie Organizer</i>.</p>",
    "ar": "<p>ضمن <span class='knopfwort'>الإعدادات ▸ الطباعة</span>، اختر خط إدخالاتك ولونها وحجمها وعاين النتيجة.</p><h3>الورق وإمكانية الوصول والطقس</h3><p>تتحكم الإعدادات العامة في الورق المسطر واتجاه عجلة الفأرة وإطار تركيز لوحة المفاتيح الاختياري. وتتحكم إعدادات التقويم في شريط الطقس وفاصل تحديثه.</p><h3>منطقة إعلام Windows</h3><p>يمكن أن يظل Organizer نشطا بجوار ساعة Windows عند تصغيره أو إغلاقه. انقر على أيقونته لإظهار النافذة أو إخفائها؛ واستخدم قائمة السياق لفتحها أو لإنهاء التطبيق تماما.</p><p>تُخزن إعدادات النافذة والتطبيق الشخصية ضمن <i dir='ltr'>%LOCALAPPDATA%\\Magnolie Organizer</i>.</p>",
    "be": "<p>У <span class='knopfwort'>Налады ▸ Тыпаграфіка</span> выберыце шрыфт, колер і памер сваіх запісаў і праверце папярэдні прагляд.</p><h3>Папера, даступнасць і надвор’е</h3><p>Агульныя налады кіруюць лінеенай паперай, кірункам кола мышы і неабавязковай рамкай фокуса клавіятуры. Налады календара кіруюць паласой надвор’я і інтэрвалам яе абнаўлення.</p><h3>Вобласць апавяшчэнняў Windows</h3><p>Organizer можа заставацца актыўным каля гадзінніка Windows пасля згортвання або закрыцця. Пстрыкніце яго значок, каб паказаць ці схаваць акно; праз кантэкстнае меню можна адкрыць яго або цалкам выйсці.</p><p>Асабістыя налады акна і праграмы захоўваюцца ў <i>%LOCALAPPDATA%\\Magnolie Organizer</i>.</p>",
    "cs": "<p>V části <span class='knopfwort'>Nastavení ▸ Písmo</span> zvolte písmo, barvu a velikost záznamů a prohlédněte si náhled.</p><h3>Papír, přístupnost a počasí</h3><p>Obecná nastavení řídí linkovaný papír, směr kolečka myši a volitelný rámeček zaměření klávesnice. Nastavení kalendáře řídí pás počasí a interval jeho aktualizace.</p><h3>Oznamovací oblast Windows</h3><p>Organizer může po minimalizaci nebo zavření zůstat aktivní vedle hodin Windows. Klepnutím na ikonu zobrazíte nebo skryjete okno; kontextovou nabídkou jej otevřete nebo úplně ukončíte.</p><p>Osobní nastavení okna a aplikace jsou uložena v <i>%LOCALAPPDATA%\\Magnolie Organizer</i>.</p>",
    "da": "<p>Under <span class='knopfwort'>Indstillinger ▸ Typografi</span> vælger du skrift, farve og størrelse på dine indtastninger og ser forhåndsvisningen.</p><h3>Papir, tilgængelighed og vejr</h3><p>De generelle indstillinger styrer det linjerede papir, musehjulets retning og den valgfri tastaturfokusramme. Kalenderindstillingerne styrer vejrstriben og dens opdateringsinterval.</p><h3>Windows' meddelelsesområde</h3><p>Organizeren kan forblive aktiv ved siden af Windows-uret, når den minimeres eller lukkes. Klik på ikonet for at vise eller skjule vinduet; brug genvejsmenuen til at åbne den eller afslutte helt.</p><p>Personlige vindues- og programindstillinger gemmes under <i>%LOCALAPPDATA%\\Magnolie Organizer</i>.</p>",
    "es": "<p>En <span class='knopfwort'>Ajustes ▸ Tipografía</span> puede elegir la fuente, el color y el tamaño de sus entradas y examinar la vista previa.</p><h3>Papel, accesibilidad y tiempo meteorológico</h3><p>Los ajustes generales gobiernan el papel rayado, el sentido de la rueda del ratón y el marco auxiliar de foco del teclado. Los ajustes del calendario gobiernan la franja del tiempo y su intervalo de actualización.</p><h3>Área de notificación de Windows</h3><p>El Organizador puede seguir activo junto al reloj de Windows cuando se minimiza o se cierra. Haga clic en su icono para mostrar u ocultar la ventana; utilice el menú contextual para abrirlo o para salir por completo.</p><p>Los ajustes personales de ventana y de aplicación se guardan en <i>%LOCALAPPDATA%\\Magnolie Organizer</i>.</p>",
    "fr": "<p>Sous <span class='knopfwort'>Paramètres ▸ Typographie</span>, choisissez la police, la couleur et la taille de vos entrées, et examinez l’aperçu.</p><h3>Papier, accessibilité et météo</h3><p>Les paramètres généraux commandent le papier ligné, le sens de la molette de la souris et le cadre de focus clavier facultatif. Les paramètres du calendrier commandent le bandeau météo et son intervalle d’actualisation.</p><h3>Zone de notification de Windows</h3><p>L’Organizer peut rester actif à côté de l’horloge de Windows lorsqu’il est réduit ou fermé. Cliquez sur son icône pour afficher ou masquer la fenêtre ; utilisez le menu contextuel pour l’ouvrir ou pour quitter complètement.</p><p>Les paramètres personnels de fenêtre et d’application sont enregistrés sous <i>%LOCALAPPDATA%\\Magnolie Organizer</i>.</p>",
    "hi": "<p><span class='knopfwort'>सेटिंग्स ▸ टाइपोग्राफी</span> में अपनी प्रविष्टियों का फ़ॉन्ट, रंग और आकार चुनें तथा पूर्वावलोकन देखें।</p><h3>कागज़, सुलभता और मौसम</h3><p>सामान्य सेटिंग्स रेखांकित कागज़, माउस-व्हील दिशा और वैकल्पिक कीबोर्ड फ़ोकस फ़्रेम नियंत्रित करती हैं। कैलेंडर सेटिंग्स मौसम पट्टी और उसके अपडेट अंतराल को नियंत्रित करती हैं।</p><h3>Windows सूचना क्षेत्र</h3><p>छोटा या बंद किए जाने पर Organizer Windows घड़ी के पास सक्रिय रह सकता है। विंडो दिखाने या छिपाने के लिए उसके आइकन पर क्लिक करें; उसे खोलने या पूरी तरह बंद करने के लिए संदर्भ मेनू का उपयोग करें।</p><p>निजी विंडो और एप्लिकेशन सेटिंग्स <i>%LOCALAPPDATA%\\Magnolie Organizer</i> में सहेजी जाती हैं।</p>",
    "hsb": "<p>Pod <span class='knopfwort'>Nastajenja ▸ Pismo</span> wubjerće pismo, barbu a wulkosć swojich zapiskow a přehladźujće přehlad.</p><h3>Papjer, bjezbarjernosć a wjedro</h3><p>Powšitkowne nastajenja wodźa linijowany papjer, směr myšaceho koleska a opcionalny wobłuk tastaturoweho fokusa. Protykowe nastajenja wodźa wjedrowy pask a jeho aktualizaciski interwal.</p><h3>Wobłuk zdźělenkow Windows</h3><p>Organizer móže po miniměrowanju abo začinjenju pódla časnika Windows aktiwny wostać. Klikńće na jeho symbol, zo byšće wokno pokazali abo schowali; z kontekstowym menijom je wočińće abo program dospołnje skónčće.</p><p>Wosobinske woknowe a nałoženske nastajenja so pod <i>%LOCALAPPDATA%\\Magnolie Organizer</i> składuja.</p>",
    "it": "<p>In <span class='knopfwort'>Impostazioni ▸ Tipografia</span> scegliete carattere, colore e dimensione delle vostre voci ed esaminate l'anteprima.</p><h3>Carta, accessibilità e meteo</h3><p>Le impostazioni generali governano la carta a righe, il verso della rotellina del mouse e la cornice facoltativa del focus da tastiera. Le impostazioni del calendario governano la striscia meteo e il suo intervallo di aggiornamento.</p><h3>Area di notifica di Windows</h3><p>L'Organizer può restare attivo accanto all'orologio di Windows quando viene ridotto a icona o chiuso. Fate clic sulla sua icona per mostrare o nascondere la finestra; usate il menu contestuale per aprirlo o per uscire del tutto.</p><p>Le impostazioni personali di finestra e applicazione sono salvate in <i>%LOCALAPPDATA%\\Magnolie Organizer</i>.</p>",
    "ja": "<p><span class='knopfwort'>設定 ▸ タイポグラフィ</span> で、入力内容のフォント、色、サイズを選び、プレビューを確認します。</p><h3>用紙、アクセシビリティ、天気</h3><p>一般設定では罫線入り用紙、マウスホイールの方向、任意のキーボードフォーカス枠を制御します。カレンダー設定では天気欄と更新間隔を制御します。</p><h3>Windows の通知領域</h3><p>最小化または閉じたときも、Organizer を Windows の時計の横で動作させておけます。アイコンをクリックするとウィンドウを表示または非表示にでき、コンテキストメニューから開くか完全に終了できます。</p><p>個人用のウィンドウ設定とアプリケーション設定は <i>%LOCALAPPDATA%\\Magnolie Organizer</i> に保存されます。</p>",
    "nb": "<p>Under <span class='knopfwort'>Innstillinger ▸ Skrift</span> velger du skrift, farge og størrelse for oppføringene og ser på forhåndsvisningen.</p><h3>Papir, tilgjengelighet og vær</h3><p>Generelle innstillinger styrer linjert papir, retning på musehjulet og den valgfrie rammen for tastaturfokus. Kalenderinnstillinger styrer værstripen og oppdateringsintervallet.</p><h3>Systemstatusfeltet i Windows</h3><p>Organizeren kan forbli aktiv ved siden av Windows-klokken når den minimeres eller lukkes. Klikk på ikonet for å vise eller skjule vinduet; bruk hurtigmenyen for å åpne det eller avslutte helt.</p><p>Personlige vindus- og programinnstillinger lagres under <i>%LOCALAPPDATA%\\Magnolie Organizer</i>.</p>",
    "nl": "<p>Onder <span class='knopfwort'>Instellingen ▸ Typografie</span> kiest u lettertype, kleur en grootte van uw invoer en bekijkt u het voorbeeld.</p><h3>Papier, toegankelijkheid en weer</h3><p>De algemene instellingen sturen het gelinieerde papier, de richting van het muiswiel en het optionele toetsenbordfocuskader. De agenda-instellingen sturen de weerstrook en het verversingsinterval.</p><h3>Windows-systeemvak</h3><p>De Organizer kan naast de Windows-klok actief blijven wanneer u hem verkleint of sluit. Klik op het pictogram om het venster te tonen of te verbergen; gebruik het contextmenu om hem te openen of volledig af te sluiten.</p><p>Persoonlijke venster- en toepassingsinstellingen worden opgeslagen onder <i>%LOCALAPPDATA%\\Magnolie Organizer</i>.</p>",
    "pl": "<p>W <span class='knopfwort'>Ustawienia ▸ Czcionka</span> wybierz czcionkę, kolor i rozmiar wpisów oraz obejrzyj podgląd.</p><h3>Papier, dostępność i pogoda</h3><p>Ustawienia ogólne sterują papierem w linie, kierunkiem kółka myszy i opcjonalną ramką fokusu klawiatury. Ustawienia kalendarza sterują paskiem pogody i odstępem aktualizacji.</p><h3>Obszar powiadomień Windows</h3><p>Organizer może pozostać aktywny obok zegara Windows po zminimalizowaniu lub zamknięciu. Kliknij ikonę, aby pokazać lub ukryć okno; menu kontekstowe pozwala je otworzyć lub całkowicie zakończyć program.</p><p>Osobiste ustawienia okna i aplikacji są przechowywane w <i>%LOCALAPPDATA%\\Magnolie Organizer</i>.</p>",
    "pt": "<p>Em <span class='knopfwort'>Definições ▸ Tipografia</span> escolhe o tipo de letra, a cor e o tamanho das suas entradas e examina a pré-visualização.</p><h3>Papel, acessibilidade e meteorologia</h3><p>As definições gerais comandam o papel pautado, o sentido da roda do rato e a moldura opcional de foco do teclado. As definições do calendário comandam a faixa meteorológica e o seu intervalo de atualização.</p><h3>Área de notificação do Windows</h3><p>O Organizador pode continuar ativo junto ao relógio do Windows quando é minimizado ou fechado. Clique no seu ícone para mostrar ou ocultar a janela; utilize o menu de contexto para o abrir ou para sair por completo.</p><p>As definições pessoais de janela e de aplicação são guardadas em <i>%LOCALAPPDATA%\\Magnolie Organizer</i>.</p>",
    "ru": "<p>В <span class='knopfwort'>Настройки ▸ Типографика</span> выберите шрифт, цвет и размер записей и просмотрите результат.</p><h3>Бумага, доступность и погода</h3><p>Общие настройки управляют линованной бумагой, направлением колеса мыши и необязательной рамкой фокуса клавиатуры. Настройки календаря управляют полосой погоды и интервалом её обновления.</p><h3>Область уведомлений Windows</h3><p>После сворачивания или закрытия Organizer может оставаться активным рядом с часами Windows. Щёлкните его значок, чтобы показать или скрыть окно; контекстное меню позволяет открыть его или полностью завершить работу.</p><p>Личные настройки окна и приложения хранятся в <i>%LOCALAPPDATA%\\Magnolie Organizer</i>.</p>",
    "tr": "<p><span class='knopfwort'>Ayarlar ▸ Tipografi</span> altında kayıtlarınızın yazı tipini, rengini ve boyutunu seçip önizlemeyi inceleyin.</p><h3>Kağıt, erişilebilirlik ve hava durumu</h3><p>Genel ayarlar çizgili kağıdı, fare tekerleği yönünü ve isteğe bağlı klavye odak çerçevesini denetler. Takvim ayarları hava durumu şeridini ve güncelleme aralığını denetler.</p><h3>Windows bildirim alanı</h3><p>Organizer küçültüldüğünde veya kapatıldığında Windows saatinin yanında etkin kalabilir. Pencereyi göstermek veya gizlemek için simgesine tıklayın; açmak veya tamamen kapatmak için bağlam menüsünü kullanın.</p><p>Kişisel pencere ve uygulama ayarları <i>%LOCALAPPDATA%\\Magnolie Organizer</i> altında saklanır.</p>",
    "uk": "<p>У <span class='knopfwort'>Налаштування ▸ Типографіка</span> виберіть шрифт, колір і розмір записів та перегляньте результат.</p><h3>Папір, доступність і погода</h3><p>Загальні налаштування керують лінійованим папером, напрямком колеса миші й необов’язковою рамкою фокуса клавіатури. Налаштування календаря керують смугою погоди та інтервалом її оновлення.</p><h3>Область сповіщень Windows</h3><p>Після згортання або закриття Organizer може залишатися активним біля годинника Windows. Клацніть його піктограму, щоб показати або приховати вікно; контекстне меню дає змогу відкрити його або повністю завершити роботу.</p><p>Особисті налаштування вікна й програми зберігаються в <i>%LOCALAPPDATA%\\Magnolie Organizer</i>.</p>",
    "zh-cn": "<p>在 <span class='knopfwort'>设置 ▸ 排版</span> 中选择条目的字体、颜色和大小，并查看预览。</p><h3>纸张、无障碍和天气</h3><p>常规设置控制横线纸、鼠标滚轮方向和可选的键盘焦点框。日历设置控制天气条及其更新间隔。</p><h3>Windows 通知区域</h3><p>最小化或关闭后，Organizer 可以在 Windows 时钟旁保持活动。点击其图标可显示或隐藏窗口；使用上下文菜单可打开窗口或完全退出。</p><p>个人窗口和应用程序设置存储在 <i>%LOCALAPPDATA%\\Magnolie Organizer</i> 下。</p>"
  },
  "version-and-updates": {
    "en": "<p><span class='knopfwort'>Settings ▸ About</span> shows the program, license, author, and installed handbook versions.</p><h3>Updating Organizer and handbook</h3><p><span class='knopfwort'>Check now</span> checks the published Organizer and handbook releases. A newer handbook is downloaded as the complete Windows installer with a visible SHA-256 checksum and is opened only after successful verification. Leave <b>User handbook</b> selected in the installer. Personal data under <i>%LOCALAPPDATA%\\Magnolie Organizer</i> remain untouched.</p><div class='achtung'><b>No silent installation</b>The Organizer does not perform an unattended installation. Confirm the visible installer yourself.</div><div class='merke'><b>Works offline</b>An installed handbook remains fully readable without an internet connection.</div>",
    "de": "<p><span class='knopfwort'>Einstellungen ▸ Über</span> zeigt Programmfassung, Lizenz, Autor und installierte Handbuchfassung.</p><h3>Organizer und Handbuch aktualisieren</h3><p><span class='knopfwort'>Jetzt prüfen</span> prüft die veröffentlichten Fassungen von Organizer und Handbuch. Ein neueres Handbuch wird als vollständiger Windows-Installer mit sichtbarer SHA-256-Prüfsumme geladen und erst nach erfolgreicher Prüfung geöffnet. Lassen Sie <b>Benutzerhandbuch</b> im Installer ausgewählt. Persönliche Daten unter <i>%LOCALAPPDATA%\\Magnolie Organizer</i> bleiben erhalten.</p><div class='achtung'><b>Keine stille Installation</b>Der Organizer führt keine unbeaufsichtigte Installation aus. Bestätigen Sie den sichtbaren Installer selbst.</div><div class='merke'><b>Offline lesbar</b>Ein installiertes Handbuch bleibt ohne Internet vollständig lesbar.</div>",
    "ar": "<p>يعرض <span class='knopfwort'>الإعدادات ▸ حول</span> إصدارات البرنامج والترخيص والمؤلف والدليل المثبت.</p><h3>تحديث Organizer والدليل</h3><p>يفحص <span class='knopfwort'>التحقق الآن</span> إصدارات Organizer والدليل المنشورة. يُنزّل الدليل الأحدث في صورة مثبت Windows الكامل مع قيمة تحقق SHA-256 ظاهرة، ولا يُفتح إلا بعد نجاح التحقق. اترك <b>دليل المستخدم</b> محددا في المثبت. وتبقى البيانات الشخصية ضمن <i dir='ltr'>%LOCALAPPDATA%\\Magnolie Organizer</i> من دون تغيير.</p><div class='achtung'><b>لا يوجد تثبيت صامت</b>لا يجري Organizer تثبيتا دون إشراف. أكد المثبت الظاهر بنفسك.</div><div class='merke'><b>يعمل دون اتصال</b>يظل الدليل المثبت قابلا للقراءة بالكامل من دون اتصال بالإنترنت.</div>",
    "be": "<p><span class='knopfwort'>Налады ▸ Аб праграме</span> паказвае версіі праграмы, ліцэнзіі, аўтара і ўсталяванага даведніка.</p><h3>Абнаўленне Organizer і даведніка</h3><p><span class='knopfwort'>Праверыць зараз</span> правярае апублікаваныя выпускі Organizer і даведніка. Навейшы даведнік спампоўваецца як поўны ўсталёўшчык Windows з бачнай кантрольнай сумай SHA-256 і адкрываецца толькі пасля паспяховай праверкі. Пакіньце выбраным <b>Даведнік карыстальніка</b> ва ўсталёўшчыку. Асабістыя даныя ў <i>%LOCALAPPDATA%\\Magnolie Organizer</i> не змяняюцца.</p><div class='achtung'><b>Без ціхага ўсталявання</b>Organizer не выконвае аўтаматычнае ўсталяванне без нагляду. Самі пацвердзіце бачны ўсталёўшчык.</div><div class='merke'><b>Працуе без сеткі</b>Усталяваны даведнік цалкам чытаецца без інтэрнэт-злучэння.</div>",
    "cs": "<p><span class='knopfwort'>Nastavení ▸ O aplikaci</span> zobrazuje verzi programu, licenci, autora a verzi nainstalované příručky.</p><h3>Aktualizace Organizeru a příručky</h3><p><span class='knopfwort'>Zkontrolovat nyní</span> zkontroluje vydané verze Organizeru a příručky. Novější příručka se stáhne jako úplný instalátor Windows s viditelným kontrolním součtem SHA-256 a otevře se až po úspěšném ověření. V instalátoru ponechte vybranou položku <b>Uživatelská příručka</b>. Osobní data v <i>%LOCALAPPDATA%\\Magnolie Organizer</i> zůstanou nedotčena.</p><div class='achtung'><b>Žádná tichá instalace</b>Organizer neprovádí bezobslužnou instalaci. Viditelný instalátor potvrďte sami.</div><div class='merke'><b>Funguje offline</b>Nainstalovaná příručka zůstává plně čitelná bez připojení k internetu.</div>",
    "da": "<p><span class='knopfwort'>Indstillinger ▸ Om</span> viser versionerne af program, licens, forfatter og installeret håndbog.</p><h3>Opdatering af Organizer og håndbog</h3><p><span class='knopfwort'>Kontrollér nu</span> undersøger de udgivne versioner af Organizer og håndbog. En nyere håndbog hentes som det komplette Windows-installationsprogram med en synlig SHA-256-kontrolsum og åbnes først efter vellykket verifikation. Lad <b>Brugerhåndbog</b> være markeret i installationsprogrammet. Personlige data under <i>%LOCALAPPDATA%\\Magnolie Organizer</i> forbliver urørte.</p><div class='achtung'><b>Ingen stille installation</b>Organizeren foretager ingen uovervåget installation. Du bekræfter selv det synlige installationsprogram.</div><div class='merke'><b>Virker offline</b>En installeret håndbog kan fortsat læses fuldt ud uden internetforbindelse.</div>",
    "es": "<p><span class='knopfwort'>Ajustes ▸ Acerca de</span> muestra las versiones del programa, la licencia, el autor y el manual instalado.</p><h3>Actualizar el Organizador y el manual</h3><p><span class='knopfwort'>Comprobar ahora</span> consulta las versiones publicadas del Organizador y del manual. Un manual más reciente se descarga como el instalador completo de Windows, con una suma de comprobación SHA-256 visible, y solo se abre tras una verificación correcta. Deje marcado <b>Manual de usuario</b> en el instalador. Sus datos personales en <i>%LOCALAPPDATA%\\Magnolie Organizer</i> permanecen intactos.</p><div class='achtung'><b>Sin instalación automática</b>El Organizador no realiza ninguna instalación desatendida. Confirme usted mismo el instalador visible.</div><div class='merke'><b>Funciona sin conexión</b>Un manual instalado sigue siendo legible por completo sin conexión a Internet.</div>",
    "fr": "<p><span class='knopfwort'>Paramètres ▸ À propos</span> indique les versions du programme, de la licence, de l’auteur et du manuel installé.</p><h3>Mettre à jour l’Organizer et le manuel</h3><p><span class='knopfwort'>Vérifier maintenant</span> contrôle les versions publiées de l’Organizer et du manuel. Un manuel plus récent est téléchargé sous la forme de l’installateur Windows complet, accompagné d’une somme de contrôle SHA-256 visible, et n’est ouvert qu’après vérification réussie. Laissez <b>Manuel d’utilisation</b> sélectionné dans l’installateur. Vos données personnelles sous <i>%LOCALAPPDATA%\\Magnolie Organizer</i> restent intactes.</p><div class='achtung'><b>Aucune installation silencieuse</b>L’Organizer n’effectue aucune installation sans surveillance. Vous confirmez vous-même l’installateur visible.</div><div class='merke'><b>Fonctionne hors ligne</b>Un manuel installé reste entièrement lisible sans connexion à Internet.</div>",
    "hi": "<p><span class='knopfwort'>सेटिंग्स ▸ परिचय</span> प्रोग्राम, लाइसेंस, लेखक और इंस्टॉल की गई पुस्तिका के संस्करण दिखाता है।</p><h3>Organizer और पुस्तिका अपडेट करना</h3><p><span class='knopfwort'>अभी जाँचें</span> प्रकाशित Organizer और पुस्तिका रिलीज़ की जाँच करता है। नई पुस्तिका दृश्यमान SHA-256 चेकसम के साथ संपूर्ण Windows इंस्टॉलर के रूप में डाउनलोड होती है और सफल सत्यापन के बाद ही खोली जाती है। इंस्टॉलर में <b>उपयोगकर्ता पुस्तिका</b> को चयनित रहने दें। <i>%LOCALAPPDATA%\\Magnolie Organizer</i> में निजी डेटा अपरिवर्तित रहता है।</p><div class='achtung'><b>मौन इंस्टॉलेशन नहीं</b>Organizer बिना देखरेख वाला इंस्टॉलेशन नहीं करता। दिखाई देने वाले इंस्टॉलर की पुष्टि स्वयं करें।</div><div class='merke'><b>ऑफ़लाइन काम करता है</b>इंस्टॉल की गई पुस्तिका इंटरनेट कनेक्शन के बिना भी पूरी तरह पढ़ी जा सकती है।</div>",
    "hsb": "<p><span class='knopfwort'>Nastajenja ▸ Wo programje</span> pokazuje wersiju programa, licencu, awtora a wersiju instalowaneje přiručki.</p><h3>Organizer a přiručku aktualizować</h3><p><span class='knopfwort'>Nětko přepruwować</span> kontroluje wozjewjene wersije Organizera a přiručki. Nowša přiručka so jako dospołny instalowak Windows z widźomnej SHA-256-kontrolnej sumu sćahuje a jenož po wuspěšnym přepruwowanju wočini. Wostajće <b>Wužiwarsku přiručku</b> w instalowaku wubranu. Wosobinske daty pod <i>%LOCALAPPDATA%\\Magnolie Organizer</i> so njezměnja.</p><div class='achtung'><b>Žana ćicha instalacija</b>Organizer njepřewjedźe instalaciju bjez dohlada. Wobkrućće widźomny instalowak sami.</div><div class='merke'><b>Offline funguje</b>Instalowana přiručka wostanje bjez internetneho zwiska dospołnje čitajomna.</div>",
    "it": "<p><span class='knopfwort'>Impostazioni ▸ Informazioni</span> mostra le versioni di programma, licenza, autore e manuale installato.</p><h3>Aggiornare l'Organizer e il manuale</h3><p><span class='knopfwort'>Controlla ora</span> verifica le versioni pubblicate dell'Organizer e del manuale. Un manuale più recente viene scaricato come programma di installazione completo per Windows, con una somma di controllo SHA-256 visibile, e viene aperto solo dopo una verifica riuscita. Lasciate selezionato <b>Manuale utente</b> nel programma di installazione. I vostri dati personali in <i>%LOCALAPPDATA%\\Magnolie Organizer</i> restano intatti.</p><div class='achtung'><b>Nessuna installazione automatica</b>L'Organizer non esegue alcuna installazione non presidiata. Confermate voi stessi il programma di installazione visibile.</div><div class='merke'><b>Funziona anche offline</b>Un manuale installato resta interamente leggibile senza connessione a Internet.</div>",
    "ja": "<p><span class='knopfwort'>設定 ▸ このアプリについて</span> には、プログラム、ライセンス、作者、インストール済みハンドブックの各バージョンが表示されます。</p><h3>Organizer とハンドブックの更新</h3><p><span class='knopfwort'>今すぐ確認</span> で公開済みの Organizer とハンドブックのリリースを確認します。新しいハンドブックは、表示される SHA-256 チェックサムを伴う完全な Windows インストーラーとしてダウンロードされ、検証に成功した後でのみ開かれます。インストーラーでは <b>ユーザーハンドブック</b> を選択したままにします。<i>%LOCALAPPDATA%\\Magnolie Organizer</i> にある個人データは変更されません。</p><div class='achtung'><b>サイレントインストールは行わない</b>Organizer は無人インストールを実行しません。表示されたインストーラーを自分で確認してください。</div><div class='merke'><b>オフラインでも動作</b>インストール済みハンドブックは、インターネット接続がなくてもすべて読めます。</div>",
    "nb": "<p><span class='knopfwort'>Innstillinger ▸ Om</span> viser versjonene av program, lisens, forfatter og installert håndbok.</p><h3>Oppdater Organizer og håndbok</h3><p><span class='knopfwort'>Kontroller nå</span> kontrollerer publiserte utgaver av Organizer og håndboken. En nyere håndbok lastes ned som det komplette Windows-installasjonsprogrammet med synlig SHA-256-kontrollsum og åpnes først etter vellykket kontroll. La <b>Brukerhåndbok</b> være valgt i installasjonsprogrammet. Personlige data under <i>%LOCALAPPDATA%\\Magnolie Organizer</i> forblir urørt.</p><div class='achtung'><b>Ingen stille installasjon</b>Organizeren utfører ikke en uovervåket installasjon. Bekreft selv det synlige installasjonsprogrammet.</div><div class='merke'><b>Fungerer uten nett</b>En installert håndbok er fortsatt fullt lesbar uten internettforbindelse.</div>",
    "nl": "<p><span class='knopfwort'>Instellingen ▸ Info</span> toont de versies van programma, licentie, auteur en geïnstalleerd handboek.</p><h3>Organizer en handboek bijwerken</h3><p><span class='knopfwort'>Nu controleren</span> controleert de gepubliceerde uitgaven van Organizer en handboek. Een nieuwer handboek wordt als volledig Windows-installatieprogramma opgehaald, met een zichtbare SHA-256-controlesom, en wordt pas geopend na een geslaagde verificatie. Laat <b>Gebruikershandboek</b> geselecteerd in het installatieprogramma. Persoonlijke gegevens onder <i>%LOCALAPPDATA%\\Magnolie Organizer</i> blijven ongemoeid.</p><div class='achtung'><b>Geen stille installatie</b>De Organizer voert geen onbewaakte installatie uit. U bevestigt zelf het zichtbare installatieprogramma.</div><div class='merke'><b>Werkt offline</b>Een geïnstalleerd handboek blijft volledig leesbaar zonder internetverbinding.</div>",
    "pl": "<p><span class='knopfwort'>Ustawienia ▸ O programie</span> pokazuje wersję programu, licencję, autora i wersję zainstalowanego podręcznika.</p><h3>Aktualizowanie Organizera i podręcznika</h3><p><span class='knopfwort'>Sprawdź teraz</span> sprawdza opublikowane wydania Organizera i podręcznika. Nowszy podręcznik jest pobierany jako kompletny instalator Windows z widoczną sumą SHA-256 i otwierany dopiero po pomyślnej weryfikacji. Pozostaw zaznaczony <b>Podręcznik użytkownika</b> w instalatorze. Dane osobiste w <i>%LOCALAPPDATA%\\Magnolie Organizer</i> pozostają nietknięte.</p><div class='achtung'><b>Bez instalacji cichej</b>Organizer nie wykonuje instalacji nienadzorowanej. Samodzielnie potwierdź widoczny instalator.</div><div class='merke'><b>Działa bez sieci</b>Zainstalowany podręcznik pozostaje w pełni czytelny bez połączenia z Internetem.</div>",
    "pt": "<p><span class='knopfwort'>Definições ▸ Acerca de</span> mostra as versões do programa, da licença, do autor e do manual instalado.</p><h3>Atualizar o Organizador e o manual</h3><p><span class='knopfwort'>Verificar agora</span> consulta as versões publicadas do Organizador e do manual. Um manual mais recente é transferido como instalador completo do Windows, com uma soma de verificação SHA-256 visível, e só é aberto após uma verificação bem-sucedida. Deixe <b>Manual do utilizador</b> selecionado no instalador. Os seus dados pessoais em <i>%LOCALAPPDATA%\\Magnolie Organizer</i> permanecem intactos.</p><div class='achtung'><b>Sem instalação silenciosa</b>O Organizador não realiza qualquer instalação autónoma. Confirme você mesmo o instalador visível.</div><div class='merke'><b>Funciona sem ligação</b>Um manual instalado continua totalmente legível sem ligação à Internet.</div>",
    "ru": "<p><span class='knopfwort'>Настройки ▸ О программе</span> показывает версию программы, лицензию, автора и версию установленного руководства.</p><h3>Обновление Organizer и руководства</h3><p><span class='knopfwort'>Проверить сейчас</span> проверяет опубликованные выпуски Organizer и руководства. Более новое руководство загружается как полный установщик Windows с видимой контрольной суммой SHA-256 и открывается только после успешной проверки. Оставьте выбранным <b>Руководство пользователя</b> в установщике. Личные данные в <i>%LOCALAPPDATA%\\Magnolie Organizer</i> остаются нетронутыми.</p><div class='achtung'><b>Без тихой установки</b>Organizer не выполняет автоматическую установку без участия пользователя. Самостоятельно подтвердите видимый установщик.</div><div class='merke'><b>Работает без сети</b>Установленное руководство полностью читается без подключения к Интернету.</div>",
    "tr": "<p><span class='knopfwort'>Ayarlar ▸ Hakkında</span> program, lisans, yazar ve kurulu el kitabı sürümlerini gösterir.</p><h3>Organizer ve el kitabını güncelleme</h3><p><span class='knopfwort'>Şimdi denetle</span>, yayımlanmış Organizer ve el kitabı sürümlerini denetler. Daha yeni bir el kitabı, görünür SHA-256 sağlama toplamıyla eksiksiz Windows yükleyicisi olarak indirilir ve yalnızca doğrulama başarılı olduktan sonra açılır. Yükleyicide <b>Kullanıcı el kitabı</b> seçeneğini işaretli bırakın. <i>%LOCALAPPDATA%\\Magnolie Organizer</i> altındaki kişisel veriler değişmeden kalır.</p><div class='achtung'><b>Sessiz kurulum yok</b>Organizer gözetimsiz kurulum yapmaz. Görünen yükleyiciyi kendiniz onaylayın.</div><div class='merke'><b>Çevrimdışı çalışır</b>Kurulu el kitabı internet bağlantısı olmadan bütünüyle okunabilir.</div>",
    "uk": "<p><span class='knopfwort'>Налаштування ▸ Про програму</span> показує версію програми, ліцензію, автора й версію встановленого посібника.</p><h3>Оновлення Organizer і посібника</h3><p><span class='knopfwort'>Перевірити зараз</span> перевіряє опубліковані випуски Organizer і посібника. Новіший посібник завантажується як повний інсталятор Windows із видимою контрольною сумою SHA-256 і відкривається лише після успішної перевірки. Залиште вибраним <b>Посібник користувача</b> в інсталяторі. Особисті дані в <i>%LOCALAPPDATA%\\Magnolie Organizer</i> залишаються недоторканими.</p><div class='achtung'><b>Без тихої інсталяції</b>Organizer не виконує автоматичну інсталяцію без нагляду. Самі підтвердьте видимий інсталятор.</div><div class='merke'><b>Працює без мережі</b>Установлений посібник повністю читається без з’єднання з Інтернетом.</div>",
    "zh-cn": "<p><span class='knopfwort'>设置 ▸ 关于</span>显示程序、许可证、作者和已安装手册的版本。</p><h3>更新 Organizer 和手册</h3><p><span class='knopfwort'>立即检查</span>会检查已发布的 Organizer 和手册版本。较新的手册会作为完整的 Windows 安装程序下载，同时显示 SHA-256 校验和，并且仅在验证成功后打开。请在安装程序中保持选中<b>用户手册</b>。<i>%LOCALAPPDATA%\\Magnolie Organizer</i> 下的个人数据不会改变。</p><div class='achtung'><b>不会静默安装</b>Organizer 不会执行无人值守安装。请自行确认显示的安装程序。</div><div class='merke'><b>可离线使用</b>安装的手册在没有互联网连接时仍可完整阅读。</div>"
  },
  "backing-up-and-restoring": {
    "en": "<h3>Where your data is stored</h3><p>Main Organizer data are stored in:</p><div class='beispiel'><b>Path</b>%LOCALAPPDATA%\\Magnolie Organizer\\daten.json</div><p>Open <i>%LOCALAPPDATA%\\Magnolie Organizer</i> in Windows Explorer to see the folder.</p><div class='achtung'><b>Know the scope</b>A main-data backup is not a complete device image. Phone identity and <b>phone.db</b>, KDE pairing, window state, and Magnolienbaum identity and queues are separate. In particular, <b>baum.json</b>, <b>baum-post.json</b>, and <b>baum-eingang.json</b> are unencrypted files outside the main password transaction. Protect your Windows account and back these files up deliberately.</div><h3>Creating and restoring a backup</h3><p><span class='knopfwort'>Create backup</span> normally creates a dated JSON file under <i>Documents\\Magnolie Organizer\\Sicherungen</i>. A password-protected main backup remains protected. Use <span class='knopfwort'>Restore backup</span> to select it in the Windows file dialog; the current data are backed up before replacement.</p>",
    "de": "<h3>Wo Ihre Daten liegen</h3><p>Die Hauptdaten des Organizers stehen in:</p><div class='beispiel'><b>Pfad</b>%LOCALAPPDATA%\\Magnolie Organizer\\daten.json</div><p>Öffnen Sie <i>%LOCALAPPDATA%\\Magnolie Organizer</i> im Windows-Explorer, um den Ordner zu sehen.</p><div class='achtung'><b>Umfang kennen</b>Eine Hauptdatensicherung ist kein vollständiges Geräteabbild. Telefonidentität und <b>phone.db</b>, KDE-Paarung, Fensterzustand sowie Magnolienbaum-Identität und -Warteschlangen liegen getrennt. Insbesondere sind <b>baum.json</b>, <b>baum-post.json</b> und <b>baum-eingang.json</b> unverschlüsselte Dateien außerhalb der Hauptkennwort-Transaktion. Schützen Sie Ihr Windows-Konto und sichern Sie diese Dateien bewusst.</div><h3>Sichern und wiederherstellen</h3><p><span class='knopfwort'>Sicherung erstellen</span> legt normalerweise eine datierte JSON-Datei unter <i>Dokumente\\Magnolie Organizer\\Sicherungen</i> an. Eine kennwortgeschützte Hauptsicherung bleibt geschützt. Mit <span class='knopfwort'>Sicherung wiederherstellen</span> wählen Sie sie im Windows-Dateidialog; vor dem Ersetzen werden die aktuellen Daten gesichert.</p>",
    "ar": "<h3>مكان تخزين بياناتك</h3><p>تُخزن بيانات Organizer الرئيسية في:</p><div class='beispiel' dir='ltr'><b dir='rtl'>المسار</b>%LOCALAPPDATA%\\Magnolie Organizer\\daten.json</div><p>افتح <i dir='ltr'>%LOCALAPPDATA%\\Magnolie Organizer</i> في مستكشف Windows لرؤية المجلد.</p><div class='achtung'><b>اعرف النطاق</b>النسخة الاحتياطية للبيانات الرئيسية ليست صورة كاملة للجهاز. فمعرّف الهاتف و<b dir='ltr'>phone.db</b> واقتران KDE وحالة النافذة ومعرّف Magnolienbaum وقوائم انتظاره منفصلة. وعلى وجه الخصوص، ملفات <b dir='ltr'>baum.json</b> و<b dir='ltr'>baum-post.json</b> و<b dir='ltr'>baum-eingang.json</b> غير مشفرة وتقع خارج معاملة كلمة المرور الرئيسية. احم حساب Windows وانسخ هذه الملفات احتياطيا عن قصد.</div><h3>إنشاء نسخة احتياطية واستعادتها</h3><p>ينشئ <span class='knopfwort'>إنشاء نسخة احتياطية</span> عادة ملف JSON مؤرخا ضمن <i dir='ltr'>Documents\\Magnolie Organizer\\Sicherungen</i>. وتظل النسخة الاحتياطية الرئيسية المحمية بكلمة مرور محمية. استخدم <span class='knopfwort'>استعادة نسخة احتياطية</span> لتحديدها في مربع حوار ملفات Windows؛ وتُنسخ البيانات الحالية احتياطيا قبل استبدالها.</p>",
    "be": "<h3>Дзе захоўваюцца вашы даныя</h3><p>Асноўныя даныя Organizer захоўваюцца ў:</p><div class='beispiel'><b>Шлях</b>%LOCALAPPDATA%\\Magnolie Organizer\\daten.json</div><p>Адкрыйце <i>%LOCALAPPDATA%\\Magnolie Organizer</i> у Правадыру Windows, каб убачыць папку.</p><div class='achtung'><b>Ведайце межы</b>Рэзервовая копія асноўных даных не з’яўляецца поўным вобразам прылады. Ідэнтычнасць тэлефона і <b>phone.db</b>, спалучэнне KDE, стан акна, а таксама ідэнтычнасць і чэргі Magnolienbaum захоўваюцца асобна. У прыватнасці, <b>baum.json</b>, <b>baum-post.json</b> і <b>baum-eingang.json</b> — незашыфраваныя файлы па-за асноўнай транзакцыяй пароля. Абараняйце ўліковы запіс Windows і свядома стварайце рэзервовыя копіі гэтых файлаў.</div><h3>Стварэнне і аднаўленне рэзервовай копіі</h3><p><span class='knopfwort'>Стварыць рэзервовую копію</span> звычайна стварае датаваны файл JSON у <i>Documents\\Magnolie Organizer\\Sicherungen</i>. Абароненая паролем асноўная рэзервовая копія застаецца абароненай. Праз <span class='knopfwort'>Аднавіць рэзервовую копію</span> выберыце яе ў дыялогу файлаў Windows; перад заменай бягучыя даныя рэзервуюцца.</p>",
    "cs": "<h3>Kde jsou uložena vaše data</h3><p>Hlavní data Organizeru jsou uložena zde:</p><div class='beispiel'><b>Cesta</b>%LOCALAPPDATA%\\Magnolie Organizer\\daten.json</div><p>Složku zobrazíte otevřením <i>%LOCALAPPDATA%\\Magnolie Organizer</i> v Průzkumníku Windows.</p><div class='achtung'><b>Znejte rozsah</b>Záloha hlavních dat není úplným obrazem zařízení. Identita telefonu a <b>phone.db</b>, párování KDE, stav okna a identita i fronty Magnolienbaum jsou oddělené. Zejména <b>baum.json</b>, <b>baum-post.json</b> a <b>baum-eingang.json</b> jsou nešifrované soubory mimo hlavní heslovou transakci. Chraňte účet Windows a tyto soubory záměrně zálohujte.</div><h3>Vytvoření a obnovení zálohy</h3><p><span class='knopfwort'>Vytvořit zálohu</span> běžně vytvoří soubor JSON opatřený datem v <i>Documents\\Magnolie Organizer\\Sicherungen</i>. Hlavní záloha chráněná heslem zůstává chráněná. Pomocí <span class='knopfwort'>Obnovit zálohu</span> ji vyberte v dialogu souborů Windows; před nahrazením se aktuální data zazálohují.</p>",
    "da": "<h3>Hvor dine data ligger</h3><p>Organizerens hoveddata ligger i:</p><div class='beispiel'><b>Sti</b>%LOCALAPPDATA%\\Magnolie Organizer\\daten.json</div><p>Åbn <i>%LOCALAPPDATA%\\Magnolie Organizer</i> i Windows Stifinder for at se mappen.</p><div class='achtung'><b>Kend omfanget</b>En sikkerhedskopi af hoveddata er ikke et komplet billede af enheden. Telefonidentitet og <b>phone.db</b>, KDE-parring, vinduestilstand samt Magnolienbaums identitet og køer ligger uden for. Især er <b>baum.json</b>, <b>baum-post.json</b> og <b>baum-eingang.json</b> ukrypterede filer uden for hovedadgangskodens transaktion. Beskyt din Windows-konto, og sikr disse filer bevidst.</div><h3>Opret og gendan en sikkerhedskopi</h3><p><span class='knopfwort'>Opret sikkerhedskopi</span> opretter normalt en dateret JSON-fil under <i>Documents\\Magnolie Organizer\\Sicherungen</i>. En adgangskodebeskyttet hovedsikkerhedskopi forbliver beskyttet. Brug <span class='knopfwort'>Gendan sikkerhedskopi</span> til at vælge den i Windows' fildialog; de nuværende data sikres, før de erstattes.</p>",
    "es": "<h3>Dónde se guardan sus datos</h3><p>Los datos principales del Organizador se guardan en:</p><div class='beispiel'><b>Ruta</b>%LOCALAPPDATA%\\Magnolie Organizer\\daten.json</div><p>Abra <i>%LOCALAPPDATA%\\Magnolie Organizer</i> en el Explorador de Windows para ver la carpeta.</p><div class='achtung'><b>Conoce el alcance</b>Una copia de seguridad de los datos principales no es una imagen completa del dispositivo. La identidad del teléfono y <b>phone.db</b>, el emparejamiento de KDE, el estado de las ventanas y la identidad y las colas del Magnolienbaum van aparte. En particular, <b>baum.json</b>, <b>baum-post.json</b> y <b>baum-eingang.json</b> son ficheros sin cifrar, fuera de la transacción de la contraseña principal. Proteja su cuenta de Windows y guarde esos ficheros de forma deliberada.</div><h3>Crear y restaurar una copia de seguridad</h3><p><span class='knopfwort'>Crear copia de seguridad</span> crea normalmente un fichero JSON con fecha en <i>Documents\\Magnolie Organizer\\Sicherungen</i>. Una copia principal protegida por contraseña sigue estándolo. Utilice <span class='knopfwort'>Restaurar copia de seguridad</span> para elegirla en el diálogo de archivos de Windows; los datos actuales se guardan antes de sustituirse.</p>",
    "fr": "<h3>Où vos données sont enregistrées</h3><p>Les données principales de l’Organizer sont enregistrées dans :</p><div class='beispiel'><b>Chemin</b>%LOCALAPPDATA%\\Magnolie Organizer\\daten.json</div><p>Ouvrez <i>%LOCALAPPDATA%\\Magnolie Organizer</i> dans l’Explorateur Windows pour voir le dossier.</p><div class='achtung'><b>Connaissez l’étendue</b>Une sauvegarde des données principales n’est pas une image complète de l’appareil. L’identité du téléphone et <b>phone.db</b>, l’appairage KDE, l’état des fenêtres ainsi que l’identité et les files d’attente du Magnolienbaum en sont distincts. En particulier, <b>baum.json</b>, <b>baum-post.json</b> et <b>baum-eingang.json</b> sont des fichiers non chiffrés, en dehors de la transaction du mot de passe principal. Protégez votre compte Windows et sauvegardez ces fichiers de manière délibérée.</div><h3>Créer et restaurer une sauvegarde</h3><p><span class='knopfwort'>Créer une sauvegarde</span> crée normalement un fichier JSON daté sous <i>Documents\\Magnolie Organizer\\Sicherungen</i>. Une sauvegarde principale protégée par mot de passe le reste. Utilisez <span class='knopfwort'>Restaurer une sauvegarde</span> pour la sélectionner dans la boîte de dialogue de fichiers de Windows ; les données actuelles sont sauvegardées avant tout remplacement.</p>",
    "hi": "<h3>आपका डेटा कहाँ सहेजा जाता है</h3><p>Organizer का मुख्य डेटा यहाँ सहेजा जाता है:</p><div class='beispiel'><b>पथ</b>%LOCALAPPDATA%\\Magnolie Organizer\\daten.json</div><p>फ़ोल्डर देखने के लिए Windows फ़ाइल एक्सप्लोरर में <i>%LOCALAPPDATA%\\Magnolie Organizer</i> खोलें।</p><div class='achtung'><b>दायरा समझें</b>मुख्य डेटा का बैकअप संपूर्ण डिवाइस छवि नहीं है। फ़ोन पहचान और <b>phone.db</b>, KDE युग्मन, विंडो स्थिति तथा Magnolienbaum पहचान और कतारें अलग हैं। विशेष रूप से <b>baum.json</b>, <b>baum-post.json</b> और <b>baum-eingang.json</b> मुख्य पासवर्ड लेनदेन से बाहर की अनएन्क्रिप्टेड फ़ाइलें हैं। अपने Windows खाते की रक्षा करें और इन फ़ाइलों का सोच-समझकर बैकअप लें।</div><h3>बैकअप बनाना और पुनर्स्थापित करना</h3><p><span class='knopfwort'>बैकअप बनाएँ</span> सामान्यतः <i>Documents\\Magnolie Organizer\\Sicherungen</i> में तारीख वाली JSON फ़ाइल बनाता है। पासवर्ड-सुरक्षित मुख्य बैकअप सुरक्षित रहता है। Windows फ़ाइल संवाद में उसे चुनने के लिए <span class='knopfwort'>बैकअप पुनर्स्थापित करें</span> उपयोग करें; बदलने से पहले वर्तमान डेटा का बैकअप बनाया जाता है।</p>",
    "hsb": "<h3>Hdźe waše daty leža</h3><p>Hłowne daty Organizera so składuja w:</p><div class='beispiel'><b>Šćežka</b>%LOCALAPPDATA%\\Magnolie Organizer\\daten.json</div><p>Wočińće <i>%LOCALAPPDATA%\\Magnolie Organizer</i> w Eksplorerje Windows, zo byšće zapis widźeli.</p><div class='achtung'><b>Wobłuk znać</b>Zawěsćenje hłownych datow njeje dospołny wobraz grata. Identita telefona a <b>phone.db</b>, sparowanje KDE, woknowy staw kaž tež identita a čakanske linki Magnolienbaum su separatne. Wosebje su <b>baum.json</b>, <b>baum-post.json</b> a <b>baum-eingang.json</b> njezaklučowane dataje zwonka hłowneje hesłoweje transakcije. Škitajće swoje konto Windows a zawěsćće tute dataje swědomiće.</div><h3>Zawěsćenje wutworić a wobnowić</h3><p><span class='knopfwort'>Zawěsćenje wutworić</span> wutwori zwjetša datowany JSON-dataj pod <i>Documents\\Magnolie Organizer\\Sicherungen</i>. Z hesłom škitane hłowne zawěsćenje wostanje škitane. Z <span class='knopfwort'>Zawěsćenje wobnowić</span> wubjerće jo w datajowym dialogu Windows; aktualne daty so před narunanjom zawěsćeja.</p>",
    "it": "<h3>Dove sono salvati i vostri dati</h3><p>I dati principali dell'Organizer sono salvati in:</p><div class='beispiel'><b>Percorso</b>%LOCALAPPDATA%\\Magnolie Organizer\\daten.json</div><p>Aprite <i>%LOCALAPPDATA%\\Magnolie Organizer</i> in Esplora file di Windows per vedere la cartella.</p><div class='achtung'><b>Conoscete la portata</b>Un backup dei dati principali non è un'immagine completa del dispositivo. L'identità del telefono e <b>phone.db</b>, l'accoppiamento KDE, lo stato delle finestre e l'identità e le code del Magnolienbaum sono separati. In particolare <b>baum.json</b>, <b>baum-post.json</b> e <b>baum-eingang.json</b> sono file non cifrati, fuori dalla transazione della password principale. Proteggete il vostro account Windows e salvate quei file consapevolmente.</div><h3>Creare e ripristinare un backup</h3><p><span class='knopfwort'>Crea backup</span> crea normalmente un file JSON datato in <i>Documents\\Magnolie Organizer\\Sicherungen</i>. Un backup principale protetto da password resta protetto. Usate <span class='knopfwort'>Ripristina backup</span> per sceglierlo nella finestra di dialogo dei file di Windows; i dati attuali vengono salvati prima della sostituzione.</p>",
    "ja": "<h3>データの保存場所</h3><p>Organizer のメインデータは次の場所に保存されます。</p><div class='beispiel'><b>パス</b>%LOCALAPPDATA%\\Magnolie Organizer\\daten.json</div><p>フォルダーを見るには、Windows エクスプローラーで <i>%LOCALAPPDATA%\\Magnolie Organizer</i> を開きます。</p><div class='achtung'><b>対象範囲を理解する</b>メインデータのバックアップは完全なデバイスイメージではありません。電話 ID と <b>phone.db</b>、KDE ペアリング、ウィンドウ状態、Magnolienbaum の ID とキューは別に保存されます。特に <b>baum.json</b>、<b>baum-post.json</b>、<b>baum-eingang.json</b> は、メインパスワードによる暗号化の対象外にある暗号化されていないファイルです。Windows アカウントを保護し、これらのファイルは別途バックアップしてください。</div><h3>バックアップの作成と復元</h3><p><span class='knopfwort'>バックアップを作成</span> は通常、<i>Documents\\Magnolie Organizer\\Sicherungen</i> に日付付き JSON ファイルを作成します。パスワードで保護されたメインバックアップは保護されたままです。<span class='knopfwort'>バックアップを復元</span> を使って Windows のファイルダイアログで選択します。置き換える前に現在のデータがバックアップされます。</p>",
    "nb": "<h3>Hvor dataene lagres</h3><p>Organizerens hoveddata lagres i:</p><div class='beispiel'><b>Bane</b>%LOCALAPPDATA%\\Magnolie Organizer\\daten.json</div><p>Åpne <i>%LOCALAPPDATA%\\Magnolie Organizer</i> i Windows Utforsker for å se mappen.</p><div class='achtung'><b>Kjenn omfanget</b>En sikkerhetskopi av hoveddata er ikke et komplett enhetsbilde. Telefonidentitet og <b>phone.db</b>, KDE-paring, vindustilstand samt Magnolienbaum-identitet og -køer er separate. Særlig er <b>baum.json</b>, <b>baum-post.json</b> og <b>baum-eingang.json</b> ukrypterte filer utenfor hovedpassordtransaksjonen. Beskytt Windows-kontoen, og sikkerhetskopier disse filene bevisst.</div><h3>Opprett og gjenopprett en sikkerhetskopi</h3><p><span class='knopfwort'>Opprett sikkerhetskopi</span> oppretter normalt en datert JSON-fil under <i>Documents\\Magnolie Organizer\\Sicherungen</i>. En passordbeskyttet hovedsikkerhetskopi forblir beskyttet. Bruk <span class='knopfwort'>Gjenopprett sikkerhetskopi</span> for å velge den i Windows-fildialogen; gjeldende data sikkerhetskopieres før erstatningen.</p>",
    "nl": "<h3>Waar uw gegevens staan</h3><p>De hoofdgegevens van de Organizer staan in:</p><div class='beispiel'><b>Pad</b>%LOCALAPPDATA%\\Magnolie Organizer\\daten.json</div><p>Open <i>%LOCALAPPDATA%\\Magnolie Organizer</i> in Windows Verkenner om de map te zien.</p><div class='achtung'><b>Ken de reikwijdte</b>Een back-up van de hoofdgegevens is geen volledige apparaatkopie. Telefoonidentiteit en <b>phone.db</b>, KDE-koppeling, vensterstatus en identiteit en wachtrijen van de Magnolienbaum staan er los van. In het bijzonder zijn <b>baum.json</b>, <b>baum-post.json</b> en <b>baum-eingang.json</b> onversleutelde bestanden buiten de transactie van het hoofdwachtwoord. Beveilig uw Windows-account en stel die bestanden bewust veilig.</div><h3>Een back-up maken en herstellen</h3><p><span class='knopfwort'>Back-up maken</span> maakt normaal een gedateerd JSON-bestand onder <i>Documents\\Magnolie Organizer\\Sicherungen</i>. Een met wachtwoord beveiligde hoofdback-up blijft beveiligd. Gebruik <span class='knopfwort'>Back-up herstellen</span> om die in het Windows-bestandsvenster te kiezen; de huidige gegevens worden vóór het vervangen veiliggesteld.</p>",
    "pl": "<h3>Gdzie są przechowywane dane</h3><p>Główne dane Organizera znajdują się w:</p><div class='beispiel'><b>Ścieżka</b>%LOCALAPPDATA%\\Magnolie Organizer\\daten.json</div><p>Otwórz <i>%LOCALAPPDATA%\\Magnolie Organizer</i> w Eksploratorze Windows, aby zobaczyć folder.</p><div class='achtung'><b>Znaj zakres</b>Kopia głównych danych nie jest pełnym obrazem urządzenia. Tożsamość telefonu i <b>phone.db</b>, parowanie KDE, stan okna oraz tożsamość i kolejki Magnolienbaum są oddzielne. W szczególności <b>baum.json</b>, <b>baum-post.json</b> i <b>baum-eingang.json</b> są niezaszyfrowanymi plikami poza główną transakcją hasła. Chroń konto Windows i świadomie twórz kopie tych plików.</div><h3>Tworzenie i przywracanie kopii</h3><p><span class='knopfwort'>Utwórz kopię zapasową</span> zwykle tworzy plik JSON z datą w <i>Documents\\Magnolie Organizer\\Sicherungen</i>. Główna kopia chroniona hasłem pozostaje chroniona. Użyj <span class='knopfwort'>Przywróć kopię zapasową</span>, aby wybrać ją w oknie plików Windows; bieżące dane są archiwizowane przed zastąpieniem.</p>",
    "pt": "<h3>Onde ficam guardados os seus dados</h3><p>Os dados principais do Organizador ficam guardados em:</p><div class='beispiel'><b>Caminho</b>%LOCALAPPDATA%\\Magnolie Organizer\\daten.json</div><p>Abra <i>%LOCALAPPDATA%\\Magnolie Organizer</i> no Explorador do Windows para ver a pasta.</p><div class='achtung'><b>Conheça o alcance</b>Uma cópia de segurança dos dados principais não é uma imagem completa do dispositivo. A identidade do telemóvel e o <b>phone.db</b>, o emparelhamento KDE, o estado das janelas e a identidade e as filas do Magnolienbaum ficam à parte. Em particular, <b>baum.json</b>, <b>baum-post.json</b> e <b>baum-eingang.json</b> são ficheiros não cifrados, fora da transação da palavra-passe principal. Proteja a sua conta do Windows e guarde esses ficheiros deliberadamente.</div><h3>Criar e restaurar uma cópia de segurança</h3><p><span class='knopfwort'>Criar cópia de segurança</span> cria normalmente um ficheiro JSON com data em <i>Documents\\Magnolie Organizer\\Sicherungen</i>. Uma cópia principal protegida por palavra-passe continua protegida. Utilize <span class='knopfwort'>Restaurar cópia de segurança</span> para a escolher na caixa de diálogo de ficheiros do Windows; os dados atuais são guardados antes da substituição.</p>",
    "ru": "<h3>Где хранятся ваши данные</h3><p>Основные данные Organizer хранятся здесь:</p><div class='beispiel'><b>Путь</b>%LOCALAPPDATA%\\Magnolie Organizer\\daten.json</div><p>Откройте <i>%LOCALAPPDATA%\\Magnolie Organizer</i> в Проводнике Windows, чтобы увидеть папку.</p><div class='achtung'><b>Учитывайте объём</b>Резервная копия основных данных не является полным образом устройства. Идентификатор телефона и <b>phone.db</b>, сопряжение KDE, состояние окна, а также идентификатор и очереди Magnolienbaum хранятся отдельно. В частности, <b>baum.json</b>, <b>baum-post.json</b> и <b>baum-eingang.json</b> — незашифрованные файлы вне основной парольной транзакции. Защищайте учётную запись Windows и сознательно создавайте резервные копии этих файлов.</div><h3>Создание и восстановление резервной копии</h3><p><span class='knopfwort'>Создать резервную копию</span> обычно создаёт датированный файл JSON в <i>Documents\\Magnolie Organizer\\Sicherungen</i>. Защищённая паролем основная резервная копия остаётся защищённой. Через <span class='knopfwort'>Восстановить резервную копию</span> выберите её в диалоге файлов Windows; перед заменой создаётся резервная копия текущих данных.</p>",
    "tr": "<h3>Verilerinizin saklandığı yer</h3><p>Organizer ana verileri şurada saklanır:</p><div class='beispiel'><b>Yol</b>%LOCALAPPDATA%\\Magnolie Organizer\\daten.json</div><p>Klasörü görmek için Windows Gezgini'nde <i>%LOCALAPPDATA%\\Magnolie Organizer</i> konumunu açın.</p><div class='achtung'><b>Kapsamı bilin</b>Ana veri yedeği eksiksiz bir aygıt görüntüsü değildir. Telefon kimliği ve <b>phone.db</b>, KDE eşleştirmesi, pencere durumu ve Magnolienbaum kimliği ile kuyrukları ayrıdır. Özellikle <b>baum.json</b>, <b>baum-post.json</b> ve <b>baum-eingang.json</b>, ana parola işleminin dışında kalan şifrelenmemiş dosyalardır. Windows hesabınızı koruyun ve bu dosyaları bilinçli olarak yedekleyin.</div><h3>Yedek oluşturma ve geri yükleme</h3><p><span class='knopfwort'>Yedek oluştur</span> normalde <i>Documents\\Magnolie Organizer\\Sicherungen</i> altında tarihli bir JSON dosyası oluşturur. Parola korumalı ana yedek korumalı kalır. Windows dosya iletişim kutusunda seçmek için <span class='knopfwort'>Yedeği geri yükle</span> seçeneğini kullanın; değiştirme öncesinde geçerli veriler yedeklenir.</p>",
    "uk": "<h3>Де зберігаються ваші дані</h3><p>Основні дані Organizer зберігаються тут:</p><div class='beispiel'><b>Шлях</b>%LOCALAPPDATA%\\Magnolie Organizer\\daten.json</div><p>Відкрийте <i>%LOCALAPPDATA%\\Magnolie Organizer</i> у Провіднику Windows, щоб побачити папку.</p><div class='achtung'><b>Знайте обсяг</b>Резервна копія основних даних не є повним образом пристрою. Ідентичність телефону та <b>phone.db</b>, сполучення KDE, стан вікна, а також ідентичність і черги Magnolienbaum зберігаються окремо. Зокрема, <b>baum.json</b>, <b>baum-post.json</b> і <b>baum-eingang.json</b> є незашифрованими файлами поза основною транзакцією пароля. Захищайте обліковий запис Windows і свідомо створюйте резервні копії цих файлів.</div><h3>Створення й відновлення резервної копії</h3><p><span class='knopfwort'>Створити резервну копію</span> зазвичай створює датований файл JSON у <i>Documents\\Magnolie Organizer\\Sicherungen</i>. Захищена паролем основна резервна копія залишається захищеною. Через <span class='knopfwort'>Відновити резервну копію</span> виберіть її в діалозі файлів Windows; перед заміною поточні дані резервуються.</p>",
    "zh-cn": "<h3>数据存储位置</h3><p>Organizer 主数据存储在：</p><div class='beispiel'><b>路径</b>%LOCALAPPDATA%\\Magnolie Organizer\\daten.json</div><p>在 Windows 文件资源管理器中打开 <i>%LOCALAPPDATA%\\Magnolie Organizer</i> 即可查看该文件夹。</p><div class='achtung'><b>了解范围</b>主数据备份不是完整的设备映像。手机身份和 <b>phone.db</b>、KDE 配对、窗口状态以及 Magnolienbaum 身份和队列均单独保存。特别是 <b>baum.json</b>、<b>baum-post.json</b> 和 <b>baum-eingang.json</b>，这些文件未加密，也不在主密码的加密范围内。请保护您的 Windows 账户，并务必单独备份这些文件。</div><h3>创建和恢复备份</h3><p><span class='knopfwort'>创建备份</span>通常会在 <i>Documents\\Magnolie Organizer\\Sicherungen</i> 下创建带日期的 JSON 文件。受密码保护的主备份仍受保护。使用 <span class='knopfwort'>恢复备份</span>在 Windows 文件对话框中选择它；替换前会先备份当前数据。</p>"
  },
  "troubleshooting": {
    "en": "<h3>A reminder does not appear</h3><p>Check that Magnolie Organizer is still running, reminders are enabled, and Windows allows notifications for it. Enable troubleshooting logging only temporarily while reproducing the problem.</p><h3>The notification-area icon is missing</h3><p>Allow Magnolie Organizer under the Windows taskbar-corner or additional-icons settings and check that the application is still running.</p><h3>Spell checking marks nothing</h3><p>Install the required Windows language features under <i>Settings ▸ Time & language ▸ Language & region ▸ Language options</i>.</p><h3>WebView2 is missing</h3><p>Install or repair the current <b>Microsoft Edge WebView2 Runtime</b> and restart the Organizer.</p><h3>The map service cannot find an address</h3><p>Check the country, street, postal code, and city. A route also requires your own complete address.</p>",
    "de": "<h3>Eine Erinnerung erscheint nicht</h3><p>Prüfen Sie, ob Magnolie Organizer noch läuft, Erinnerungen eingeschaltet sind und Windows Benachrichtigungen für die Anwendung zulässt. Aktivieren Sie das Fehlerprotokoll nur vorübergehend, während Sie das Problem nachstellen.</p><h3>Das Symbol im Infobereich fehlt</h3><p>Erlauben Sie Magnolie Organizer in den Windows-Einstellungen für die Taskleistenecke oder weitere Symbole und prüfen Sie, ob die Anwendung noch läuft.</p><h3>Die Rechtschreibprüfung markiert nichts</h3><p>Installieren Sie die benötigten Windows-Sprachfunktionen unter <i>Einstellungen ▸ Zeit und Sprache ▸ Sprache und Region ▸ Sprachoptionen</i>.</p><h3>WebView2 fehlt</h3><p>Installieren oder reparieren Sie die aktuelle <b>Microsoft Edge WebView2 Runtime</b> und starten Sie den Organizer erneut.</p><h3>Der Kartendienst findet die Anschrift nicht</h3><p>Prüfen Sie Land, Straße, Postleitzahl und Ort. Eine Route benötigt auch Ihre vollständige eigene Anschrift.</p>",
    "ar": "<h3>لا يظهر تذكير</h3><p>تحقق من أن Magnolie Organizer ما زال قيد التشغيل، وأن التذكيرات مفعلة، وأن Windows يسمح بإشعاراته. فعّل تسجيل استكشاف الأخطاء مؤقتا فقط أثناء إعادة إحداث المشكلة.</p><h3>أيقونة منطقة الإعلام مفقودة</h3><p>اسمح بـ Magnolie Organizer ضمن إعدادات زاوية شريط مهام Windows أو الأيقونات الإضافية، وتحقق من أن التطبيق ما زال قيد التشغيل.</p><h3>التدقيق الإملائي لا يضع أي علامات</h3><p>ثبّت ميزات لغة Windows المطلوبة ضمن <i>الإعدادات ▸ الوقت واللغة ▸ اللغة والمنطقة ▸ خيارات اللغة</i>.</p><h3>WebView2 مفقود</h3><p>ثبّت أو أصلح أحدث <b>Microsoft Edge WebView2 Runtime</b> وأعد تشغيل Organizer.</p><h3>خدمة الخرائط لا تعثر على عنوان</h3><p>تحقق من البلد والشارع والرمز البريدي والمدينة. ويتطلب المسار أيضا عنوانك الكامل.</p>",
    "be": "<h3>Напамін не з’яўляецца</h3><p>Праверце, што Magnolie Organizer усё яшчэ працуе, напаміны ўключаны і Windows дазваляе для яго апавяшчэнні. Уключайце журнал пошуку непаладак толькі часова падчас паўтарэння праблемы.</p><h3>Значок у вобласці апавяшчэнняў адсутнічае</h3><p>Дазвольце Magnolie Organizer у наладах вугла панэлі задач або дадатковых значкоў Windows і праверце, што праграма ўсё яшчэ працуе.</p><h3>Праверка правапісу нічога не пазначае</h3><p>Усталюйце патрэбныя моўныя кампаненты Windows праз <i>Налады ▸ Час і мова ▸ Мова і рэгіён ▸ Параметры мовы</i>.</p><h3>WebView2 адсутнічае</h3><p>Усталюйце або выпраўце актуальны <b>Microsoft Edge WebView2 Runtime</b> і перазапусціце Organizer.</p><h3>Картаграфічны сэрвіс не знаходзіць адрас</h3><p>Праверце краіну, вуліцу, паштовы індэкс і горад. Для маршруту таксама патрэбны ваш поўны ўласны адрас.</p>",
    "cs": "<h3>Připomínka se nezobrazuje</h3><p>Zkontrolujte, že Magnolie Organizer stále běží, připomínky jsou zapnuté a Windows pro něj povoluje oznámení. Protokol řešení potíží zapínejte jen dočasně při opakování problému.</p><h3>Chybí ikona v oznamovací oblasti</h3><p>Povolte Magnolie Organizer v nastavení rohu hlavního panelu nebo dalších ikon Windows a ověřte, že aplikace stále běží.</p><h3>Kontrola pravopisu nic neoznačuje</h3><p>Nainstalujte potřebné jazykové funkce Windows v části <i>Nastavení ▸ Čas a jazyk ▸ Jazyk a oblast ▸ Možnosti jazyka</i>.</p><h3>Chybí WebView2</h3><p>Nainstalujte nebo opravte aktuální <b>Microsoft Edge WebView2 Runtime</b> a restartujte Organizer.</p><h3>Mapová služba nenajde adresu</h3><p>Zkontrolujte zemi, ulici, PSČ a město. Trasa také vyžaduje vaši úplnou vlastní adresu.</p>",
    "da": "<h3>En påmindelse vises ikke</h3><p>Kontrollér, at Magnolie Organizer stadig kører, at påmindelser er slået til, og at Windows tillader meddelelser for programmet. Slå kun fejlsøgningsloggen til midlertidigt, mens du genskaber problemet.</p><h3>Ikonet i meddelelsesområdet mangler</h3><p>Tillad Magnolie Organizer under Windows-indstillingerne for proceslinjens hjørne eller for yderligere ikoner, og kontrollér, at programmet stadig kører.</p><h3>Stavekontrollen markerer intet</h3><p>Installer de nødvendige Windows-sprogfunktioner under <i>Indstillinger ▸ Klokkeslæt og sprog ▸ Sprog og område ▸ Sprogindstillinger</i>.</p><h3>WebView2 mangler</h3><p>Installer eller reparer den aktuelle <b>Microsoft Edge WebView2 Runtime</b>, og genstart Organizeren.</p><h3>Korttjenesten finder ikke en adresse</h3><p>Kontrollér land, vej, postnummer og by. En rute kræver desuden, at din egen adresse er fuldstændig.</p>",
    "es": "<h3>No aparece un recordatorio</h3><p>Compruebe que Magnolie Organizer sigue en ejecución, que los recordatorios están activados y que Windows le permite mostrar notificaciones. Active el registro de diagnóstico solo de forma temporal mientras reproduce el problema.</p><h3>Falta el icono del área de notificación</h3><p>Permita Magnolie Organizer en los ajustes de Windows de la esquina de la barra de tareas o de los iconos adicionales, y compruebe que la aplicación sigue en ejecución.</p><h3>El corrector ortográfico no subraya nada</h3><p>Instale las características de idioma de Windows necesarias en <i>Ajustes ▸ Hora e idioma ▸ Idioma y región ▸ Opciones de idioma</i>.</p><h3>Falta WebView2</h3><p>Instale o repare la versión actual de <b>Microsoft Edge WebView2 Runtime</b> y reinicie el Organizador.</p><h3>El servicio de mapas no encuentra la dirección</h3><p>Compruebe el país, la calle, el código postal y la ciudad. Una ruta necesita además que su propia dirección esté completa.</p>",
    "fr": "<h3>Un rappel n’apparaît pas</h3><p>Vérifiez que Magnolie Organizer est toujours en cours d’exécution, que les rappels sont activés et que Windows autorise les notifications pour ce programme. N’activez la journalisation de dépannage que temporairement, le temps de reproduire le problème.</p><h3>L’icône de la zone de notification est absente</h3><p>Autorisez Magnolie Organizer dans les paramètres Windows du coin de la barre des tâches ou des icônes supplémentaires, et vérifiez que l’application est toujours en cours d’exécution.</p><h3>La correction orthographique ne signale rien</h3><p>Installez les fonctionnalités linguistiques Windows requises sous <i>Paramètres ▸ Heure et langue ▸ Langue et région ▸ Options linguistiques</i>.</p><h3>WebView2 est absent</h3><p>Installez ou réparez la version actuelle de <b>Microsoft Edge WebView2 Runtime</b>, puis redémarrez l’Organizer.</p><h3>Le service de cartographie ne trouve pas une adresse</h3><p>Vérifiez le pays, la rue, le code postal et la ville. Un itinéraire exige en outre que votre propre adresse soit complète.</p>",
    "hi": "<h3>रिमाइंडर दिखाई नहीं देता</h3><p>जाँचें कि Magnolie Organizer अब भी चल रहा है, रिमाइंडर चालू हैं और Windows उसके लिए सूचनाएँ स्वीकार करता है। समस्या दोहराते समय ही समस्या निवारण लॉगिंग अस्थायी रूप से चालू करें।</p><h3>सूचना-क्षेत्र आइकन नहीं है</h3><p>Windows की टास्कबार-कोना या अतिरिक्त-आइकन सेटिंग्स में Magnolie Organizer को अनुमति दें और जाँचें कि एप्लिकेशन अब भी चल रहा है।</p><h3>वर्तनी जाँच कुछ चिह्नित नहीं करती</h3><p><i>सेटिंग्स ▸ समय और भाषा ▸ भाषा और क्षेत्र ▸ भाषा विकल्प</i> में आवश्यक Windows भाषा सुविधाएँ इंस्टॉल करें।</p><h3>WebView2 उपलब्ध नहीं है</h3><p>वर्तमान <b>Microsoft Edge WebView2 Runtime</b> इंस्टॉल या सुधारें और Organizer फिर शुरू करें।</p><h3>नक्शा सेवा को पता नहीं मिलता</h3><p>देश, सड़क, डाक कोड और शहर जाँचें। मार्ग के लिए आपका अपना पूरा पता भी आवश्यक है।</p>",
    "hsb": "<h3>Dopominanje so njezjewi</h3><p>Přepruwujće, hač Magnolie Organizer hišće běži, dopominanja su zmóžnjene a Windows zdźělenja za njón dowoli. Protokolowanje za pytanje zmylkow zmóžńće jenož nachwilu při wospjetowanju problema.</p><h3>Symbol we wobłuku zdźělenkow faluje</h3><p>Dowolće Magnolie Organizer w nastajenjach Windows za róžk nadawkoweje lajsty abo dalše symbole a přepruwujće, hač nałoženje hišće běži.</p><h3>Přepruwowanje prawopisa ničo njeznamjenja</h3><p>Instalujće trěbne rěčne funkcije Windows pod <i>Nastajenja ▸ Čas a rěč ▸ Rěč a region ▸ Rěčne opcije</i>.</p><h3>WebView2 faluje</h3><p>Instalujće abo porjedźće aktualny <b>Microsoft Edge WebView2 Runtime</b> a startujće Organizer znowa.</p><h3>Kartowa słužba adresu njenamaka</h3><p>Přepruwujće kraj, hasu, póštowe čisło a město. Rota trjeba tež wašu dospołnu swójsku adresu.</p>",
    "it": "<h3>Un promemoria non compare</h3><p>Verificate che Magnolie Organizer sia ancora in esecuzione, che i promemoria siano attivi e che Windows consenta le notifiche. Attivate il registro diagnostico solo temporaneamente, mentre riproducete il problema.</p><h3>Manca l'icona nell'area di notifica</h3><p>Consentite Magnolie Organizer nelle impostazioni di Windows per l'angolo della barra delle applicazioni o le icone aggiuntive, e verificate che l'applicazione sia ancora in esecuzione.</p><h3>Il correttore ortografico non segna nulla</h3><p>Installate le funzionalità di lingua di Windows necessarie in <i>Impostazioni ▸ Data/ora e lingua ▸ Lingua e area geografica ▸ Opzioni lingua</i>.</p><h3>Manca WebView2</h3><p>Installate o riparate la versione attuale di <b>Microsoft Edge WebView2 Runtime</b> e riavviate l'Organizer.</p><h3>Il servizio di mappe non trova un indirizzo</h3><p>Verificate paese, via, codice postale e città. Un itinerario richiede inoltre che il vostro indirizzo sia completo.</p>",
    "ja": "<h3>リマインダーが表示されない</h3><p>Magnolie Organizer がまだ実行中で、リマインダーが有効になっており、Windows が通知を許可していることを確認します。問題を再現するときだけ、トラブルシューティングログを一時的に有効にしてください。</p><h3>通知領域のアイコンがない</h3><p>Windows のタスクバー隅または追加アイコンの設定で Magnolie Organizer を許可し、アプリケーションがまだ実行中か確認します。</p><h3>スペルチェックで何もマークされない</h3><p><i>設定 ▸ 時刻と言語 ▸ 言語と地域 ▸ 言語のオプション</i> で必要な Windows 言語機能をインストールします。</p><h3>WebView2 がない</h3><p>最新の <b>Microsoft Edge WebView2 Runtime</b> をインストールまたは修復し、Organizer を再起動します。</p><h3>地図サービスが住所を見つけられない</h3><p>国、通り、郵便番号、市区町村を確認します。経路には自分の完全な住所も必要です。</p>",
    "nb": "<h3>En påminnelse vises ikke</h3><p>Kontroller at Magnolie Organizer fortsatt kjører, at påminnelser er aktivert, og at Windows tillater varsler fra programmet. Aktiver feilsøkingslogging bare midlertidig mens du gjenskaper problemet.</p><h3>Ikonet i systemstatusfeltet mangler</h3><p>Tillat Magnolie Organizer under Windows-innstillingene for hjørnet av oppgavelinjen eller ekstra ikoner, og kontroller at programmet fortsatt kjører.</p><h3>Stavekontrollen markerer ingenting</h3><p>Installer nødvendige Windows-språkfunksjoner under <i>Innstillinger ▸ Tid og språk ▸ Språk og område ▸ Språkalternativer</i>.</p><h3>WebView2 mangler</h3><p>Installer eller reparer gjeldende <b>Microsoft Edge WebView2 Runtime</b>, og start Organizeren på nytt.</p><h3>Karttjenesten finner ikke en adresse</h3><p>Kontroller land, gate, postnummer og sted. En rute krever også din egen fullstendige adresse.</p>",
    "nl": "<h3>Een herinnering verschijnt niet</h3><p>Controleer of Magnolie Organizer nog draait, of herinneringen zijn ingeschakeld en of Windows meldingen ervoor toestaat. Schakel het foutopsporingslogboek alleen tijdelijk in terwijl u het probleem nabootst.</p><h3>Het systeemvakpictogram ontbreekt</h3><p>Sta Magnolie Organizer toe bij de Windows-instellingen voor de hoek van de taakbalk of voor extra pictogrammen, en controleer of de toepassing nog draait.</p><h3>De spellingcontrole markeert niets</h3><p>Installeer de benodigde Windows-taalfuncties onder <i>Instellingen ▸ Tijd en taal ▸ Taal en regio ▸ Taalopties</i>.</p><h3>WebView2 ontbreekt</h3><p>Installeer of herstel de huidige <b>Microsoft Edge WebView2 Runtime</b> en start de Organizer opnieuw.</p><h3>De kaartdienst vindt een adres niet</h3><p>Controleer land, straat, postcode en plaats. Een route vereist bovendien dat uw eigen adres volledig is.</p>",
    "pl": "<h3>Przypomnienie się nie pojawia</h3><p>Sprawdź, czy Magnolie Organizer nadal działa, przypomnienia są włączone i Windows zezwala mu na powiadomienia. Rejestrowanie diagnostyczne włączaj tylko tymczasowo podczas odtwarzania problemu.</p><h3>Brakuje ikony obszaru powiadomień</h3><p>Zezwól na Magnolie Organizer w ustawieniach narożnika paska zadań lub dodatkowych ikon Windows i sprawdź, czy aplikacja nadal działa.</p><h3>Sprawdzanie pisowni niczego nie zaznacza</h3><p>Zainstaluj wymagane funkcje językowe Windows w <i>Ustawienia ▸ Czas i język ▸ Język i region ▸ Opcje języka</i>.</p><h3>Brakuje WebView2</h3><p>Zainstaluj lub napraw aktualny <b>Microsoft Edge WebView2 Runtime</b> i uruchom Organizer ponownie.</p><h3>Usługa mapowa nie znajduje adresu</h3><p>Sprawdź kraj, ulicę, kod pocztowy i miasto. Trasa wymaga również pełnego własnego adresu.</p>",
    "pt": "<h3>Não aparece um lembrete</h3><p>Verifique se o Magnolie Organizer continua em execução, se os lembretes estão ativados e se o Windows lhe permite mostrar notificações. Ative o registo de diagnóstico apenas temporariamente, enquanto reproduz o problema.</p><h3>Falta o ícone da área de notificação</h3><p>Permita o Magnolie Organizer nas definições do Windows do canto da barra de tarefas ou dos ícones adicionais, e verifique se a aplicação continua em execução.</p><h3>O corretor ortográfico não assinala nada</h3><p>Instale as funcionalidades de idioma do Windows necessárias em <i>Definições ▸ Hora e idioma ▸ Idioma e região ▸ Opções de idioma</i>.</p><h3>Falta o WebView2</h3><p>Instale ou repare a versão atual do <b>Microsoft Edge WebView2 Runtime</b> e reinicie o Organizador.</p><h3>O serviço de mapas não encontra um endereço</h3><p>Verifique o país, a rua, o código postal e a localidade. Um itinerário exige ainda que o seu próprio endereço esteja completo.</p>",
    "ru": "<h3>Напоминание не появляется</h3><p>Убедитесь, что Magnolie Organizer продолжает работать, напоминания включены и Windows разрешает для него уведомления. Включайте диагностический журнал только временно при воспроизведении проблемы.</p><h3>Нет значка в области уведомлений</h3><p>Разрешите Magnolie Organizer в настройках угла панели задач или дополнительных значков Windows и проверьте, что приложение продолжает работать.</p><h3>Проверка орфографии ничего не отмечает</h3><p>Установите требуемые языковые компоненты Windows в <i>Параметры ▸ Время и язык ▸ Язык и регион ▸ Параметры языка</i>.</p><h3>Отсутствует WebView2</h3><p>Установите или восстановите актуальный <b>Microsoft Edge WebView2 Runtime</b> и перезапустите Organizer.</p><h3>Картографическая служба не находит адрес</h3><p>Проверьте страну, улицу, почтовый индекс и город. Для маршрута также нужен ваш полный адрес.</p>",
    "tr": "<h3>Hatırlatıcı görünmüyor</h3><p>Magnolie Organizer uygulamasının hâlâ çalıştığını, hatırlatıcıların etkin olduğunu ve Windows'un bildirimlere izin verdiğini denetleyin. Sorunu yeniden oluştururken sorun giderme günlüğünü yalnızca geçici olarak etkinleştirin.</p><h3>Bildirim alanı simgesi yok</h3><p>Windows görev çubuğu köşesi veya ek simgeler ayarlarında Magnolie Organizer uygulamasına izin verin ve uygulamanın hâlâ çalıştığını denetleyin.</p><h3>Yazım denetimi hiçbir şeyi işaretlemiyor</h3><p>Gerekli Windows dil özelliklerini <i>Ayarlar ▸ Zaman ve dil ▸ Dil ve bölge ▸ Dil seçenekleri</i> altında kurun.</p><h3>WebView2 eksik</h3><p>Güncel <b>Microsoft Edge WebView2 Runtime</b> bileşenini kurun veya onarın ve Organizer uygulamasını yeniden başlatın.</p><h3>Harita hizmeti adresi bulamıyor</h3><p>Ülkeyi, caddeyi, posta kodunu ve şehri denetleyin. Rota için kendi tam adresiniz de gerekir.</p>",
    "uk": "<h3>Нагадування не з’являється</h3><p>Перевірте, що Magnolie Organizer досі працює, нагадування ввімкнено й Windows дозволяє для нього сповіщення. Вмикайте діагностичне журналювання лише тимчасово під час відтворення проблеми.</p><h3>Немає піктограми в області сповіщень</h3><p>Дозвольте Magnolie Organizer у налаштуваннях кута панелі завдань або додаткових піктограм Windows і перевірте, що програма досі працює.</p><h3>Перевірка правопису нічого не позначає</h3><p>Установіть потрібні мовні компоненти Windows у <i>Налаштування ▸ Час і мова ▸ Мова й регіон ▸ Параметри мови</i>.</p><h3>Немає WebView2</h3><p>Установіть або відновіть актуальний <b>Microsoft Edge WebView2 Runtime</b> і перезапустіть Organizer.</p><h3>Картографічна служба не знаходить адресу</h3><p>Перевірте країну, вулицю, поштовий індекс і місто. Для маршруту також потрібна ваша повна адреса.</p>",
    "zh-cn": "<h3>提醒没有出现</h3><p>请检查 Magnolie Organizer 是否仍在运行、提醒是否已启用，以及 Windows 是否允许其发送通知。仅在重现问题时临时启用故障排除日志。</p><h3>通知区域图标缺失</h3><p>在 Windows 任务栏角落或其他图标设置中允许 Magnolie Organizer，并检查应用程序是否仍在运行。</p><h3>拼写检查未标记任何内容</h3><p>在<i>设置 ▸ 时间和语言 ▸ 语言和区域 ▸ 语言选项</i>中安装所需的 Windows 语言功能。</p><h3>缺少 WebView2</h3><p>安装或修复当前的 <b>Microsoft Edge WebView2 Runtime</b>，然后重新启动 Organizer。</p><h3>地图服务找不到地址</h3><p>请检查国家/地区、街道、邮政编码和城市。计算路线还需要您自己的完整地址。</p>"
  },
  "phone-pairing": {
    "en": "<p><b>Phone connection</b> links this Organizer directly and encrypted with Magnolie Notes on exactly one phone. It is independent of the Magnolienbaum.</p><h3>Pair once over WLAN</h3><ol class='schritte'><li>Open <span class='knopfwort'>Settings ▸ Magnolienbaum</span> and select <span class='knopfwort'>Enable Magnolie Notes phone connection</span>. Approve the Windows security prompt if the Organizer asks for the required firewall rule.</li><li>Connect the computer and phone to the same WLAN and click <span class='knopfwort'>Connect phone via WLAN</span>.</li><li>Open phone connection in Magnolie Notes and select this computer.</li><li>Compare the six-digit code on both devices. If it differs, click <span class='knopfwort'>Codes differ</span>. Only if it is exactly the same, click <span class='knopfwort'>Codes match</span> and confirm on the phone.</li></ol><p>The dialog closes when the phone is securely paired. To change phones, first use <span class='knopfwort'>Remove phone connection</span> for the existing phone.</p><h3>Optional Bluetooth data fallback</h3><p>First pair the phone in Windows under <i>Settings ▸ Bluetooth &amp; devices</i>. Then select <span class='knopfwort'>Bluetooth data fallback</span> for the paired phone in the Organizer and choose its system-paired Bluetooth address. The option is disabled when Windows reports no usable radio, permission, driver, or RFCOMM support. WLAN has priority; Bluetooth carries encrypted data only and no HFP audio.</p><div class='achtung'><b>Separate from SMS</b>Native Magnolie phone connection does not send SMS. SMS remains a separate KDE Connect function on <b data-page='kde-sms' class='knopfwort'></b>.</div>",
    "de": "<p>Die <b>Telefonverbindung</b> verbindet diesen Organizer direkt und verschlüsselt mit Magnolie Notes auf genau einem Telefon. Sie ist vom Magnolienbaum unabhängig.</p><h3>Einmal über WLAN koppeln</h3><ol class='schritte'><li>Öffnen Sie <span class='knopfwort'>Einstellungen ▸ Magnolienbaum</span> und markieren Sie <span class='knopfwort'>Magnolie Notes-Telefonverbindung einschalten</span>. Bestätigen Sie die Windows-Sicherheitsabfrage, falls der Organizer die benötigte Firewallregel anfordert.</li><li>Verbinden Sie Computer und Telefon mit demselben WLAN und klicken Sie auf <span class='knopfwort'>Telefon über WLAN verbinden</span>.</li><li>Öffnen Sie in Magnolie Notes die Telefonverbindung und wählen Sie diesen Computer aus.</li><li>Vergleichen Sie den sechsstelligen Code auf beiden Geräten. Weicht er ab, klicken Sie auf <span class='knopfwort'>Codes stimmen nicht überein</span>. Nur wenn er genau gleich ist, klicken Sie auf <span class='knopfwort'>Codes stimmen überein</span> und bestätigen auf dem Telefon.</li></ol><p>Der Dialog schließt sich, sobald das Telefon sicher gekoppelt ist. Um das Telefon zu wechseln, verwenden Sie beim bisherigen Telefon zuerst <span class='knopfwort'>Telefonverbindung entfernen</span>.</p><h3>Optionaler Bluetooth-Daten-Rückfallweg</h3><p>Koppeln Sie das Telefon zuerst in Windows unter <i>Einstellungen ▸ Bluetooth und Geräte</i>. Markieren Sie danach beim gekoppelten Telefon im Organizer <span class='knopfwort'>Bluetooth-Daten als Ausweichverbindung</span> und wählen Sie seine systemgekoppelte Bluetooth-Adresse. Die Option ist gesperrt, wenn Windows kein nutzbares Funkgerät, keine Berechtigung, keinen passenden Treiber oder keine RFCOMM-Unterstützung meldet. WLAN hat Vorrang; Bluetooth überträgt nur verschlüsselte Daten und keinen HFP-Ton.</p><div class='achtung'><b>Von SMS getrennt</b>Die native Magnolie-Telefonverbindung versendet keine SMS. SMS bleibt eine getrennte KDE-Connect-Funktion auf <b data-page='kde-sms' class='knopfwort'></b>.</div>",
    "ar": "<p>يربط <b>اتصال الهاتف</b> هذا الـ Organizer مباشرة وبشكل مشفر مع Magnolie Notes على هاتف واحد فقط. وهو مستقل عن Magnolienbaum.</p><h3>الاقتران مرة واحدة عبر WiFi</h3><ol class='schritte'><li>افتح <span class='knopfwort'>الإعدادات ▸ Magnolienbaum</span> وحدد <span class='knopfwort'>تمكين اتصال الهاتف Magnolie Notes</span>. وافق على مطالبة أمان Windows إذا طلب Organizer قاعدة جدار الحماية المطلوبة.</li><li>صل الكمبيوتر والهاتف بشبكة WiFi نفسها وانقر على <span class='knopfwort'>قم بتوصيل الهاتف عبر شبكة الواي فاي</span>.</li><li>افتح اتصال الهاتف في Magnolie Notes واختر هذا الكمبيوتر.</li><li>قارن الرمز المكون من ستة أرقام على الجهازين. إذا اختلف، فانقر على <span class='knopfwort'>تختلف الأكواد</span>. وإذا كان متطابقا تماما فقط، فانقر على <span class='knopfwort'>الرمز متطابق</span> وأكد على الهاتف.</li></ol><p>يغلق مربع الحوار عند اقتران الهاتف بأمان. لتغيير الهاتف، استخدم أولا <span class='knopfwort'>إزالة الاتصال</span> للهاتف الحالي.</p><h3>رجوع اختياري إلى بيانات Bluetooth</h3><p>اقرن الهاتف أولا في Windows ضمن <i>الإعدادات ▸ Bluetooth والأجهزة</i>. ثم حدد <span class='knopfwort'>الرجوع إلى بيانات Bluetooth</span> للهاتف المقترن في Organizer واختر عنوان Bluetooth المقترن بالنظام. يتعطل الخيار إذا لم يبلغ Windows عن راديو أو إذن أو برنامج تشغيل أو دعم RFCOMM صالح. تكون الأولوية لشبكة WiFi؛ وينقل Bluetooth البيانات المشفرة فقط ولا ينقل صوت HFP.</p><div class='achtung'><b>منفصل عن SMS</b>لا يرسل اتصال هاتف Magnolie الأصلي رسائل SMS. تظل SMS وظيفة منفصلة في KDE Connect على <b data-page='kde-sms' class='knopfwort'></b>.</div>",
    "be": "<p><b>Тэлефоннае злучэнне</b> непасрэдна і ў зашыфраваным выглядзе злучае гэты Organizer з Magnolie Notes толькі на адным тэлефоне. Яно не залежыць ад Magnolienbaum.</p><h3>Аднаразовае спалучэнне праз Wi-Fi</h3><ol class='schritte'><li>Адкрыйце <span class='knopfwort'>Налады ▸ Magnolienbaum</span> і выберыце <span class='knopfwort'>Уключыць тэлефоннае злучэнне Magnolie Notes</span>. Пацвердзіце запыт бяспекі Windows, калі Organizer папросіць патрэбнае правіла брандмаўэра.</li><li>Падключыце камп’ютар і тэлефон да адной сеткі Wi-Fi і націсніце <span class='knopfwort'>Падключыце тэлефон праз Wi-Fi</span>.</li><li>Адкрыйце тэлефоннае злучэнне ў Magnolie Notes і выберыце гэты камп’ютар.</li><li>Параўнайце шасцізначны код на абедзвюх прыладах. Калі ён адрозніваецца, націсніце <span class='knopfwort'>Коды адрозніваюцца</span>. Толькі калі ён цалкам супадае, націсніце <span class='knopfwort'>Код супадае</span> і пацвердзіце на тэлефоне.</li></ol><p>Дыялог закрыецца пасля бяспечнага спалучэння. Каб змяніць тэлефон, спачатку скарыстайцеся <span class='knopfwort'>Выдаліць злучэнне</span> для цяперашняга тэлефона.</p><h3>Неабавязковы рэзервовы Bluetooth-канал даных</h3><p>Спачатку спалучыце тэлефон у Windows праз <i>Налады ▸ Bluetooth і прылады</i>. Затым выберыце <span class='knopfwort'>Рэзервовы перанос дадзеных праз Bluetooth</span> для спалучанага тэлефона ў Organizer і яго сістэмны Bluetooth-адрас. Параметр недаступны, калі Windows не паведамляе пра прыдатны радыёмодуль, дазвол, драйвер або падтрымку RFCOMM. Wi-Fi мае прыярытэт; Bluetooth перадае толькі зашыфраваныя даныя, без гуку HFP.</p><div class='achtung'><b>Асобна ад SMS</b>Уласнае тэлефоннае злучэнне Magnolie не адпраўляе SMS. SMS застаецца асобнай функцыяй KDE Connect на <b data-page='kde-sms' class='knopfwort'></b>.</div>",
    "cs": "<p><b>Připojení telefonu</b> spojuje tento Organizer přímo a šifrovaně s Magnolie Notes právě na jednom telefonu. Je nezávislé na Magnolienbaum.</p><h3>Jednorázové spárování přes WLAN</h3><ol class='schritte'><li>Otevřete <span class='knopfwort'>Nastavení ▸ Magnolienbaum</span> a vyberte <span class='knopfwort'>Povolte připojení telefonu Magnolie Notes</span>. Pokud Organizer požádá o potřebné pravidlo brány firewall, potvrďte bezpečnostní výzvu Windows.</li><li>Připojte počítač a telefon ke stejné WLAN a klikněte na <span class='knopfwort'>Připojte telefon přes WLAN</span>.</li><li>V Magnolie Notes otevřete připojení telefonu a vyberte tento počítač.</li><li>Porovnejte šestimístný kód na obou zařízeních. Pokud se liší, klikněte na <span class='knopfwort'>Kódy se liší</span>. Pouze pokud je naprosto stejný, klikněte na <span class='knopfwort'>Kód se shoduje</span> a potvrďte jej v telefonu.</li></ol><p>Po bezpečném spárování telefonu se dialog zavře. Chcete-li telefon změnit, použijte nejprve u stávajícího telefonu <span class='knopfwort'>Odstranit připojení</span>.</p><h3>Volitelný záložní přenos dat přes Bluetooth</h3><p>Nejprve telefon spárujte ve Windows v části <i>Nastavení ▸ Bluetooth a zařízení</i>. Poté v Organizeru u spárovaného telefonu vyberte <span class='knopfwort'>Záložní data Bluetooth</span> a jeho systémově spárovanou adresu Bluetooth. Volba je zakázána, pokud Windows nehlásí použitelný adaptér, oprávnění, ovladač nebo podporu RFCOMM. WLAN má přednost; Bluetooth přenáší pouze šifrovaná data, nikoli zvuk HFP.</p><div class='achtung'><b>Odděleno od SMS</b>Vlastní telefonní připojení Magnolie neposílá SMS. SMS zůstávají samostatnou funkcí KDE Connect na <b data-page='kde-sms' class='knopfwort'></b>.</div>",
    "da": "<p><b>Telefonforbindelsen</b> forbinder denne Organizer direkte og krypteret med Magnolie Notes på præcis én telefon. Den er uafhængig af Magnolienbaum.</p><h3>Par én gang via WLAN</h3><ol class='schritte'><li>Åbn <span class='knopfwort'>Indstillinger ▸ Magnolienbaum</span>, og vælg <span class='knopfwort'>Aktiver Magnolie Notes telefonforbindelse</span>. Godkend Windows-sikkerhedsforespørgslen, hvis Organizeren beder om den nødvendige firewallregel.</li><li>Forbind computeren og telefonen til samme WLAN, og klik på <span class='knopfwort'>Forbind telefon via WLAN</span>.</li><li>Åbn telefonforbindelsen i Magnolie Notes, og vælg denne computer.</li><li>Sammenlign den sekscifrede kode på begge enheder. Klik på <span class='knopfwort'>Koderne er forskellige</span>, hvis den afviger. Klik kun på <span class='knopfwort'>Koderne er ens</span>, hvis den er helt ens, og bekræft på telefonen.</li></ol><p>Dialogen lukker, når telefonen er sikkert parret. Hvis du vil skifte telefon, skal du først bruge <span class='knopfwort'>Fjern telefonforbindelse</span> på den nuværende telefon.</p><h3>Valgfri Bluetooth-datareserve</h3><p>Par først telefonen i Windows under <i>Indstillinger ▸ Bluetooth og enheder</i>. Vælg derefter <span class='knopfwort'>Bluetooth-data som reserve</span> for den parrede telefon i Organizeren, og vælg dens systemparrede Bluetooth-adresse. Valget er deaktiveret, hvis Windows ikke melder en brugbar radio, tilladelse, driver eller RFCOMM-understøttelse. WLAN har prioritet; Bluetooth overfører kun krypterede data og ingen HFP-lyd.</p><div class='achtung'><b>Adskilt fra sms</b>Magnolies indbyggede telefonforbindelse sender ikke sms. Sms er fortsat en særskilt KDE Connect-funktion på <b data-page='kde-sms' class='knopfwort'></b>.</div>",
    "es": "<p>La <b>conexión telefónica</b> enlaza este Organizador directa y cifradamente con Magnolie Notes en un solo teléfono. Es independiente del Magnolienbaum.</p><h3>Emparejar una vez mediante WLAN</h3><ol class='schritte'><li>Abra <span class='knopfwort'>Ajustes ▸ Magnolienbaum</span> y marque <span class='knopfwort'>Habilitar la conexión telefónica Magnolie Notes</span>. Acepte el aviso de seguridad de Windows si el Organizador solicita la regla de cortafuegos necesaria.</li><li>Conecte el ordenador y el teléfono a la misma WLAN y haga clic en <span class='knopfwort'>Conectar el teléfono mediante WLAN</span>.</li><li>Abra la conexión telefónica en Magnolie Notes y seleccione este ordenador.</li><li>Compare el código de seis dígitos en ambos dispositivos. Si difiere, pulse <span class='knopfwort'>Los códigos no coinciden</span>. Solo si es exactamente igual, pulse <span class='knopfwort'>Los códigos coinciden</span> y confirme en el teléfono.</li></ol><p>El cuadro se cierra cuando el teléfono queda emparejado de forma segura. Para cambiar de teléfono, use primero <span class='knopfwort'>Eliminar la conexión del teléfono</span> en el teléfono actual.</p><h3>Alternativa opcional de datos Bluetooth</h3><p>Empareje primero el teléfono en Windows, en <i>Configuración ▸ Bluetooth y dispositivos</i>. Después marque <span class='knopfwort'>Datos Bluetooth como alternativa</span> para el teléfono emparejado en el Organizador y elija su dirección Bluetooth emparejada por el sistema. La opción estará desactivada si Windows no informa de radio, permiso, controlador o compatibilidad RFCOMM utilizables. WLAN tiene prioridad; Bluetooth solo transporta datos cifrados, no audio HFP.</p><div class='achtung'><b>Separada de los SMS</b>La conexión telefónica nativa de Magnolie no envía SMS. Los SMS siguen siendo una función independiente de KDE Connect en <b data-page='kde-sms' class='knopfwort'></b>.</div>",
    "fr": "<p>La <b>connexion téléphonique</b> relie directement et de façon chiffrée cet Organizer à Magnolie Notes sur un seul téléphone. Elle est indépendante du Magnolienbaum.</p><h3>Appairer une fois par WLAN</h3><ol class='schritte'><li>Ouvrez <span class='knopfwort'>Paramètres ▸ Magnolienbaum</span> et cochez <span class='knopfwort'>Activer la connexion téléphonique Magnolie Notes</span>. Acceptez l’invite de sécurité Windows si l’Organizer demande la règle de pare-feu nécessaire.</li><li>Connectez l’ordinateur et le téléphone au même WLAN, puis cliquez sur <span class='knopfwort'>Connecter le téléphone par WLAN</span>.</li><li>Ouvrez la connexion téléphonique dans Magnolie Notes et sélectionnez cet ordinateur.</li><li>Comparez le code à six chiffres sur les deux appareils. S’il diffère, cliquez sur <span class='knopfwort'>Les codes diffèrent</span>. Uniquement s’il est strictement identique, cliquez sur <span class='knopfwort'>Les codes correspondent</span> et confirmez sur le téléphone.</li></ol><p>La boîte de dialogue se ferme lorsque le téléphone est appairé de façon sécurisée. Pour changer de téléphone, utilisez d’abord <span class='knopfwort'>Supprimer la connexion téléphonique</span> pour le téléphone actuel.</p><h3>Repli facultatif des données sur le Bluetooth</h3><p>Appairez d’abord le téléphone dans Windows sous <i>Paramètres ▸ Bluetooth et appareils</i>. Cochez ensuite <span class='knopfwort'>Repli des données sur le Bluetooth</span> pour le téléphone appairé dans l’Organizer et choisissez son adresse Bluetooth appairée par le système. L’option est désactivée si Windows ne signale pas de radio, autorisation, pilote ou prise en charge RFCOMM utilisable. Le WLAN est prioritaire ; le Bluetooth ne transporte que des données chiffrées, sans son HFP.</p><div class='achtung'><b>Séparée des SMS</b>La connexion téléphonique native de Magnolie n’envoie pas de SMS. Les SMS restent une fonction KDE Connect distincte sur <b data-page='kde-sms' class='knopfwort'></b>.</div>",
    "hi": "<p><b>फ़ोन कनेक्शन</b> इस Organizer को ठीक एक फ़ोन पर Magnolie Notes से सीधे और एन्क्रिप्टेड रूप में जोड़ता है। यह Magnolienbaum से स्वतंत्र है।</p><h3>WLAN पर एक बार पेयर करें</h3><ol class='schritte'><li><span class='knopfwort'>सेटिंग्स ▸ Magnolienbaum</span> खोलें और <span class='knopfwort'>Magnolie Notes फ़ोन कनेक्शन सक्षम करें</span> चुनें। यदि Organizer आवश्यक फ़ायरवॉल नियम माँगे, तो Windows सुरक्षा संकेत स्वीकार करें।</li><li>कंप्यूटर और फ़ोन को एक ही WLAN से जोड़ें और <span class='knopfwort'>फोन को WLAN के माध्यम से कनेक्ट करें</span> पर क्लिक करें।</li><li>Magnolie Notes में फ़ोन कनेक्शन खोलें और यह कंप्यूटर चुनें।</li><li>दोनों डिवाइस पर छह अंकों का कोड मिलाएँ। अलग होने पर <span class='knopfwort'>कोड अलग हैं</span> पर क्लिक करें। बिल्कुल समान होने पर ही <span class='knopfwort'>कोड मेल खाता है</span> पर क्लिक करके फ़ोन पर पुष्टि करें।</li></ol><p>फ़ोन सुरक्षित रूप से पेयर होते ही संवाद बंद हो जाता है। फ़ोन बदलने से पहले मौजूदा फ़ोन के लिए <span class='knopfwort'>कनेक्शन हटाएँ</span> इस्तेमाल करें।</p><h3>वैकल्पिक Bluetooth डेटा फ़ॉलबैक</h3><p>पहले Windows में <i>सेटिंग्स ▸ Bluetooth और डिवाइस</i> के अंतर्गत फ़ोन पेयर करें। फिर Organizer में पेयर किए गए फ़ोन के लिए <span class='knopfwort'>Bluetooth डेटा फ़ॉलबैक</span> चुनें और उसका सिस्टम-पेयर Bluetooth पता चुनें। Windows से उपयोग योग्य रेडियो, अनुमति, ड्राइवर या RFCOMM समर्थन न मिलने पर विकल्प निष्क्रिय रहता है। WLAN को प्राथमिकता है; Bluetooth केवल एन्क्रिप्टेड डेटा ले जाता है, HFP ऑडियो नहीं।</p><div class='achtung'><b>SMS से अलग</b>मूल Magnolie फ़ोन कनेक्शन SMS नहीं भेजता। SMS <b data-page='kde-sms' class='knopfwort'></b> पर एक अलग KDE Connect सुविधा रहता है।</div>",
    "hsb": "<p><b>Telefonowy zwisk</b> zwjazuje tutón Organizer direktnje a zaklučowany z Magnolie Notes na runje jednym telefonje. Wón je wot Magnolienbaum njewotwisny.</p><h3>Jónkróć přez WLAN sparować</h3><ol class='schritte'><li>Wočińće <span class='knopfwort'>Nastajenja ▸ Magnolienbaum</span> a wubjerće <span class='knopfwort'>Telefonowy zwisk Magnolie Notes zmóžnić</span>. Wobkrućće wěstotne naprašowanje Windows, jeli Organizer trěbne prawidło wohnjoweje murje žada.</li><li>Zwjazajće kompjuter a telefon ze samsnym WLAN a klikńće na <span class='knopfwort'>Telefon přez WLAN zwjazać</span>.</li><li>Wočińće telefonowy zwisk w Magnolie Notes a wubjerće tutón kompjuter.</li><li>Přirunajće šěsćměstny kod na woběmaj gratomaj. Jeli so rozeznawa, klikńće na <span class='knopfwort'>Kody so rozeznawaja</span>. Jenož jeli je eksaktnje samsny, klikńće na <span class='knopfwort'>Kod so kryje</span> a wobkrućće na telefonje.</li></ol><p>Dialog so začini, hdyž je telefon wěsće sparowany. Zo byšće telefon wuměnili, wužiwajće najprjedy <span class='knopfwort'>Zwisk wotstronić</span> za dotalny telefon.</p><h3>Opcionalny Bluetoothowy wróćopad za daty</h3><p>Sparujće telefon najprjedy w Windows pod <i>Nastajenja ▸ Bluetooth a graty</i>. Wubjerće potom w Organizerje za sparowany telefon <span class='knopfwort'>Daty Bluetooth fallback</span> a jeho ze systemom sparowanu Bluetooth-adresu. Opcija je znjemóžnjena, jeli Windows žadyn wužiwajomny radio, dowolnosć, ćěrjak abo podpěru RFCOMM njezjewi. WLAN ma prioritu; Bluetooth přenošuje jenož zaklučowane daty, žadyn HFP-zynk.</p><div class='achtung'><b>Wot SMS dźělene</b>Swójski telefonowy zwisk Magnolie SMS njepósćele. SMS wostanje separatna funkcija KDE Connect na <b data-page='kde-sms' class='knopfwort'></b>.</div>",
    "it": "<p>Il <b>collegamento telefonico</b> connette questo Organizer direttamente e in modo cifrato a Magnolie Notes su un solo telefono. È indipendente dal Magnolienbaum.</p><h3>Abbinamento singolo tramite WLAN</h3><ol class='schritte'><li>Aprite <span class='knopfwort'>Impostazioni ▸ Magnolienbaum</span> e selezionate <span class='knopfwort'>Abilita la connessione telefonica Magnolie Notes</span>. Accettate la richiesta di sicurezza di Windows se l’Organizer richiede la regola firewall necessaria.</li><li>Collegate computer e telefono alla stessa WLAN e fate clic su <span class='knopfwort'>Connetti il telefono tramite WLAN</span>.</li><li>Aprite il collegamento telefonico in Magnolie Notes e selezionate questo computer.</li><li>Confrontate il codice a sei cifre sui due dispositivi. Se è diverso, fate clic su <span class='knopfwort'>I codici non corrispondono</span>. Solo se è perfettamente uguale, fate clic su <span class='knopfwort'>I codici corrispondono</span> e confermate sul telefono.</li></ol><p>La finestra si chiude quando il telefono è abbinato in modo sicuro. Per cambiare telefono, usate prima <span class='knopfwort'>Rimuovi connessione telefonica</span> per quello esistente.</p><h3>Ripiego facoltativo sui dati Bluetooth</h3><p>Abbinate prima il telefono in Windows, in <i>Impostazioni ▸ Bluetooth e dispositivi</i>. Selezionate quindi <span class='knopfwort'>Ripiego sui dati Bluetooth</span> per il telefono abbinato nell’Organizer e scegliete il suo indirizzo Bluetooth abbinato dal sistema. L’opzione è disabilitata se Windows non segnala radio, autorizzazione, driver o supporto RFCOMM utilizzabili. La WLAN ha la precedenza; Bluetooth trasporta solo dati cifrati, non audio HFP.</p><div class='achtung'><b>Separato dagli SMS</b>Il collegamento telefonico nativo Magnolie non invia SMS. Gli SMS restano una funzione KDE Connect separata su <b data-page='kde-sms' class='knopfwort'></b>.</div>",
    "ja": "<p><b>電話接続</b>は、この Organizer と 1 台だけのスマートフォン上の Magnolie Notes を直接、暗号化して接続します。Magnolienbaum とは独立しています。</p><h3>WLAN で一度ペアリングする</h3><ol class='schritte'><li><span class='knopfwort'>設定 ▸ Magnolienbaum</span> を開き、<span class='knopfwort'>Magnolie Notes 電話接続を有効にする</span> を選択します。Organizer が必要なファイアウォール規則を要求した場合は、Windows のセキュリティ確認を許可します。</li><li>コンピューターとスマートフォンを同じ WLAN に接続し、<span class='knopfwort'>電話をWi-Fiで接続する</span> をクリックします。</li><li>Magnolie Notes で電話接続を開き、このコンピューターを選択します。</li><li>両方の機器に表示された 6 桁のコードを比較します。異なる場合は <span class='knopfwort'>コードは異なる</span> をクリックします。完全に同じ場合だけ <span class='knopfwort'>コードが一致</span> をクリックし、スマートフォンでも確認します。</li></ol><p>安全なペアリングが完了するとダイアログが閉じます。スマートフォンを変更するには、まず現在のスマートフォンで <span class='knopfwort'>接続を削除</span> を使用します。</p><h3>任意の Bluetooth データフォールバック</h3><p>最初に Windows の <i>設定 ▸ Bluetooth とデバイス</i> でスマートフォンをペアリングします。次に Organizer でペアリング済みスマートフォンの <span class='knopfwort'>Bluetoothデータフォールバック</span> を選択し、システムでペアリングされた Bluetooth アドレスを選びます。使用可能な無線、許可、ドライバー、または RFCOMM 対応を Windows が報告しない場合、この項目は無効です。WLAN が優先され、Bluetooth は暗号化されたデータだけを伝送し、HFP 音声は伝送しません。</p><div class='achtung'><b>SMS とは別です</b>Magnolie 独自の電話接続は SMS を送信しません。SMS は <b data-page='kde-sms' class='knopfwort'></b> の独立した KDE Connect 機能です。</div>",
    "nb": "<p><b>Telefontilkoblingen</b> kobler denne Organizeren direkte og kryptert til Magnolie Notes på nøyaktig én telefon. Den er uavhengig av Magnolienbaum.</p><h3>Par én gang via WLAN</h3><ol class='schritte'><li>Åpne <span class='knopfwort'>Innstillinger ▸ Magnolienbaum</span>, og velg <span class='knopfwort'>Aktiver Magnolie Notes telefontilkobling</span>. Godkjenn sikkerhetsforespørselen fra Windows hvis Organizeren ber om den nødvendige brannmurregelen.</li><li>Koble datamaskinen og telefonen til samme WLAN, og klikk på <span class='knopfwort'>Koble til telefonen via WLAN</span>.</li><li>Åpne telefontilkoblingen i Magnolie Notes, og velg denne datamaskinen.</li><li>Sammenlign den sekssifrede koden på begge enhetene. Klikk på <span class='knopfwort'>Kodene er forskjellige</span> hvis den avviker. Bare hvis den er helt lik, klikker du på <span class='knopfwort'>Kodene er like</span> og bekrefter på telefonen.</li></ol><p>Dialogboksen lukkes når telefonen er sikkert paret. Hvis du vil bytte telefon, må du først bruke <span class='knopfwort'>Fjern telefontilkobling</span> for den nåværende telefonen.</p><h3>Valgfri Bluetooth-datareserve</h3><p>Par først telefonen i Windows under <i>Innstillinger ▸ Bluetooth og enheter</i>. Velg deretter <span class='knopfwort'>Bluetooth-data som reserve</span> for den parede telefonen i Organizeren, og velg den systemparede Bluetooth-adressen. Valget er deaktivert hvis Windows ikke rapporterer en brukbar radio, tillatelse, driver eller RFCOMM-støtte. WLAN har prioritet; Bluetooth overfører bare krypterte data, ikke HFP-lyd.</p><div class='achtung'><b>Adskilt fra SMS</b>Magnolies innebygde telefontilkobling sender ikke SMS. SMS forblir en separat KDE Connect-funksjon på <b data-page='kde-sms' class='knopfwort'></b>.</div>",
    "nl": "<p>De <b>telefoonverbinding</b> verbindt deze Organizer rechtstreeks en versleuteld met Magnolie Notes op precies één telefoon. Zij staat los van de Magnolienbaum.</p><h3>Eenmalig via WLAN koppelen</h3><ol class='schritte'><li>Open <span class='knopfwort'>Instellingen ▸ Magnolienbaum</span> en selecteer <span class='knopfwort'>Schakel Magnolie Notes-telefoonverbinding in</span>. Sta de Windows-beveiligingsvraag toe als de Organizer om de vereiste firewallregel vraagt.</li><li>Verbind computer en telefoon met hetzelfde WLAN en klik op <span class='knopfwort'>Telefoon via WLAN verbinden</span>.</li><li>Open de telefoonverbinding in Magnolie Notes en selecteer deze computer.</li><li>Vergelijk de zescijferige code op beide apparaten. Klik bij een afwijking op <span class='knopfwort'>Codes verschillen</span>. Klik alleen als de code exact gelijk is op <span class='knopfwort'>Codes komen overeen</span> en bevestig op de telefoon.</li></ol><p>Het venster sluit zodra de telefoon veilig is gekoppeld. Gebruik om van telefoon te wisselen eerst <span class='knopfwort'>Telefoonverbinding verwijderen</span> bij de huidige telefoon.</p><h3>Optionele Bluetooth-gegevens als terugvaloptie</h3><p>Koppel de telefoon eerst in Windows onder <i>Instellingen ▸ Bluetooth en apparaten</i>. Selecteer daarna bij de gekoppelde telefoon in de Organizer <span class='knopfwort'>Bluetooth-gegevens als terugvaloptie</span> en kies het door het systeem gekoppelde Bluetooth-adres. De optie is uitgeschakeld als Windows geen bruikbare radio, toestemming, driver of RFCOMM-ondersteuning meldt. WLAN heeft voorrang; Bluetooth vervoert alleen versleutelde gegevens en geen HFP-geluid.</p><div class='achtung'><b>Gescheiden van sms</b>De eigen Magnolie-telefoonverbinding verstuurt geen sms. Sms blijft een afzonderlijke KDE Connect-functie op <b data-page='kde-sms' class='knopfwort'></b>.</div>",
    "pl": "<p><b>Połączenie telefoniczne</b> łączy ten Organizer bezpośrednio i w sposób zaszyfrowany z Magnolie Notes na dokładnie jednym telefonie. Jest niezależne od Magnolienbaum.</p><h3>Jednorazowe parowanie przez WLAN</h3><ol class='schritte'><li>Otwórz <span class='knopfwort'>Ustawienia ▸ Magnolienbaum</span> i wybierz <span class='knopfwort'>Włącz połączenie telefoniczne Magnolie Notes</span>. Zaakceptuj monit zabezpieczeń Windows, jeśli Organizer poprosi o wymaganą regułę zapory.</li><li>Połącz komputer i telefon z tą samą siecią WLAN i kliknij <span class='knopfwort'>Połącz telefon przez WLAN</span>.</li><li>Otwórz połączenie telefoniczne w Magnolie Notes i wybierz ten komputer.</li><li>Porównaj sześciocyfrowy kod na obu urządzeniach. Jeśli jest inny, kliknij <span class='knopfwort'>Kody różnią się</span>. Tylko jeśli jest dokładnie taki sam, kliknij <span class='knopfwort'>Kod jest zgodny</span> i potwierdź na telefonie.</li></ol><p>Okno zamknie się po bezpiecznym sparowaniu telefonu. Aby zmienić telefon, najpierw użyj <span class='knopfwort'>Usuń połączenie</span> przy obecnym telefonie.</p><h3>Opcjonalne awaryjne przesyłanie danych przez Bluetooth</h3><p>Najpierw sparuj telefon w Windows w sekcji <i>Ustawienia ▸ Bluetooth i urządzenia</i>. Następnie wybierz <span class='knopfwort'>Awaryjne przesyłanie danych przez Bluetooth</span> przy sparowanym telefonie w Organizerze i jego adres Bluetooth sparowany przez system. Opcja jest wyłączona, jeśli Windows nie zgłasza użytecznego modułu, uprawnienia, sterownika lub obsługi RFCOMM. WLAN ma pierwszeństwo; Bluetooth przesyła tylko zaszyfrowane dane, bez dźwięku HFP.</p><div class='achtung'><b>Oddzielnie od SMS</b>Wbudowane połączenie telefoniczne Magnolie nie wysyła SMS-ów. SMS pozostaje osobną funkcją KDE Connect na <b data-page='kde-sms' class='knopfwort'></b>.</div>",
    "pt": "<p>A <b>ligação ao telefone</b> une este Organizador direta e cifradamente ao Magnolie Notes num único telefone. É independente do Magnolienbaum.</p><h3>Emparelhar uma vez por WLAN</h3><ol class='schritte'><li>Abra <span class='knopfwort'>Definições ▸ Magnolienbaum</span> e selecione <span class='knopfwort'>Habilitar conexão telefônica Magnolie Notes</span>. Aceite o pedido de segurança do Windows se o Organizador solicitar a regra de firewall necessária.</li><li>Ligue o computador e o telefone à mesma WLAN e clique em <span class='knopfwort'>Ligar o telefone por WLAN</span>.</li><li>Abra a ligação ao telefone no Magnolie Notes e selecione este computador.</li><li>Compare o código de seis algarismos nos dois dispositivos. Se for diferente, clique em <span class='knopfwort'>Os códigos são diferentes</span>. Apenas se for exatamente igual, clique em <span class='knopfwort'>Os códigos correspondem</span> e confirme no telefone.</li></ol><p>A caixa fecha-se quando o telefone fica emparelhado com segurança. Para mudar de telefone, utilize primeiro <span class='knopfwort'>Remover ligação ao telefone</span> no telefone atual.</p><h3>Recurso opcional a dados por Bluetooth</h3><p>Emparelhe primeiro o telefone no Windows em <i>Definições ▸ Bluetooth e dispositivos</i>. Depois selecione <span class='knopfwort'>Recurso a dados por Bluetooth</span> para o telefone emparelhado no Organizador e escolha o respetivo endereço Bluetooth emparelhado pelo sistema. A opção fica desativada se o Windows não indicar rádio, permissão, controlador ou suporte RFCOMM utilizáveis. A WLAN tem prioridade; o Bluetooth transporta apenas dados cifrados, sem som HFP.</p><div class='achtung'><b>Separada dos SMS</b>A ligação nativa ao telefone do Magnolie não envia SMS. Os SMS continuam a ser uma função KDE Connect separada em <b data-page='kde-sms' class='knopfwort'></b>.</div>",
    "ru": "<p><b>Подключение телефона</b> напрямую и в зашифрованном виде связывает этот Organizer с Magnolie Notes ровно на одном телефоне. Оно не зависит от Magnolienbaum.</p><h3>Однократное сопряжение по WLAN</h3><ol class='schritte'><li>Откройте <span class='knopfwort'>Параметры ▸ Magnolienbaum</span> и выберите <span class='knopfwort'>Включить телефонное соединение Magnolie Notes</span>. Подтвердите запрос безопасности Windows, если Organizer запросит необходимое правило брандмауэра.</li><li>Подключите компьютер и телефон к одной сети WLAN и нажмите <span class='knopfwort'>Подключите телефон через WLAN</span>.</li><li>Откройте подключение телефона в Magnolie Notes и выберите этот компьютер.</li><li>Сравните шестизначный код на обоих устройствах. Если он отличается, нажмите <span class='knopfwort'>Коды различаются</span>. Только если он полностью совпадает, нажмите <span class='knopfwort'>Код совпадает</span> и подтвердите на телефоне.</li></ol><p>После безопасного сопряжения телефона диалог закроется. Чтобы сменить телефон, сначала используйте <span class='knopfwort'>Удалить подключение</span> для текущего телефона.</p><h3>Необязательный резервный канал данных Bluetooth</h3><p>Сначала выполните сопряжение телефона в Windows в разделе <i>Параметры ▸ Bluetooth и устройства</i>. Затем выберите <span class='knopfwort'>Резервное копирование данных Bluetooth</span> для сопряжённого телефона в Organizer и его системный Bluetooth-адрес. Параметр недоступен, если Windows не сообщает о пригодном радиомодуле, разрешении, драйвере или поддержке RFCOMM. WLAN имеет приоритет; Bluetooth передаёт только зашифрованные данные, без звука HFP.</p><div class='achtung'><b>Отдельно от SMS</b>Собственное подключение телефона Magnolie не отправляет SMS. SMS остаются отдельной функцией KDE Connect на <b data-page='kde-sms' class='knopfwort'></b>.</div>",
    "tr": "<p><b>Telefon bağlantısı</b>, bu Organizer’ı tam olarak bir telefondaki Magnolie Notes’a doğrudan ve şifreli olarak bağlar. Magnolienbaum’dan bağımsızdır.</p><h3>WLAN üzerinden bir kez eşleştirme</h3><ol class='schritte'><li><span class='knopfwort'>Ayarlar ▸ Magnolienbaum</span> bölümünü açın ve <span class='knopfwort'>Magnolie Notes telefon bağlantısını etkinleştirin</span> seçeneğini belirleyin. Organizer gerekli güvenlik duvarı kuralını isterse Windows güvenlik istemini onaylayın.</li><li>Bilgisayarı ve telefonu aynı WLAN’a bağlayın ve <span class='knopfwort'>Telefonu WLAN üzerinden bağla</span> düğmesine tıklayın.</li><li>Magnolie Notes’ta telefon bağlantısını açın ve bu bilgisayarı seçin.</li><li>Her iki cihazdaki altı haneli kodu karşılaştırın. Farklıysa <span class='knopfwort'>Kodlar farklı</span> seçeneğine tıklayın. Yalnızca tamamen aynıysa <span class='knopfwort'>Kodlar eşleşiyor</span> seçeneğine tıklayın ve telefonda onaylayın.</li></ol><p>Telefon güvenli biçimde eşleştirildiğinde iletişim kutusu kapanır. Telefonu değiştirmek için önce mevcut telefonda <span class='knopfwort'>Telefon bağlantısını kaldır</span> seçeneğini kullanın.</p><h3>İsteğe bağlı Bluetooth veri yedeği</h3><p>Önce telefonu Windows’ta <i>Ayarlar ▸ Bluetooth ve cihazlar</i> altında eşleştirin. Ardından Organizer’da eşleştirilmiş telefon için <span class='knopfwort'>Bluetooth veri yedeği</span> seçeneğini belirleyin ve sistemle eşleştirilmiş Bluetooth adresini seçin. Windows kullanılabilir radyo, izin, sürücü veya RFCOMM desteği bildirmezse seçenek devre dışıdır. WLAN önceliklidir; Bluetooth yalnızca şifreli veri taşır, HFP sesi taşımaz.</p><div class='achtung'><b>SMS’ten ayrıdır</b>Yerel Magnolie telefon bağlantısı SMS göndermez. SMS, <b data-page='kde-sms' class='knopfwort'></b> sayfasındaki ayrı KDE Connect işlevi olarak kalır.</div>",
    "uk": "<p><b>Підключення телефона</b> безпосередньо й у зашифрованому вигляді з’єднує цей Organizer із Magnolie Notes лише на одному телефоні. Воно не залежить від Magnolienbaum.</p><h3>Одноразове сполучення через WLAN</h3><ol class='schritte'><li>Відкрийте <span class='knopfwort'>Налаштування ▸ Magnolienbaum</span> і виберіть <span class='knopfwort'>Увімкніть телефонне підключення Magnolie Notes</span>. Підтвердьте запит безпеки Windows, якщо Organizer попросить потрібне правило брандмауера.</li><li>Підключіть комп’ютер і телефон до однієї WLAN і натисніть <span class='knopfwort'>Підключіть телефон через WLAN</span>.</li><li>Відкрийте підключення телефона в Magnolie Notes і виберіть цей комп’ютер.</li><li>Порівняйте шестизначний код на обох пристроях. Якщо він відрізняється, натисніть <span class='knopfwort'>Коди відрізняються</span>. Лише якщо він цілком збігається, натисніть <span class='knopfwort'>Код збігається</span> і підтвердьте на телефоні.</li></ol><p>Після безпечного сполучення телефона діалог закриється. Щоб змінити телефон, спочатку скористайтеся <span class='knopfwort'>Видалити з’єднання</span> для поточного телефона.</p><h3>Необов’язковий резервний канал даних Bluetooth</h3><p>Спочатку сполучіть телефон у Windows у розділі <i>Налаштування ▸ Bluetooth і пристрої</i>. Потім виберіть <span class='knopfwort'>Резервний варіант даних Bluetooth</span> для сполученого телефона в Organizer і його системну Bluetooth-адресу. Параметр недоступний, якщо Windows не повідомляє про придатний радіомодуль, дозвіл, драйвер або підтримку RFCOMM. WLAN має пріоритет; Bluetooth передає лише зашифровані дані, без звуку HFP.</p><div class='achtung'><b>Окремо від SMS</b>Власне підключення телефона Magnolie не надсилає SMS. SMS залишається окремою функцією KDE Connect на <b data-page='kde-sms' class='knopfwort'></b>.</div>",
    "zh-cn": "<p><b>手机连接</b>会将此 Organizer 与仅一部手机上的 Magnolie Notes 直接加密连接。它独立于 Magnolienbaum。</p><h3>通过 WLAN 配对一次</h3><ol class='schritte'><li>打开<span class='knopfwort'>设置 ▸ Magnolienbaum</span>并选择<span class='knopfwort'>启用 Magnolie Notes 电话连接</span>。如果 Organizer 请求所需的防火墙规则，请批准 Windows 安全提示。</li><li>将电脑和手机连接到同一 WLAN，然后单击<span class='knopfwort'>通过无线局域网连接手机</span>。</li><li>在 Magnolie Notes 中打开手机连接并选择此电脑。</li><li>比较两台设备上的六位代码。如果不同，请单击<span class='knopfwort'>代码不同</span>。仅当代码完全相同时，才单击<span class='knopfwort'>代码一致</span>并在手机上确认。</li></ol><p>手机安全配对后，对话框会关闭。若要更换手机，请先对当前手机使用<span class='knopfwort'>移除连接</span>。</p><h3>可选的 Bluetooth 数据回退</h3><p>首先在 Windows 的<i>设置 ▸ Bluetooth 和设备</i>中配对手机。然后在 Organizer 中为已配对手机选择<span class='knopfwort'>Bluetooth 数据回退</span>，并选择其系统配对的 Bluetooth 地址。如果 Windows 未报告可用的无线设备、权限、驱动程序或 RFCOMM 支持，该选项将被禁用。WLAN 优先；Bluetooth 仅传输加密数据，不传输 HFP 音频。</p><div class='achtung'><b>与短信分开</b>Magnolie 原生手机连接不发送短信。短信仍是 <b data-page='kde-sms' class='knopfwort'></b> 上单独的 KDE Connect 功能。</div>"
  },
  "platform-security-matrix": {
    "en": "<h3>Windows desktop</h3><p>Organizer role; Wi-Fi plus conditionally available RFCOMM when Windows grants Bluetooth access, an enabled radio is present, and the phone is paired in Windows system settings. Windows consent, hardware, driver, or operating-system policy can instead report <b>permission_missing</b>, <b>no_hardware</b>, <b>disabled</b>, or <b>os_restricted</b>. KDE Connect SMS and granted dial, incoming-call, answer, and end controls are supported. Receiving selected Android app notifications (<b>selected_notifications_readonly</b>) is currently <b>not_implemented</b> on Windows. Windows Contacts and optional Microsoft Graph with a DPAPI-protected refresh token are supported.</p><h3>Android phone</h3><p>Magnolie Notes role; Wi-Fi plus RFCOMM fallback; permitted call actions, but no HFP audio or native Magnolie SMS. Android permissions and roles can restrict contacts and calls. Cloud backup is disabled. The encrypted recovery journal is <b>not a backup</b>: it remains inside app data and is unavailable after clearing app data, uninstalling Magnolie Notes, or losing the device.</p><div class='achtung'><b>Backup and encryption scope</b>Main-data backups exclude phone identity, peers, <b>phone.db</b>, KDE pairing, Magnolienbaum queues, and Android data. The Windows Magnolienbaum files <b>baum.json</b>, <b>baum-post.json</b>, and <b>baum-eingang.json</b> are not encrypted by the main Organizer password. Protect the Windows account and back them up deliberately; never publish keys or diagnostic databases.</div>",
    "de": "<h3>Windows-Desktop</h3><p>Organizer-Rolle; WLAN sowie bedingt verfügbares RFCOMM, wenn Windows den Bluetooth-Zugriff erlaubt, ein eingeschaltetes Funkgerät vorhanden und das Telefon in den Windows-Systemeinstellungen gekoppelt ist. Windows-Zustimmung, Hardware, Treiber oder Betriebssystemrichtlinien können stattdessen <b>permission_missing</b>, <b>no_hardware</b>, <b>disabled</b> oder <b>os_restricted</b> melden. SMS über KDE Connect sowie freigegebene Aktionen für Wählen, eingehende Anrufe, Annehmen und Beenden werden unterstützt. Der Empfang ausgewählter Android-App-Benachrichtigungen (<b>selected_notifications_readonly</b>) ist unter Windows derzeit <b>not_implemented</b>. Windows-Kontakte und optional Microsoft Graph mit DPAPI-geschütztem Aktualisierungstoken werden unterstützt.</p><h3>Android-Telefon</h3><p>Magnolie-Notes-Rolle; WLAN plus RFCOMM-Rückfallweg; erlaubte Anrufaktionen, jedoch kein HFP-Ton und keine nativen Magnolie-SMS. Android-Berechtigungen und -Rollen können Kontakte und Anrufe einschränken. Die Cloud-Sicherung ist deaktiviert. Das verschlüsselte Wiederherstellungsjournal ist <b>keine Sicherung</b>: Es verbleibt in den App-Daten und ist nach dem Löschen der App-Daten, der Deinstallation von Magnolie Notes oder dem Verlust des Geräts nicht verfügbar.</p><div class='achtung'><b>Sicherungs- und Verschlüsselungsumfang</b>Hauptdatensicherungen enthalten Telefonidentität, Partner, <b>phone.db</b>, KDE-Paarung, Magnolienbaum-Warteschlangen und Android-Daten nicht. Die Windows-Magnolienbaum-Dateien <b>baum.json</b>, <b>baum-post.json</b> und <b>baum-eingang.json</b> werden nicht durch das Hauptkennwort des Organizers verschlüsselt. Schützen Sie das Windows-Konto und sichern Sie sie bewusst; veröffentlichen Sie niemals Schlüssel oder Diagnosedatenbanken.</div>",
    "ar": "<h3>سطح مكتب Windows</h3><p>دور Organizer؛ نقل الهاتف عبر WiFi؛ RFCOMM <b dir='ltr'>os_restricted</b>؛ رسائل SMS عبر KDE Connect؛ عناصر التحكم الممنوحة للاتصال والمكالمات الواردة والرد والإنهاء؛ وجهات اتصال Windows وMicrosoft Graph الاختياري مع رمز تحديث محمي بواسطة DPAPI.</p><h3>هاتف Android</h3><p>دور Magnolie Notes؛ WiFi وإجراءات المكالمات المسموح بها، لكن من دون صوت HFP أو رسائل SMS أصلية من Magnolie. قد تقيد أذونات Android وأدواره جهات الاتصال والمكالمات.</p><div class='achtung'><b>نطاق النسخ الاحتياطي والتشفير</b>تستثني النسخ الاحتياطية للبيانات الرئيسية معرّف الهاتف والأقران و<b dir='ltr'>phone.db</b> واقتران KDE وقوائم انتظار Magnolienbaum. ولا تُشفّر ملفات Magnolienbaum في Windows، وهي <b dir='ltr'>baum.json</b> و<b dir='ltr'>baum-post.json</b> و<b dir='ltr'>baum-eingang.json</b>، بواسطة كلمة مرور Organizer الرئيسية. احم حساب Windows وانسخها احتياطيا عن قصد.</div>",
    "be": "<h3>Камп’ютар з Windows</h3><p>Роля Organizer; перадача даных тэлефона праз WiFi; RFCOMM: <b>os_restricted</b>; SMS праз KDE Connect; дазволенае кіраванне наборам нумара, уваходнымі выклікамі, адказам і завяршэннем выкліку; Кантакты Windows і неабавязковае падключэнне Microsoft Graph з абароненым DPAPI токенам абнаўлення.</p><h3>Тэлефон Android</h3><p>Роля Magnolie Notes; WiFi і дазволеныя дзеянні з выклікамі, але без гуку HFP і ўласных SMS Magnolie. Дазволы і ролі Android могуць абмяжоўваць доступ да кантактаў і выклікаў.</p><div class='achtung'><b>Межы рэзервовага капіравання і шыфравання</b>Рэзервовыя копіі асноўных даных не змяшчаюць ідэнтыфікатар тэлефона, спалучаныя прылады, <b>phone.db</b>, спалучэнне KDE і чэргі Magnolienbaum. Файлы Magnolienbaum для Windows <b>baum.json</b>, <b>baum-post.json</b> і <b>baum-eingang.json</b> не шыфруюцца асноўным паролем Organizer. Абараняйце ўліковы запіс Windows і свядома стварайце рэзервовыя копіі гэтых файлаў.</div>",
    "cs": "<h3>Počítač se systémem Windows</h3><p>Role Organizeru; přenos dat telefonu přes WiFi; RFCOMM <b>os_restricted</b>; SMS přes KDE Connect; povolené ovládání vytáčení, příchozího hovoru, přijetí a ukončení; Kontakty Windows a volitelně Microsoft Graph s obnovovacím tokenem chráněným pomocí DPAPI.</p><h3>Telefon s Androidem</h3><p>Role Magnolie Notes; WiFi a povolené akce hovorů, avšak bez zvuku HFP a nativních SMS Magnolie. Oprávnění a role Androidu mohou omezit kontakty a hovory.</p><div class='achtung'><b>Rozsah záloh a šifrování</b>Zálohy hlavních dat nezahrnují identitu telefonu, protějšky, <b>phone.db</b>, párování KDE ani fronty Magnolienbaum. Soubory Magnolienbaum ve Windows <b>baum.json</b>, <b>baum-post.json</b> a <b>baum-eingang.json</b> nejsou šifrovány hlavním heslem Organizeru. Chraňte účet Windows a záměrně je zálohujte.</div>",
    "da": "<h3>Windows-skrivebord</h3><p>Organizer-rolle; telefontransport via wi-fi; RFCOMM <b>os_restricted</b>; sms via KDE Connect; givne styringer for opkald, indgående opkald, besvarelse og afslutning; Windows-kontakter og valgfrit Microsoft Graph med DPAPI-beskyttet opdateringstoken.</p><h3>Android-telefon</h3><p>Magnolie Notes-rolle; wi-fi og tilladte opkaldshandlinger, men ingen HFP-lyd og ingen indbyggede Magnolie-sms'er. Androids tilladelser og roller kan begrænse kontakter og opkald.</p><div class='achtung'><b>Omfang af sikkerhedskopi og kryptering</b>Sikkerhedskopier af hoveddata omfatter ikke telefonidentitet, modparter, <b>phone.db</b>, KDE-parring og Magnolienbaum-køer. Windows-Magnolienbaum-filerne <b>baum.json</b>, <b>baum-post.json</b> og <b>baum-eingang.json</b> krypteres ikke med Organizerens hovedadgangskode. Beskyt Windows-kontoen, og sikr dem bevidst.</div>",
    "es": "<h3>Escritorio de Windows</h3><p>Rol de Organizador; transporte del teléfono por WiFi; RFCOMM <b>os_restricted</b>; SMS mediante KDE Connect; controles concedidos de marcación, llamada entrante, descolgar y colgar; Contactos de Windows y, opcionalmente, Microsoft Graph con token de actualización protegido por DPAPI.</p><h3>Teléfono Android</h3><p>Rol de Magnolie Notes; WiFi y acciones de llamada permitidas, pero sin sonido HFP ni SMS nativos de Magnolie. Los permisos y roles de Android pueden restringir los contactos y las llamadas.</p><div class='achtung'><b>Alcance de la copia de seguridad y del cifrado</b>Las copias de seguridad de los datos principales excluyen la identidad del teléfono, los pares, <b>phone.db</b>, el emparejamiento de KDE y las colas del Magnolienbaum. Los ficheros del Magnolienbaum en Windows <b>baum.json</b>, <b>baum-post.json</b> y <b>baum-eingang.json</b> no se cifran con la contraseña principal del Organizador. Proteja la cuenta de Windows y guárdelos de forma deliberada.</div>",
    "fr": "<h3>Bureau Windows</h3><p>Rôle Organizer ; transport téléphonique par WiFi ; RFCOMM <b>os_restricted</b> ; SMS via KDE Connect ; commandes accordées de composition, d’appel entrant, de prise et de fin d’appel ; Contacts Windows et, en option, Microsoft Graph avec jeton d’actualisation protégé par DPAPI.</p><h3>Téléphone Android</h3><p>Rôle Magnolie Notes ; WiFi et actions d’appel autorisées, mais pas de son HFP ni de SMS Magnolie natifs. Les autorisations et les rôles Android peuvent restreindre les contacts et les appels.</p><div class='achtung'><b>Étendue de la sauvegarde et du chiffrement</b>Les sauvegardes des données principales excluent l’identité du téléphone, les partenaires, <b>phone.db</b>, l’appairage KDE et les files d’attente du Magnolienbaum. Les fichiers Magnolienbaum de Windows <b>baum.json</b>, <b>baum-post.json</b> et <b>baum-eingang.json</b> ne sont pas chiffrés par le mot de passe principal de l’Organizer. Protégez le compte Windows et sauvegardez-les de manière délibérée.</div>",
    "hi": "<h3>Windows डेस्कटॉप</h3><p>Organizer भूमिका; WiFi फ़ोन परिवहन; RFCOMM <b>os_restricted</b>; KDE Connect SMS; स्वीकृत डायल, आने वाली कॉल, उत्तर और समाप्ति नियंत्रण; Windows Contacts और DPAPI-सुरक्षित रिफ़्रेश टोकन वाला वैकल्पिक Microsoft Graph।</p><h3>Android फ़ोन</h3><p>Magnolie Notes भूमिका; WiFi और अनुमत कॉल क्रियाएँ, लेकिन HFP ऑडियो और मूल Magnolie SMS नहीं। Android अनुमतियाँ और भूमिकाएँ संपर्कों और कॉल को सीमित कर सकती हैं।</p><div class='achtung'><b>बैकअप और एन्क्रिप्शन का दायरा</b>मुख्य डेटा बैकअप में फ़ोन पहचान, पीयर, <b>phone.db</b>, KDE युग्मन और Magnolienbaum कतारें शामिल नहीं हैं। Windows की Magnolienbaum फ़ाइलें <b>baum.json</b>, <b>baum-post.json</b> और <b>baum-eingang.json</b> मुख्य Organizer पासवर्ड से एन्क्रिप्टेड नहीं हैं। Windows खाते की रक्षा करें और सोच-समझकर उनका बैकअप लें।</div>",
    "hsb": "<h3>Windowsowy desktop</h3><p>Róla Organizera; telefonowy přenos přez WiFi; RFCOMM <b>os_restricted</b>; SMS přez KDE Connect; dowolene wodźenje wuzwolenja, dochadźaceho zawołanja, přiwzaća a skónčenja; Kontakty Windows a opcionalny Microsoft Graph z přez DPAPI škitanym wobnowjenskim tokenom.</p><h3>Telefon z Androidom</h3><p>Róla Magnolie Notes; WiFi a dowolene zawołanske akcije, ale bjez HFP-zynka a bjez swójskich SMS Magnolie. Dowolnosće a róle Androida móža kontakty a zawołanja wobmjezować.</p><div class='achtung'><b>Wobłuk zawěsćenja a zaklučowanja</b>Hłownodatowe zawěsćenja njewobsahuja identitu telefona, partnerow, <b>phone.db</b>, sparowanje KDE ani čakanske linki Magnolienbaum. Dataje Magnolienbaum pod Windows <b>baum.json</b>, <b>baum-post.json</b> a <b>baum-eingang.json</b> so z hłownym hesłom Organizera njezaklučuja. Škitajće konto Windows a zawěsćće je swědomiće.</div>",
    "it": "<h3>Desktop Windows</h3><p>Ruolo Organizer; trasporto del telefono via WiFi; RFCOMM <b>os_restricted</b>; SMS tramite KDE Connect; controlli concessi di composizione, chiamata in arrivo, risposta e chiusura; Contatti di Windows e, facoltativamente, Microsoft Graph con token di aggiornamento protetto da DPAPI.</p><h3>Telefono Android</h3><p>Ruolo Magnolie Notes; WiFi e azioni di chiamata consentite, ma nessun audio HFP e nessun SMS Magnolie nativo. Le autorizzazioni e i ruoli di Android possono limitare contatti e chiamate.</p><div class='achtung'><b>Portata di backup e cifratura</b>I backup dei dati principali escludono identità del telefono, peer, <b>phone.db</b>, accoppiamento KDE e code del Magnolienbaum. I file Magnolienbaum di Windows <b>baum.json</b>, <b>baum-post.json</b> e <b>baum-eingang.json</b> non sono cifrati dalla password principale dell'Organizer. Proteggete l'account Windows e salvateli consapevolmente.</div>",
    "ja": "<h3>Windows デスクトップ</h3><p>Organizer の役割。スマートフォンとの通信には WiFi を使用します。RFCOMM は <b>os_restricted</b> です。KDE Connect による SMS、および許可された発信、着信、応答、通話終了の操作に対応します。Windows の連絡先と、DPAPI で更新トークンを保護するオプションの Microsoft Graph にも対応します。</p><h3>Android スマートフォン</h3><p>Magnolie Notes の役割。WiFi と許可された通話操作に対応しますが、HFP 音声と Magnolie 独自の SMS には対応しません。Android の権限とロールによって、連絡先や通話が制限される場合があります。</p><div class='achtung'><b>バックアップと暗号化の対象範囲</b>メインデータのバックアップには、電話 ID、ピア、<b>phone.db</b>、KDE ペアリング、Magnolienbaum キューは含まれません。Windows の Magnolienbaum ファイル <b>baum.json</b>、<b>baum-post.json</b>、<b>baum-eingang.json</b> は、Organizer のメインパスワードでは暗号化されません。Windows アカウントを保護し、これらのファイルは必ず別途バックアップしてください。</div>",
    "nb": "<h3>Windows-skrivebord</h3><p>Organizer-rolle; Wi-Fi pluss betinget tilgjengelig RFCOMM når Windows gir Bluetooth-tilgang, en aktivert radio finnes, og telefonen er paret i systeminnstillingene i Windows. Windows-samtykke, maskinvare, driver eller operativsystempolicy kan i stedet melde <b>permission_missing</b>, <b>no_hardware</b>, <b>disabled</b> eller <b>os_restricted</b>. KDE Connect-SMS og tillatte funksjoner for oppringing, innkommende anrop, svar og avslutning støttes. Mottak av utvalgte Android-appvarsler (<b>selected_notifications_readonly</b>) er for øyeblikket <b>not_implemented</b> på Windows. Windows-kontakter og valgfri Microsoft Graph med et DPAPI-beskyttet refresh token støttes.</p><h3>Android-telefon</h3><p>Magnolie Notes-rolle; Wi-Fi pluss RFCOMM-reserve; tillatte anropshandlinger, men ingen HFP-lyd eller innebygd Magnolie-SMS. Android-tillatelser og -roller kan begrense kontakter og anrop. Cloud backup er deaktivert. Den krypterte gjenopprettingsjournalen er <b>ikke en sikkerhetskopi</b>: den forblir i appdata og er utilgjengelig etter sletting av appdata, avinstallering av Magnolie Notes eller tap av enheten.</p><div class='achtung'><b>Omfang av sikkerhetskopiering og kryptering</b>Sikkerhetskopier av hoveddata utelukker telefonidentitet, peers, <b>phone.db</b>, KDE-paring, Magnolienbaum-køer og Android-data. Windows-Magnolienbaum-filene <b>baum.json</b>, <b>baum-post.json</b> og <b>baum-eingang.json</b> krypteres ikke av Organizerens hovedpassord. Beskytt Windows-kontoen, og sikkerhetskopier dem bevisst; publiser aldri nøkler eller diagnosedatabaser.</div>",
    "nl": "<h3>Windows-bureaublad</h3><p>Organizer-rol; telefoontransport via wifi; RFCOMM <b>os_restricted</b>; sms via KDE Connect; verleende besturing voor bellen, inkomende oproep, opnemen en beëindigen; Windows-contacten en desgewenst Microsoft Graph met door DPAPI beschermd vernieuwingstoken.</p><h3>Android-telefoon</h3><p>Magnolie Notes-rol; wifi en toegestane oproepacties, maar geen HFP-geluid en geen eigen Magnolie-sms. Rechten en rollen van Android kunnen contacten en oproepen beperken.</p><div class='achtung'><b>Reikwijdte van back-up en versleuteling</b>Back-ups van de hoofdgegevens bevatten geen telefoonidentiteit, peers, <b>phone.db</b>, KDE-koppeling en Magnolienbaum-wachtrijen. De Windows-Magnolienbaum-bestanden <b>baum.json</b>, <b>baum-post.json</b> en <b>baum-eingang.json</b> worden niet versleuteld met het hoofdwachtwoord van de Organizer. Beveilig het Windows-account en stel ze bewust veilig.</div>",
    "pl": "<h3>Komputer z Windows</h3><p>Rola Organizera; przesyłanie danych telefonu przez WiFi; RFCOMM <b>os_restricted</b>; SMS-y przez KDE Connect; dozwolone sterowanie wybieraniem numeru, połączeniem przychodzącym, odbieraniem i kończeniem; Kontakty Windows i opcjonalny Microsoft Graph z tokenem odświeżania chronionym przez DPAPI.</p><h3>Telefon z Androidem</h3><p>Rola Magnolie Notes; WiFi i dozwolone działania dotyczące połączeń, ale bez dźwięku HFP i natywnych SMS-ów Magnolie. Uprawnienia i role Androida mogą ograniczać kontakty i połączenia.</p><div class='achtung'><b>Zakres kopii zapasowych i szyfrowania</b>Kopie głównych danych nie obejmują tożsamości telefonu, urządzeń równorzędnych, <b>phone.db</b>, parowania KDE ani kolejek Magnolienbaum. Pliki Magnolienbaum w systemie Windows <b>baum.json</b>, <b>baum-post.json</b> i <b>baum-eingang.json</b> nie są szyfrowane głównym hasłem Organizera. Chroń konto Windows i świadomie twórz ich kopie zapasowe.</div>",
    "pt": "<h3>Ambiente de trabalho Windows</h3><p>Papel de Organizador; transporte do telemóvel por WiFi; RFCOMM <b>os_restricted</b>; SMS através do KDE Connect; controlos concedidos de marcação, chamada recebida, atendimento e fim de chamada; Contactos do Windows e, opcionalmente, Microsoft Graph com token de atualização protegido por DPAPI.</p><h3>Telemóvel Android</h3><p>Papel de Magnolie Notes; WiFi e ações de chamada permitidas, mas sem som HFP e sem SMS nativos do Magnolie. As permissões e os papéis do Android podem restringir contactos e chamadas.</p><div class='achtung'><b>Alcance da cópia de segurança e da cifragem</b>As cópias de segurança dos dados principais excluem a identidade do telemóvel, os pares, o <b>phone.db</b>, o emparelhamento KDE e as filas do Magnolienbaum. Os ficheiros Magnolienbaum do Windows <b>baum.json</b>, <b>baum-post.json</b> e <b>baum-eingang.json</b> não são cifrados com a palavra-passe principal do Organizador. Proteja a conta do Windows e guarde-os deliberadamente.</div>",
    "ru": "<h3>Компьютер с Windows</h3><p>Роль Organizer; передача данных телефона по WiFi; RFCOMM: <b>os_restricted</b>; SMS через KDE Connect; разрешённое управление набором номера, входящими звонками, ответом и завершением звонка; Контакты Windows и необязательное подключение Microsoft Graph с защищённым DPAPI токеном обновления.</p><h3>Телефон Android</h3><p>Роль Magnolie Notes; WiFi и разрешённые действия со звонками, но без звука HFP и собственных SMS Magnolie. Разрешения и роли Android могут ограничивать доступ к контактам и звонкам.</p><div class='achtung'><b>Объём резервного копирования и шифрования</b>Резервные копии основных данных не включают идентификатор телефона, сопряжённые устройства, <b>phone.db</b>, сопряжение KDE и очереди Magnolienbaum. Файлы Magnolienbaum для Windows <b>baum.json</b>, <b>baum-post.json</b> и <b>baum-eingang.json</b> не шифруются основным паролем Organizer. Защищайте учётную запись Windows и сознательно создавайте резервные копии этих файлов.</div>",
    "tr": "<h3>Windows masaüstü</h3><p>Organizer rolü; WiFi telefon aktarımı; RFCOMM <b>os_restricted</b>; KDE Connect SMS; izin verilen arama, gelen arama, yanıtlama ve sonlandırma denetimleri; Windows Contacts ve DPAPI korumalı yenileme belirteciyle isteğe bağlı Microsoft Graph.</p><h3>Android telefon</h3><p>Magnolie Notes rolü; WiFi ve izin verilen arama eylemleri, ancak HFP sesi ve yerel Magnolie SMS yoktur. Android izinleri ve rolleri kişileri ve aramaları kısıtlayabilir.</p><div class='achtung'><b>Yedekleme ve şifreleme kapsamı</b>Ana veri yedekleri telefon kimliğini, eşleri, <b>phone.db</b> dosyasını, KDE eşleştirmesini ve Magnolienbaum kuyruklarını içermez. Windows Magnolienbaum dosyaları <b>baum.json</b>, <b>baum-post.json</b> ve <b>baum-eingang.json</b>, ana Organizer parolasıyla şifrelenmez. Windows hesabını koruyun ve bunları bilinçli olarak yedekleyin.</div>",
    "uk": "<h3>Комп’ютер із Windows</h3><p>Роль Organizer; передавання даних телефона через WiFi; RFCOMM: <b>os_restricted</b>; SMS через KDE Connect; дозволене керування набором номера, вхідними викликами, відповіддю та завершенням виклику; Контакти Windows і необов’язкове підключення Microsoft Graph із захищеним DPAPI токеном оновлення.</p><h3>Телефон Android</h3><p>Роль Magnolie Notes; WiFi і дозволені дії з викликами, але без звуку HFP і власних SMS Magnolie. Дозволи й ролі Android можуть обмежувати доступ до контактів і викликів.</p><div class='achtung'><b>Обсяг резервного копіювання та шифрування</b>Резервні копії основних даних не містять ідентифікатора телефона, сполучених пристроїв, <b>phone.db</b>, сполучення KDE та черг Magnolienbaum. Файли Magnolienbaum для Windows <b>baum.json</b>, <b>baum-post.json</b> і <b>baum-eingang.json</b> не шифруються основним паролем Organizer. Захищайте обліковий запис Windows і свідомо створюйте резервні копії цих файлів.</div>",
    "zh-cn": "<h3>Windows 桌面</h3><p>Organizer 角色；通过 WiFi 与手机通信；RFCOMM 状态为 <b>os_restricted</b>；支持 KDE Connect 短信，以及已授权的拨号、来电、接听和挂断控制；支持 Windows 联系人，也可通过 Microsoft Graph 同步，并使用 DPAPI 保护刷新令牌。</p><h3>Android 手机</h3><p>Magnolie Notes 角色；支持 WiFi 和已获授权的通话操作，但不支持 HFP 音频，也不支持 Magnolie 原生短信。Android 权限和角色可能限制联系人和通话功能。</p><div class='achtung'><b>备份和加密范围</b>主数据备份不包括手机身份、对等设备、<b>phone.db</b>、KDE 配对和 Magnolienbaum 队列。Windows 上的 Magnolienbaum 文件 <b>baum.json</b>、<b>baum-post.json</b> 和 <b>baum-eingang.json</b> 不受 Organizer 主密码加密。请保护 Windows 账户，并务必单独备份这些文件。</div>"
  }
};

  const installerName = "Magnolie-Organizer-Windows-2.0.14-Setup-x64.exe";
  for (const locale of Object.keys(variants["installing-the-organizer"])) {
    variants["installing-the-organizer"][locale] =
      variants["installing-the-organizer"][locale].replace(
        /Magnolie-Organizer-Windows-\d+\.\d+\.\d+-Setup-x64\.exe/g,
        installerName);
  }

  function applyWindowsVariants() {
    const locale = window.MagnolieI18n.locale().replace(/_/g, "-").toLowerCase();
    for (const page of window.HANDBUCH_SEITEN || []) {
      const variant = variants[page.id];
      if (variant) {
        if (!Object.prototype.hasOwnProperty.call(variant, locale)) {
          throw new Error(`Windows handbook variant ${page.id} is missing for ${locale}`);
        }
        page.inhalt = variant[locale];
      }
    }
  }

  applyWindowsVariants();
  document.addEventListener("magnolie-locale-changed", applyWindowsVariants);
})();
